import pytest

import jwt
from jwt.exceptions import MissingRequiredClaimError


KEY = "test-secret"


def make_token(payload):
    return jwt.encode(payload, KEY, algorithm="HS256")


def decode(token, **kwargs):
    return jwt.decode(token, KEY, algorithms=["HS256"], **kwargs)


def test_null_audience_is_accepted_when_no_audience_is_requested():
    token = make_token({"sub": "user", "aud": None})

    assert decode(token) == {"sub": "user", "aud": None}


@pytest.mark.parametrize("audience", ["expected-audience", ["expected-audience"]])
def test_null_audience_has_same_behavior_as_absent_audience_when_requested(
    audience,
):
    null_audience_token = make_token({"sub": "user", "aud": None})
    absent_audience_token = make_token({"sub": "user"})

    # A requested audience cannot be validated against an absent aud claim.
    # Since null must be treated as absent, both tokens must have this same
    # public failure mode.
    with pytest.raises(MissingRequiredClaimError, match="aud"):
        decode(absent_audience_token, audience=audience)

    with pytest.raises(MissingRequiredClaimError, match="aud"):
        decode(null_audience_token, audience=audience)


def test_null_audience_has_same_behavior_as_absent_audience_when_required():
    null_audience_token = make_token({"sub": "user", "aud": None})
    absent_audience_token = make_token({"sub": "user"})

    # A null claim is not present for purposes of required-claim validation,
    # just like an omitted claim.
    with pytest.raises(MissingRequiredClaimError, match="aud"):
        decode(absent_audience_token, options={"require": ["aud"]})

    with pytest.raises(MissingRequiredClaimError, match="aud"):
        decode(null_audience_token, options={"require": ["aud"]})

from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_with_parents_uses_implementation_for_each_parent():
    class Base:
        pass

    class Intermediate(Base):
        pass

    class Implementation(Intermediate):
        pass

    class TestProvider(Provider):
        scope = Scope.APP
        implementations = provide_all(WithParents[Implementation])

    container = make_container(TestProvider())

    implementation = container.get(Implementation)

    # WithParents must create aliases to the implementation rather than
    # independently constructing every class in its inheritance hierarchy.
    assert container.get(Intermediate) is implementation
    assert container.get(Base) is implementation


def test_provide_all_with_parents_supports_protocol_from_issue():
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes:
            ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return b"processed:" + data

    class MyProvider(Provider):
        scope = Scope.APP
        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())

    implementation = container.get(MyImpl)
    interactor = container.get(MyProtocol)

    # In particular, resolving the protocol must not attempt to instantiate
    # the protocol itself (which is the regression exposed by the issue).
    assert interactor is implementation
    assert interactor(b"input") == b"processed:input"


def test_provide_all_combines_with_parents_and_regular_provides():
    class Parent:
        pass

    class Child(Parent):
        pass

    class Independent:
        pass

    class TestProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child], Independent)

    container = make_container(TestProvider())

    child = container.get(Child)

    assert container.get(Parent) is child
    assert isinstance(container.get(Independent), Independent)

import pytest

from jwt.api_jwt import PyJWT
from jwt.exceptions import MissingRequiredClaimError


@pytest.fixture
def jwt_instance():
    return PyJWT()


def test_null_audience_is_ignored_when_no_audience_is_requested(jwt_instance):
    payload = {"sub": "user-123", "aud": None}
    token = jwt_instance.encode(payload, "secret", algorithm="HS256")

    decoded = jwt_instance.decode(token, "secret", algorithms=["HS256"])

    assert decoded == payload


@pytest.mark.parametrize(
    "audience",
    [
        "expected-audience",
        ["expected-audience", "other-audience"],
    ],
)
def test_null_audience_is_treated_as_missing_when_audience_is_requested(
    jwt_instance, audience
):
    token = jwt_instance.encode({"sub": "user-123", "aud": None}, "secret")

    # An absent aud claim with an expected audience raises this error. Since
    # aud: null must behave identically to an unspecified aud claim, it must
    # not instead be treated as a malformed audience value.
    with pytest.raises(MissingRequiredClaimError) as exc:
        jwt_instance.decode(
            token,
            "secret",
            audience=audience,
            algorithms=["HS256"],
        )

    assert exc.value.claim == "aud"


def test_null_audience_does_not_satisfy_a_required_audience_claim(jwt_instance):
    token = jwt_instance.encode({"sub": "user-123", "aud": None}, "secret")

    with pytest.raises(MissingRequiredClaimError) as exc:
        jwt_instance.decode(
            token,
            "secret",
            algorithms=["HS256"],
            options={"require": ["aud"]},
        )

    assert exc.value.claim == "aud"

from typing import Annotated

import pytest
from pydantic import ValidationError
from pydantic.dataclasses import dataclass
from shapely import (
    GeometryCollection,
    LineString,
    MultiLineString,
    MultiPoint,
    MultiPolygon,
    Point,
    Polygon,
)

from pydantic_shapely import GeometryField


def polygon_with_hole() -> Polygon:
    return Polygon(
        shell=((0, 0), (0, 4), (4, 4), (4, 0), (0, 0)),
        holes=(((1, 1), (1, 2), (2, 2), (2, 1), (1, 1)),),
    )


@pytest.mark.parametrize(
    ("geometry_type", "parts"),
    [
        (
            MultiPolygon,
            [
                polygon_with_hole(),
                Polygon(((10, 10), (10, 11), (11, 11), (10, 10))),
            ],
        ),
        (MultiPoint, [Point(1, 2), Point(3, 4)]),
        (
            MultiLineString,
            [LineString(((0, 0), (1, 1))), LineString(((2, 2), (3, 3)))],
        ),
    ],
)
def test_multi_geometry_fields_accept_component_geometry_objects(
    geometry_type, parts
):
    @dataclass
    class Holder:
        value: Annotated[geometry_type, GeometryField()]

    result = Holder(value=parts).value

    assert isinstance(result, geometry_type)
    assert result.equals_exact(geometry_type(parts), tolerance=0)


def test_multipolygon_field_accepts_tuple_of_polygon_objects():
    polygon = polygon_with_hole()

    @dataclass
    class Holder:
        polys: Annotated[MultiPolygon, GeometryField()]

    result = Holder(polys=(polygon,)).polys

    assert isinstance(result, MultiPolygon)
    assert result.equals_exact(MultiPolygon([polygon]), tolerance=0)


def test_geometry_collection_field_accepts_component_geometry_objects():
    parts = [
        Point(1, 2),
        LineString(((0, 0), (2, 2))),
        polygon_with_hole(),
    ]

    @dataclass
    class Holder:
        value: Annotated[GeometryCollection, GeometryField()]

    result = Holder(value=parts).value

    assert isinstance(result, GeometryCollection)
    assert result.equals_exact(GeometryCollection(parts), tolerance=0)


def test_component_geometry_conversion_applies_z_value_handling():
    polygon_3d = Polygon(
        shell=((0, 0, 5), (0, 1, 5), (1, 1, 5), (0, 0, 5))
    )

    @dataclass
    class Holder:
        polys: Annotated[MultiPolygon, GeometryField(z_values="strip")]

    result = Holder(polys=[polygon_3d]).polys

    assert isinstance(result, MultiPolygon)
    assert not result.has_z
    assert result.equals_exact(
        MultiPolygon([Polygon(((0, 0), (0, 1), (1, 1), (0, 0)))]),
        tolerance=0,
    )


def test_multipolygon_field_rejects_non_polygon_component_geometries():
    @dataclass
    class Holder:
        polys: Annotated[MultiPolygon, GeometryField()]

    with pytest.raises(ValidationError):
        Holder(polys=[Point(1, 2)])

from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_withparents_at_request_scope_provides_protocol_instance():
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes:
            raise NotImplementedError

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return data.upper()

    class MyProvider(Provider):
        scope = Scope.REQUEST
        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())

    with container() as request_container:
        implementation = request_container.get(MyImpl)
        protocol = request_container.get(MyProtocol)

        assert protocol is implementation
        assert protocol(b"dishka") == b"DISHKA"


def test_provide_all_withparents_keeps_all_inherited_types_as_child_aliases():
    class Grandparent:
        pass

    class Parent(Grandparent):
        pass

    class Child(Parent):
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child])

    container = make_container(MyProvider())

    child = container.get(Child)

    assert container.get(Parent) is child
    assert container.get(Grandparent) is child


def test_provide_all_withparents_uses_child_constructor_for_parent_dependency():
    class Config:
        pass

    class Service:
        pass

    class ServiceImpl(Service):
        def __init__(self, config: Config) -> None:
            self.config = config

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(Config, WithParents[ServiceImpl])

    container = make_container(MyProvider())

    implementation = container.get(ServiceImpl)
    service = container.get(Service)

    assert service is implementation
    assert isinstance(service, ServiceImpl)
    assert isinstance(service.config, Config)


def test_provide_all_handles_withparents_and_regular_class_in_one_call():
    class Parent:
        pass

    class Child(Parent):
        pass

    class Standalone:
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child], Standalone)

    container = make_container(MyProvider())

    assert container.get(Parent) is container.get(Child)
    assert isinstance(container.get(Standalone), Standalone)

"""Regression tests for cleaning suspect and corrupt file copies."""

import contextlib
import importlib
from types import SimpleNamespace
from unittest.mock import MagicMock

from alpenhorn.daemon import update as update_module
from alpenhorn.daemon.update import UpdateableNode


class _Field:
    """Small in-memory stand-in for Peewee fields used by these tests."""

    def __init__(self, name):
        self.name = name

    def __eq__(self, value):
        return lambda obj: getattr(obj, self.name) == value

    def __ne__(self, value):
        return lambda obj: getattr(obj, self.name) != value

    def __lshift__(self, values):
        return lambda obj: getattr(obj, self.name) in values

    def in_(self, values):
        return lambda obj: getattr(obj, self.name) in values


class _Query:
    def __init__(self, rows):
        self.rows = list(rows)

    def where(self, *conditions):
        for condition in conditions:
            if callable(condition):
                self.rows = [row for row in self.rows if condition(row)]
        return self

    def order_by(self, *_args):
        return self

    def join(self, *_args):
        return self

    def execute(self):
        return self

    def scalars(self):
        return iter(row.id for row in self.rows)

    def count(self):
        return len(self.rows)

    def __iter__(self):
        return iter(self.rows)


def _copy_model(copies):
    """Return an ArchiveFileCopy-like model backed by ``copies``."""

    class CopyModel:
        id = _Field("id")
        node = _Field("node")
        has_file = _Field("has_file")
        wants_file = _Field("wants_file")

        @classmethod
        def select(cls, *_args):
            return _Query(copies)

        @classmethod
        def update(cls, **changes):
            class Updater:
                def __init__(self):
                    self.rows = list(copies)

                def where(self, *conditions):
                    for condition in conditions:
                        if callable(condition):
                            self.rows = [
                                row for row in self.rows if condition(row)
                            ]
                    return self

                def execute(self):
                    for row in self.rows:
                        for name, value in changes.items():
                            setattr(row, name, value)
                    return len(self.rows)

            return Updater()

    return CopyModel


def _copy(id_, node, has_file, wants_file):
    file_ = SimpleNamespace(
        id=id_,
        path=f"/test/file-{id_}",
        name=f"file-{id_}",
        size_b=1024,
        acq=SimpleNamespace(name="test-acq"),
    )
    return SimpleNamespace(
        id=id_,
        node=node,
        file=file_,
        has_file=has_file,
        wants_file=wants_file,
    )


def _install_no_pending_request_model(monkeypatch):
    """Install an AFCR model for which no copy has a pending transfer."""

    class RequestModel:
        file = _Field("file")
        node_from = _Field("node_from")
        completed = _Field("completed")
        cancelled = _Field("cancelled")

        @classmethod
        def select(cls, *_args):
            return _Query([])

    monkeypatch.setattr(update_module, "ArchiveFileCopyRequest", RequestModel)


def test_daemon_deletes_released_suspect_and_corrupt_copies(monkeypatch):
    """The daemon must delete M/N and X/N copies, not only Y/N copies."""
    node = SimpleNamespace(name="test-node", under_min=False, archive=False)

    valid = _copy(1, node, "Y", "N")
    suspect = _copy(2, node, "M", "N")
    corrupt = _copy(3, node, "X", "N")

    # These look similar, but are not released deletion candidates.
    absent = _copy(4, node, "N", "N")
    wanted_suspect = _copy(5, node, "M", "Y")
    deferred_corrupt = _copy(6, node, "X", "M")

    monkeypatch.setattr(
        update_module,
        "ArchiveFileCopy",
        _copy_model(
            [valid, suspect, corrupt, absent, wanted_suspect, deferred_corrupt]
        ),
    )
    _install_no_pending_request_model(monkeypatch)

    updateable = object.__new__(UpdateableNode)
    updateable.db = node
    updateable.io = MagicMock()
    updateable._io_happened = False

    updateable.update_delete()

    deleted_ids = {
        copy.id
        for call in updateable.io.delete.call_args_list
        for copy in call.args[0]
    }
    assert deleted_ids == {valid.id, suspect.id, corrupt.id}


def test_daemon_does_not_check_released_suspect_copy(monkeypatch):
    """A suspect copy already released for deletion must not be checked."""
    node = SimpleNamespace(
        name="test-node",
        under_min=False,
        archive=False,
        active=True,
    )

    wanted_suspect = _copy(1, node, "M", "Y")
    deferred_suspect = _copy(2, node, "M", "M")
    released_suspect = _copy(3, node, "M", "N")

    monkeypatch.setattr(
        update_module,
        "ArchiveFileCopy",
        _copy_model([wanted_suspect, deferred_suspect, released_suspect]),
    )
    _install_no_pending_request_model(monkeypatch)

    queue = MagicMock()
    queue.fifo_size.return_value = 0

    io = MagicMock()
    io.fifo = "node-fifo"
    io.before_update.return_value = True

    updateable = object.__new__(UpdateableNode)
    updateable.db = node
    updateable.io = io
    updateable._queue = queue
    updateable._io_happened = False
    updateable._updated = False

    monkeypatch.setattr(updateable, "update_free_space", lambda: None)
    monkeypatch.setattr(updateable, "update_delete", MagicMock())
    monkeypatch.setattr(
        update_module.auto_import, "update_observer", lambda *_args, **_kwargs: None
    )
    monkeypatch.setattr(update_module, "RemoteNode", MagicMock())

    updateable.update()

    checked_ids = {call.args[0].id for call in io.check.call_args_list}
    assert checked_ids == {wanted_suspect.id, deferred_suspect.id}
    assert released_suspect.id not in checked_ids


def test_node_clean_include_bad_releases_suspect_and_corrupt_copies(monkeypatch):
    """``node clean --include-bad`` must schedule M/X as well as Y copies."""
    # This import is deliberately part of the test: the public command must be
    # syntactically valid and loadable by the alpenhorn CLI.
    clean_module = importlib.import_module("alpenhorn.cli.node.clean")

    node = SimpleNamespace(name="test-node", archive=False)
    valid = _copy(1, node, "Y", "Y")
    suspect = _copy(2, node, "M", "Y")
    corrupt = _copy(3, node, "X", "Y")
    copies = [valid, suspect, corrupt]

    class StorageNode:
        @classmethod
        def get(cls, **_kwargs):
            return node

    monkeypatch.setattr(clean_module, "StorageNode", StorageNode)
    monkeypatch.setattr(clean_module, "ArchiveFileCopy", _copy_model(copies))
    monkeypatch.setattr(
        clean_module,
        "database_proxy",
        SimpleNamespace(atomic=contextlib.nullcontext),
    )

    from click.testing import CliRunner

    runner = CliRunner()

    # Bad copies are excluded by default.
    result = runner.invoke(clean_module.clean, [node.name, "--now", "--force"])
    assert result.exception is None, result.output
    assert valid.wants_file == "N"
    assert suspect.wants_file == "Y"
    assert corrupt.wants_file == "Y"

    # Requesting them explicitly must release both suspect and corrupt copies.
    result = runner.invoke(
        clean_module.clean,
        [node.name, "--now", "--force", "--include-bad"],
    )
    assert result.exception is None, result.output
    assert suspect.wants_file == "N"
    assert corrupt.wants_file == "N"

