    token = jwt.encode({"aud": None}, "secret")

    with pytest.raises(MissingRequiredClaimError) as exc:
        jwt.decode(
            token,
            "secret",
            audience=audience,
            algorithms=["HS256"],
        )

    assert exc.value.claim == "aud"


def test_null_audience_does_not_satisfy_required_audience_claim(jwt):
    token = jwt.encode({"aud": None}, "secret")

    with pytest.raises(MissingRequiredClaimError) as exc:
        jwt.decode(
            token,
            "secret",
