from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_accepts_withparents_and_resolves_implementation():
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return b"handled:" + data

    class MyProvider(Provider):
        scope = Scope.REQUEST
        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())

    with container() as request_container:
        implementation = request_container.get(MyImpl)

    assert isinstance(implementation, MyImpl)
    assert implementation(b"data") == b"handled:data"


def test_provide_all_withparents_expands_concrete_parent_types():
    class Parent:
        pass

    class Child(Parent):
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child])

    container = make_container(MyProvider())

    child = container.get(Child)
    parent = container.get(Parent)

    assert isinstance(child, Child)
    assert isinstance(parent, Parent)

import enum
import inspect

import pytest

import gspread.utils as utils
from gspread.worksheet import Worksheet


class RecordingClient:
    def __init__(self):
        self.calls = []

    def values_get(self, spreadsheet_id, range_name, params=None):
        self.calls.append(("values_get", spreadsheet_id, range_name, params))
        return {
            "range": range_name,
            "majorDimension": "ROWS",
            "values": [["top-left", ""]],
        }

    def values_batch_get(self, spreadsheet_id, ranges, params=None):
        self.calls.append(("values_batch_get", spreadsheet_id, ranges, params))
        return {
            "valueRanges": [
                {
                    "range": range_name,
                    "majorDimension": "ROWS",
                    "values": [["value"]],
                }
                for range_name in ranges
            ]
        }

    def values_update(self, spreadsheet_id, range_name, params=None, body=None):
        self.calls.append(("values_update", spreadsheet_id, range_name, params, body))
        return {"updatedRange": range_name}

    def values_batch_update(self, spreadsheet_id, body=None):
        self.calls.append(("values_batch_update", spreadsheet_id, body))
        return {"totalUpdatedCells": 1}

    def fetch_sheet_metadata(self, spreadsheet_id):
        self.calls.append(("fetch_sheet_metadata", spreadsheet_id))
        return {
            "sheets": [
                {
                    "properties": {"sheetId": 123, "title": "Sheet1"},
                    "merges": [
                        {
                            "startRowIndex": 0,
                            "endRowIndex": 1,
                            "startColumnIndex": 0,
                            "endColumnIndex": 2,
                        }
                    ],
                }
            ]
        }


