def test_removed_kwargs_helpers_are_not_public_utils():
    """The obsolete filtering/decorator helpers must actually be removed."""
    assert not hasattr(utils, "accepted_kwargs")
    assert not hasattr(utils, "filter_dict_values")
    assert not hasattr(utils, "filter_dict_value")


