def test_value_methods_have_explicit_keyword_parameters(method, expected_arguments):
    """Options formerly injected by accepted_kwargs belong in method signatures."""
    parameters = inspect.signature(getattr(Worksheet, method)).parameters

    assert expected_arguments <= set(parameters)
    assert not any(
        parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in parameters.values()
    )


def test_get_values_keeps_legacy_positional_combine_merged_cells_behavior(worksheet):
    """Removing the decorator must not reinterpret an existing positional call."""
    values = worksheet.get_values("A1:B1", True)

    assert values == [["top-left", "top-left"]]
