from __future__ import annotations

import importlib
import sys
import uuid

from setuptools_scm import Configuration
from setuptools_scm.version import format_version, meta


def _make_source_only_versioning_module(tmp_path, monkeypatch):
    """Create a project module which is importable from its source tree only."""
    package_name = f"uninstalled_project_{uuid.uuid4().hex}"
    package = tmp_path / package_name
    package.mkdir()
    (package / "__init__.py").write_text("")
    (package / "versioning.py").write_text(
        """
def source_tree_scheme(version):
    # Deliberately distinctive: this must come from this project's source tree,
    # not from a setuptools_scm entry point.
    return "source-%s.post%s" % (version.tag, version.distance)


def unavailable_scheme(version):
    # Version scheme sequences use None to request trying the next scheme.
    return None


def fallback_source_tree_scheme(version):
    return "fallback-%s.dev%s" % (version.tag, version.distance)


def source_tree_local_scheme(version):
    return "+from-source-%s" % version.node[:7]
""".lstrip()
    )

    # This is analogous to setuptools executing in the checkout while the
    # project itself has not yet been installed.
    monkeypatch.syspath_prepend(str(tmp_path))
    importlib.invalidate_caches()
    return package_name


def _version(config):
    return meta(
        tag="2.4.0",
        distance=3,
        node="abcdef0123456789",
        dirty=False,
        config=config,
    )


def test_qualified_version_scheme_loads_from_uninstalled_project_source(
    tmp_path, monkeypatch
):
    package = _make_source_only_versioning_module(tmp_path, monkeypatch)
    qualified_name = f"{package}.versioning.source_tree_scheme"

    config = Configuration(
        version_scheme=qualified_name,
        local_scheme="no-local-version",
    )

    assert (
        format_version(
            _version(config),
            version_scheme=qualified_name,
            local_scheme="no-local-version",
        )
        == "source-2.4.0.post3"
    )

    # The module was loaded from the temporary checkout, not from installed
    # distribution entry-point metadata.
    assert sys.modules[f"{package}.versioning"].__file__.startswith(str(tmp_path))


def test_qualified_names_work_in_scheme_fallbacks_and_for_local_schemes(
    tmp_path, monkeypatch
):
    package = _make_source_only_versioning_module(tmp_path, monkeypatch)
    unavailable = f"{package}.versioning.unavailable_scheme"
    fallback = f"{package}.versioning.fallback_source_tree_scheme"
    local = f"{package}.versioning.source_tree_local_scheme"

    config = Configuration(
        version_scheme=[unavailable, fallback],
        local_scheme=local,
    )

    assert (
        format_version(
            _version(config),
            version_scheme=[unavailable, fallback],
            local_scheme=local,
        )
        == "fallback-2.4.0.dev3+from-source-abcdef0"
    )

