import pytest

import sqlglot
from sqlglot import exp


def _column_by_name(expression, name):
    return next(
        column
        for column in expression.find_all(exp.ColumnDef)
        if column.this.name == name
    )


def _has_constraint(column, constraint_type):
    return any(
        isinstance(constraint.kind, constraint_type)
        for constraint in column.args.get("constraints", [])
    )


@pytest.mark.parametrize("serial_keyword", ["SERIAL", "serial"])
def test_mysql_serial_columns_parse_and_round_trip(serial_keyword):
    sql = f"""
        CREATE TABLE temp (
            id {serial_keyword} PRIMARY KEY,
            sequence {serial_keyword}
        );
    """

    parsed = sqlglot.parse_one(sql, read="mysql")

    id_column = _column_by_name(parsed, "id")
    sequence_column = _column_by_name(parsed, "sequence")

    # SERIAL must be recognized as a data type, rather than causing the rest of
    # the column definition to be parsed as invalid trailing tokens.
    assert id_column.kind.this == exp.DataType.Type.SERIAL
    assert sequence_column.kind.this == exp.DataType.Type.SERIAL
    assert _has_constraint(id_column, exp.PrimaryKeyColumnConstraint)

    rendered = sqlglot.transpile(
        sql,
        read="mysql",
        write="mysql",
        pretty=True,
        comments=False,
    )

    assert len(rendered) == 1

    # The generated MySQL must itself remain valid MySQL and preserve both
    # SERIAL columns. A dialect may preserve the SERIAL spelling, or expand its
    # documented BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE alias.
    reparsed = sqlglot.parse_one(rendered[0], read="mysql")
    reparsed_id = _column_by_name(reparsed, "id")
    reparsed_sequence = _column_by_name(reparsed, "sequence")

    assert _has_constraint(reparsed_id, exp.PrimaryKeyColumnConstraint)

    if reparsed_sequence.kind.this != exp.DataType.Type.SERIAL:
        assert reparsed_sequence.kind.this == exp.DataType.Type.UBIGINT
        assert _has_constraint(reparsed_sequence, exp.NotNullColumnConstraint)
        assert _has_constraint(reparsed_sequence, exp.AutoIncrementColumnConstraint)
        assert _has_constraint(reparsed_sequence, exp.UniqueColumnConstraint)

