from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_accepts_withparents_for_protocol_implementation():
    class Handler(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes:
            ...

    class HandlerImpl(Handler):
        def __call__(self, data: bytes) -> bytes:
            return b"handled:" + data

    class HandlerProvider(Provider):
        scope = Scope.REQUEST
        interactors = provide_all(WithParents[HandlerImpl])

    container = make_container(HandlerProvider())
    try:
        with container() as request_container:
            handler = request_container.get(HandlerImpl)
            assert handler(b"message") == b"handled:message"
    finally:
        container.close()


def test_provide_all_withparents_can_be_mixed_with_regular_classes():
    class Parent:
        pass

    class Child(Parent):
        pass

    class Unrelated:
        pass

    class MixedProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child], Unrelated)

    container = make_container(MixedProvider())
    try:
        assert isinstance(container.get(Child), Child)
        assert isinstance(container.get(Parent), Parent)
        assert isinstance(container.get(Unrelated), Unrelated)
    finally:
        container.close()


def test_provider_instance_provide_all_accepts_withparents():
