def test_list_separates_live_and_soft_deleted_items(store):
    store.store("live", b"live")
    store.store("removed", b"old")
    store.move("removed", delete=True)

    # A replacement may coexist with a soft-deleted object of the same
    # logical name.  The two list modes must identify the respective object.
    store.store("shared", b"old")
    store.move("shared", delete=True)
    store.store("shared", b"replacement")

    visible = {item.name: item.size for item in store.list("")}
    visible_explicit = {item.name: item.size for item in store.list("", deleted=False)}
    deleted = {item.name: item.size for item in store.list("", deleted=True)}

    assert visible == {"live": len(b"live"), "shared": len(b"replacement")}
    assert visible_explicit == visible
    assert deleted == {"removed": len(b"old"), "shared": len(b"old")}

    # Deleted entries are presented under their logical name, not their
    # backend .del filename.
    assert all(not name.endswith(".del") for name in deleted)


