from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_withparents_registers_concrete_factory_and_parent_aliases():
    class Transformer(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes:
            ...

    class PrefixingTransformer(Transformer):
        def __call__(self, data: bytes) -> bytes:
            return b"prefix:" + data

    class TransformerProvider(Provider):
        scope = Scope.REQUEST
        # This is the public API combination reported in the issue.
        interactors = provide_all(WithParents[PrefixingTransformer])

    provider = TransformerProvider()

    # WithParents describes one concrete factory plus aliases, not separate
    # factories attempting to construct every parent type.
    assert [factory.provides.type_hint for factory in provider.factories] == [
        PrefixingTransformer,
    ]
    assert [alias.provides.type_hint for alias in provider.aliases] == [
        Transformer,
    ]

    container = make_container(provider)
    with container() as request_container:
        implementation = request_container.get(PrefixingTransformer)
        parent = request_container.get(Transformer)

        assert parent is implementation
        assert parent(b"value") == b"prefix:value"


def test_provide_all_withparents_preserves_aliases_when_mixed_with_regular_types():
    class Base:
        pass

    class Child(Base):
        pass

    class Independent:
        pass

    class MyProvider(Provider):
        scope = Scope.REQUEST
        dependencies = provide_all(WithParents[Child], Independent)

    provider = MyProvider()

    assert {factory.provides.type_hint for factory in provider.factories} == {
        Child,
        Independent,
    }
    assert [alias.provides.type_hint for alias in provider.aliases] == [Base]

    container = make_container(provider)
    with container() as request_container:
        child = request_container.get(Child)

        assert request_container.get(Base) is child
        assert isinstance(request_container.get(Independent), Independent)

