from wemake_python_styleguide.violations.complexity import (
    TooManyLocalsViolation,
)
from wemake_python_styleguide.visitors.ast.complexity.function import (
    FunctionComplexityVisitor,
)


def _local_variable_violations(visitor):
    return [
        violation
        for violation in visitor.violations
        if isinstance(violation, TooManyLocalsViolation)
    ]


def test_nested_function_and_class_locals_do_not_count_for_outer_function(
    options,
    parse_ast_tree,
):
    """Assignments in direct nested scopes are not outer-function locals."""
    tree = parse_ast_tree(
        '''
        def outer():
            outer_value = 1

            def inner():
                inner_value = 1

            class Inner:
                class_value = 1

            return outer_value
        ''',
    )
    visitor = FunctionComplexityVisitor(
        options(max_local_variables=1),
        tree=tree,
    )

    visitor.run()

    assert not _local_variable_violations(visitor)


def test_nested_scopes_inside_control_flow_do_not_count_for_outer_function(
    options,
    parse_ast_tree,
):
    """
    A scope is nested lexically even when an ``if`` is between it and a function.

    This is important because the immediate AST parent of the nested definition
    is the conditional, rather than the enclosing function.
    """
    tree = parse_ast_tree(
        '''
        def outer(enabled):
            outer_value = 1

            if enabled:
                def inner():
                    inner_value = 1

                class Inner:
                    class_value = 1

            return outer_value
        ''',
    )
    visitor = FunctionComplexityVisitor(
        options(max_local_variables=1),
        tree=tree,
    )

    visitor.run()

    assert not _local_variable_violations(visitor)


def test_nested_function_is_checked_without_adding_its_locals_to_outer(
    options,
    parse_ast_tree,
):
    """The nested function has its own WPS210 result, not a shared one."""
    tree = parse_ast_tree(
        '''
        def outer(enabled):
            outer_value = 1

            if enabled:
                def inner():
                    first_inner_value = 1
                    second_inner_value = 2

            return outer_value
        ''',
    )
    visitor = FunctionComplexityVisitor(
        options(max_local_variables=1),
        tree=tree,
    )

    visitor.run()

    # ``inner`` has two locals and violates the limit. ``outer`` has only
    # ``outer_value`` and must not receive an additional violation.
    assert len(_local_variable_violations(visitor)) == 1

import pytest

from jwt.api_jwt import PyJWT
from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


@pytest.fixture
def jwt():
    return PyJWT()


@pytest.mark.parametrize("method", ["decode", "decode_complete"])
def test_null_audience_is_ignored_without_requested_audience(jwt, method):
    payload = {"sub": "user-123", "aud": None}
    token = jwt.encode(payload, "secret", algorithm="HS256")

    result = getattr(jwt, method)(token, "secret", algorithms=["HS256"])

    if method == "decode_complete":
        result = result["payload"]

    assert result == payload


@pytest.mark.parametrize("method", ["decode", "decode_complete"])
def test_null_audience_has_same_failure_as_omitted_audience_when_requested(
    jwt, method
):
    null_audience_token = jwt.encode(
        {"sub": "user-123", "aud": None}, "secret", algorithm="HS256"
    )
    omitted_audience_token = jwt.encode(
        {"sub": "user-123"}, "secret", algorithm="HS256"
    )

    # Establish the behavior for an actually unspecified audience claim.
    with pytest.raises(MissingRequiredClaimError) as omitted_error:
        getattr(jwt, method)(
            omitted_audience_token,
            "secret",
            algorithms=["HS256"],
            audience="expected-audience",
        )

    # aud: null is specified to be treated exactly like that omitted claim.
    with pytest.raises(MissingRequiredClaimError) as null_error:
        getattr(jwt, method)(
            null_audience_token,
            "secret",
            algorithms=["HS256"],
            audience="expected-audience",
        )

    assert omitted_error.value.claim == "aud"
    assert null_error.value.claim == "aud"


def test_non_null_audience_is_still_validated(jwt):
    token = jwt.encode(
        {"sub": "user-123", "aud": "actual-audience"},
        "secret",
        algorithm="HS256",
    )

    with pytest.raises(InvalidAudienceError):
        jwt.decode(token, "secret", algorithms=["HS256"])

