from __future__ import annotations

from pdm.models.requirements import parse_requirement
from pdm.project.core import Project


def _set_legacy_dev_dependencies(project: Project, groups: dict[str, list[str]]) -> None:
    project.pyproject.settings["dev-dependencies"] = groups
    project.pyproject.write()


def _add_dev_requirement(project: Project, group: str) -> None:
    project.add_dependencies(
        [parse_requirement("ruff")],
        to_group=group,
        dev=True,
    )
    project.pyproject.write()


def test_add_to_default_dev_group_keeps_legacy_editable_group_untouched(project: Project):
    """A legacy editable group must not be copied into PEP 735 dependency-groups."""
    _set_legacy_dev_dependencies(
        project,
        {
            "workspaces": [
                "-e ./packages/pkg-app",
                "-e ./packages/pkg-core",
            ]
        },
    )

    _add_dev_requirement(project, "dev")

    data = project.pyproject._data
    assert data["dependency-groups"]["dev"] == ["ruff"]
    assert "workspaces" not in data["dependency-groups"]
    assert project.pyproject.settings["dev-dependencies"]["workspaces"] == [
        "-e ./packages/pkg-app",
        "-e ./packages/pkg-core",
    ]


def test_add_to_named_dev_group_keeps_all_legacy_groups_untouched(project: Project):
    """The selected group, not the final legacy table key, receives the dependency."""
    _set_legacy_dev_dependencies(
        project,
        {
            "first": ["-e ./packages/first"],
            # Keeping this last exposes the original loop-variable shadowing bug.
            "workspaces": ["-e ./packages/pkg-app"],
        },
    )

    _add_dev_requirement(project, "lint")

    data = project.pyproject._data
    assert data["dependency-groups"]["lint"] == ["ruff"]
    assert "first" not in data["dependency-groups"]
    assert "workspaces" not in data["dependency-groups"]
    assert project.pyproject.settings["dev-dependencies"] == {
        "first": ["-e ./packages/first"],
        "workspaces": ["-e ./packages/pkg-app"],
    }


def test_adding_to_existing_pep735_group_does_not_migrate_legacy_editables(project: Project):
    """Adding to an existing PEP 735 group must not duplicate a legacy editable group."""
    project.pyproject._data["dependency-groups"] = {"lint": ["pytest"]}
    _set_legacy_dev_dependencies(project, {"workspaces": ["-e ./packages/pkg-app"]})

    _add_dev_requirement(project, "lint")

    data = project.pyproject._data
    assert data["dependency-groups"]["lint"] == ["pytest", "ruff"]
    assert set(data["dependency-groups"]) == {"lint"}
    assert project.pyproject.settings["dev-dependencies"]["workspaces"] == ["-e ./packages/pkg-app"]

