from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide, provide_all


def test_provide_all_with_parents_registers_implementation_and_protocol_alias():
    class Transformer(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class TransformerImpl(Transformer):
        def __call__(self, data: bytes) -> bytes:
            return data.upper()

    class TransformerProvider(Provider):
        scope = Scope.REQUEST
        transformers = provide_all(WithParents[TransformerImpl])

    container = make_container(TransformerProvider())

    with container(scope=Scope.REQUEST) as request_container:
        implementation = request_container.get(TransformerImpl)
        protocol = request_container.get(Transformer)

        assert isinstance(implementation, TransformerImpl)
        assert protocol is implementation
        assert protocol(b"dishka") == b"DISHKA"


def test_provide_all_with_parents_uses_concrete_class_and_aliases_all_parents():
    class Dependency:
        pass

    class BaseService:
        pass

    class FirstService:
        pass

    class SecondService:
        pass

    class Service(BaseService, FirstService, SecondService):
        def __init__(self, dependency: Dependency) -> None:
            self.dependency = dependency

    class ServiceProvider(Provider):
        scope = Scope.APP

        dependency = provide(Dependency)
        services = provide_all(WithParents[Service])

    container = make_container(ServiceProvider())

    service = container.get(Service)

    assert isinstance(service, Service)
    assert isinstance(service.dependency, Dependency)
    assert container.get(BaseService) is service
    assert container.get(FirstService) is service
    assert container.get(SecondService) is service

