from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide, provide_all


def test_provide_all_with_parents_registers_concrete_factory_and_protocol_alias():
    class Transformer(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes:
            ...

    class TransformerImpl(Transformer):
        def __init__(self, prefix: bytes) -> None:
            self.prefix = prefix

        def __call__(self, data: bytes) -> bytes:
            return self.prefix + data

    class MyProvider(Provider):
        scope = Scope.REQUEST

        @provide
        @staticmethod
        def prefix() -> bytes:
            return b"processed:"

        interactors = provide_all(WithParents[TransformerImpl])

    container = make_container(MyProvider())

    with container() as request_container:
        implementation = request_container.get(TransformerImpl)
        protocol = request_container.get(Transformer)

        assert protocol is implementation
        assert protocol(b"data") == b"processed:data"


def test_provide_all_with_parents_aliases_every_direct_parent():
    class Reader(Protocol):
        @abstractmethod
        def read(self) -> str:
            ...

    class Writer(Protocol):
        @abstractmethod
        def write(self, value: str) -> None:
            ...

    class ReadWriter(Reader, Writer):
        def __init__(self) -> None:
            self.value = ""

        def read(self) -> str:
            return self.value

        def write(self, value: str) -> None:
            self.value = value

    class MyProvider(Provider):
        scope = Scope.APP

        services = provide_all(WithParents[ReadWriter])

    container = make_container(MyProvider())

    implementation = container.get(ReadWriter)
    reader = container.get(Reader)
    writer = container.get(Writer)

    assert reader is implementation
    assert writer is implementation

    writer.write("updated")
    assert reader.read() == "updated"

import pytest

from ucumvert import PintUcumRegistry, ucum_preprocessor


def _magnitude_in_international_units_per_liter(quantity):
    """Return a magnitude after verifying the quantity is convertible to IU/L."""
    return quantity.to("international_unit / liter").magnitude


@pytest.mark.parametrize(
    ("ucum_code", "scale"),
    [
        ("m[IU]/L", 1e-3),
        ("k[IU]/L", 1e3),
    ],
)
def test_prefixed_international_units_are_scaled_not_multiplied_by_length(
    ucum_code, scale
):
    """A UCUM prefix before [IU] applies to IU, rather than becoming a length."""
    ureg = PintUcumRegistry()

    result = ureg.from_ucum(ucum_code)
    unprefixed = ureg.from_ucum("[IU]/L")

    assert _magnitude_in_international_units_per_liter(result) == pytest.approx(
        scale * _magnitude_in_international_units_per_liter(unprefixed)
    )


def test_prefixed_international_unit_and_prefixed_liter_cancel():
    """Prefixes in numerator and denominator must be independently interpreted."""
    ureg = PintUcumRegistry()

    result = ureg.from_ucum("m[IU]/mL")
    expected = ureg.from_ucum("[IU]/L")

    assert _magnitude_in_international_units_per_liter(result) == pytest.approx(
        _magnitude_in_international_units_per_liter(expected)
    )


@pytest.mark.parametrize(
    ("ucum_code", "scale"),
    [
        ("m[IU]/L", 1e-3),
        ("k[IU]/L", 1e3),
    ],
)
def test_preprocessor_can_parse_prefixed_international_units(ucum_code, scale):
    """The documented UCUM-aware Pint preprocessor must produce valid Pint input."""
    ureg = PintUcumRegistry()
    ureg.preprocessors.append(ucum_preprocessor)

    result = ureg(ucum_code)
    unprefixed = ureg.from_ucum("[IU]/L")

    assert _magnitude_in_international_units_per_liter(result) == pytest.approx(
        scale * _magnitude_in_international_units_per_liter(unprefixed)
    )

from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


class ServiceProtocol(Protocol):
    def handle(self, value: str) -> str: ...


class BaseService:
    def base_name(self) -> str:
        return "base"


class Service(BaseService, ServiceProtocol):
    def handle(self, value: str) -> str:
        return value.upper()


def test_provide_all_with_parents_registers_implementation_and_all_parents():
    """WithParents must be unpacked when used as a provide_all source."""

    class ServicesProvider(Provider):
        scope = Scope.APP
        services = provide_all(WithParents[Service])

    container = make_container(ServicesProvider())

    implementation = container.get(Service)
    assert isinstance(implementation, Service)

    # WithParents aliases every parent to the single Service factory.
    assert container.get(BaseService) is implementation
    assert container.get(ServiceProtocol) is implementation
    assert implementation.handle("dishka") == "DISHKA"


def test_instance_provide_all_with_parents_supports_multiple_parent_interfaces():
    """The instance API must handle the ProvideMultiple marker as well."""

    class FirstInterface(Protocol):
        def first(self) -> str: ...

    class SecondInterface(Protocol):
        def second(self) -> str: ...

    class MultiService(FirstInterface, SecondInterface):
        def first(self) -> str:
            return "first"

        def second(self) -> str:
            return "second"

    provider = Provider(scope=Scope.APP)
    provider.provide_all(WithParents[MultiService])
    container = make_container(provider)

    implementation = container.get(MultiService)

    assert isinstance(implementation, MultiService)
    assert container.get(FirstInterface) is implementation
    assert container.get(SecondInterface) is implementation

