from checkov.cloudformation.runner import Runner
from checkov.runner_filter import RunnerFilter


CHECK_ID = "CKV_AWS_24"


def _scan(template_path):
    return Runner().run(
        root_folder=None,
        files=[str(template_path)],
        runner_filter=RunnerFilter(framework="all", checks=[CHECK_ID]),
    )


def _security_group(name):
    return (
        f"  {name}:\n"
        "    Type: AWS::EC2::SecurityGroup\n"
        "    Properties:\n"
        "      GroupDescription: intentionally allows SSH for this test\n"
        "      VpcId: vpc-12345678\n"
        "      SecurityGroupIngress:\n"
        "        - IpProtocol: tcp\n"
        "          FromPort: 22\n"
        "          ToPort: 22\n"
        "          CidrIp: 0.0.0.0/0\n"
    )


def _resources(records):
    return {record.resource for record in records if record.check_id == CHECK_ID}


def test_cloudformation_skip_comment_suppresses_only_annotated_resource(tmp_path):
    """The issue's exact comment form suppresses the following CFN resource."""
    template = tmp_path / "security_groups.yaml"
    template.write_text(
        "AWSTemplateFormatVersion: '2010-09-09'\n"
        "Resources:\n"
        "  #checkov:skip=CKV_AWS_24:\n"
        + _security_group("SuppressedSecurityGroup")
        + _security_group("UnsuppressedSecurityGroup"),
        encoding="utf-8",
    )

    report = _scan(template)

    assert _resources(report.skipped_checks) == {
        "AWS::EC2::SecurityGroup.SuppressedSecurityGroup"
    }
    assert _resources(report.failed_checks) == {
        "AWS::EC2::SecurityGroup.UnsuppressedSecurityGroup"
    }


def test_cloudformation_skip_comment_between_resources_applies_to_next_resource(tmp_path):
    """A skip annotation must not be associated with the preceding resource."""
    template = tmp_path / "resource_scoping.yaml"
    template.write_text(
        "AWSTemplateFormatVersion: '2010-09-09'\n"
        "Resources:\n"
        + _security_group("FirstSecurityGroup")
        + "  #checkov:skip=CKV_AWS_24: SSH access is required temporarily\n"
        + _security_group("SecondSecurityGroup"),
        encoding="utf-8",
    )

    report = _scan(template)

    assert _resources(report.skipped_checks) == {
        "AWS::EC2::SecurityGroup.SecondSecurityGroup"
    }
    assert _resources(report.failed_checks) == {
        "AWS::EC2::SecurityGroup.FirstSecurityGroup"
    }

