        np.array([-10, -10], dtype=np.int32),
    ],
)
def test_move_masks_returns_empty_masks_when_offset_moves_everything_outside_frame(
    masks: np.ndarray, offset: np.ndarray
) -> None:
    result = move_masks(
        masks=masks,
        offset=offset,
        resolution_wh=(4, 3),
    )

    np.testing.assert_array_equal(result, np.zeros((2, 3, 4), dtype=bool))


def test_move_masks_pads_output_when_resolution_is_larger_than_source(
    masks: np.ndarray,
) -> None:
