import numpy as np
import pytest

import supervision as sv


def expected_moved_masks(
    masks: np.ndarray, offset: tuple[int, int], resolution_wh: tuple[int, int]
) -> np.ndarray:
    """Reference implementation using per-pixel destination coordinates."""
    dx, dy = offset
    width, height = resolution_wh
    expected = np.zeros((masks.shape[0], height, width), dtype=bool)

    for mask_index in range(masks.shape[0]):
        for source_y in range(masks.shape[1]):
            for source_x in range(masks.shape[2]):
                target_x = source_x + dx
                target_y = source_y + dy
                if 0 <= target_x < width and 0 <= target_y < height:
                    expected[mask_index, target_y, target_x] = masks[
                        mask_index, source_y, source_x
                    ]

    return expected


@pytest.fixture
def masks() -> np.ndarray:
    return np.array(
        [
            [
                [False, True, False, True],
                [True, False, True, False],
                [False, True, True, False],
            ],
            [
                [True, False, False, True],
                [False, True, False, False],
                [True, True, False, True],
            ],
        ],
        dtype=bool,
    )


@pytest.mark.parametrize(
    "offset,resolution_wh",
    [
        pytest.param((-1, -2), (5, 4), id="negative-x-and-y-with-cropping"),
        pytest.param((-2, 1), (4, 3), id="negative-x-positive-y"),
        pytest.param((2, -1), (5, 3), id="positive-x-negative-y"),
        pytest.param((3, 2), (4, 3), id="positive-offset-with-cropping"),
        pytest.param((0, 0), (6, 5), id="no-movement-with-padding"),
    ],
)
def test_move_masks_translates_each_mask_and_crops_to_output_bounds(
    masks: np.ndarray, offset: tuple[int, int], resolution_wh: tuple[int, int]
) -> None:
    original_masks = masks.copy()

    result = sv.move_masks(
        masks=masks,
        offset=np.array(offset, dtype=np.int32),
        resolution_wh=resolution_wh,
    )

    expected = expected_moved_masks(masks, offset, resolution_wh)
    np.testing.assert_array_equal(result, expected)
    assert result.dtype == bool
    np.testing.assert_array_equal(masks, original_masks)


@pytest.mark.parametrize(
    "offset",
    [
        pytest.param((-10, 0), id="completely-left"),
        pytest.param((0, -10), id="completely-above"),
        pytest.param((10, 10), id="completely-right-and-below"),
    ],
)
def test_move_masks_returns_empty_masks_when_offset_has_no_overlap(
    masks: np.ndarray, offset: tuple[int, int]
) -> None:
    result = sv.move_masks(
        masks=masks,
        offset=np.array(offset, dtype=np.int32),
        resolution_wh=(4, 3),
    )

    assert result.shape == (2, 3, 4)
    assert result.dtype == bool
    assert not result.any()

