from infrahub_sdk import Config, InfrahubClient, InfrahubClientSync
from infrahub_sdk.exceptions import NodeNotFoundError

from .conftest import InfrahubTestClient


class TestClientGetRaiseWhenMissing:
    """Validate optional missing-node behavior for both SDK client variants."""

    missing_account_name = "ttg-generated-account-that-does-not-exist"

    @pytest.fixture(scope="class")
    async def test_client(self) -> InfrahubTestClient:
        return InfrahubTestClient(app)

    @pytest.fixture
    def async_client(self, test_client: InfrahubTestClient) -> InfrahubClient:
        return InfrahubClient(
            config=Config(
                username="admin",
                password="infrahub",
                requester=test_client.async_request,
            )
        )

    @pytest.fixture
    def sync_client(self, test_client: InfrahubTestClient) -> InfrahubClientSync:
        return InfrahubClientSync(
            config=Config(
                username="admin",
                password="infrahub",
                sync_requester=test_client.sync_request,
            )
        )

    async def test_async_get_returns_none_for_missing_node_when_disabled(
        self, async_client: InfrahubClient, init_db_base
    ) -> None:
        node = await async_client.get(
            kind="CoreAccount",
            name__value=self.missing_account_name,
            raise_when_missing=False,
        )

        assert node is None

    async def test_async_get_still_raises_by_default_and_when_explicitly_enabled(
        self, async_client: InfrahubClient, init_db_base
    ) -> None:
        with pytest.raises(NodeNotFoundError):
            await async_client.get(kind="CoreAccount", name__value=self.missing_account_name)

        with pytest.raises(NodeNotFoundError):
            await async_client.get(
                kind="CoreAccount",
                name__value=self.missing_account_name,
                raise_when_missing=True,
            )

    async def test_async_get_returns_existing_node_when_missing_errors_are_disabled(
        self, async_client: InfrahubClient, init_db_base
    ) -> None:
        node = await async_client.get(
            kind="CoreAccount",
            name__value="admin",
            raise_when_missing=False,
        )

        assert node is not None
        assert node.name.value == "admin"  # type: ignore[attr-defined]

    def test_sync_get_returns_none_for_missing_node_when_disabled(
        self, sync_client: InfrahubClientSync, init_db_base
    ) -> None:
        node = sync_client.get(
            kind="CoreAccount",
            name__value=self.missing_account_name,
            raise_when_missing=False,
        )

        assert node is None

    def test_sync_get_still_raises_by_default_and_when_explicitly_enabled(
        self, sync_client: InfrahubClientSync, init_db_base
    ) -> None:
        with pytest.raises(NodeNotFoundError):
            sync_client.get(kind="CoreAccount", name__value=self.missing_account_name)

        with pytest.raises(NodeNotFoundError):
            sync_client.get(
                kind="CoreAccount",
                name__value=self.missing_account_name,
                raise_when_missing=True,
            )

    def test_sync_get_returns_existing_node_when_missing_errors_are_disabled(
        self, sync_client: InfrahubClientSync, init_db_base
    ) -> None:
        node = sync_client.get(
            kind="CoreAccount",
            name__value="admin",
            raise_when_missing=False,
        )

        assert node is not None
        assert node.name.value == "admin"  # type: ignore[attr-defined]

