    assert ureg(ucum_code) == expected

import pytest

from wemake_python_styleguide.violations.complexity import (
    TooManyLocalsViolation,
)
from wemake_python_styleguide.visitors.ast.complexity.function import (
    FunctionComplexityVisitor,
)


def _local_variable_violations(visitor):
    """Return violations emitted by WPS210 only."""
    return [
        violation
        for violation in visitor.violations
        if isinstance(violation, TooManyLocalsViolation)
    ]


def test_class_attributes_are_not_outer_function_locals(
    default_options,
    parse_ast_tree,
):
    """Class-body assignments must not contribute to the enclosing function."""
    tree = parse_ast_tree(
        """
def factory():
    local_value = 1

    class Inner:
        first = 1
        second = 2
        third = 3
        fourth = 4
""",
    )
    options = default_options._replace(max_local_variables=1)

    visitor = FunctionComplexityVisitor(options, tree=tree)
    visitor.run()

    assert _local_variable_violations(visitor) == []


@pytest.mark.parametrize(
    ('nested_scope', 'expected_violations'),
    [
        (
            """
    if condition:
        class Inner:
            first = 1
            second = 2
""",
            0,
        ),
        (
            """
    if condition:
        def inner():
            first = 1
            second = 2
""",
            1,
        ),
        (
            """
    if condition:
        async def inner():
            first = 1
            second = 2
""",
            1,
        ),
    ],
)
def test_nested_scope_locals_do_not_leak_through_control_flow(
    default_options,
    parse_ast_tree,
    nested_scope,
    expected_violations,
):
    """
    Locals of nested scopes must stay local, including scopes inside an ``if``.

    Nested functions still have their own WPS210 check. Thus function cases
    produce one violation for ``inner`` itself, but must not additionally
    produce a violation for ``outer``.
    """
    tree = parse_ast_tree(
        (
            'def outer(condition):\n'
            '    outer_local = 1\n'
            + nested_scope
        ),
    )
    options = default_options._replace(max_local_variables=1)

    visitor = FunctionComplexityVisitor(options, tree=tree)
    visitor.run()

    assert len(_local_variable_violations(visitor)) == expected_violations

import re
import subprocess
import sys
from pathlib import Path


def _warning_categories_for_file(output: str, filename: Path) -> set[str]:
    """Return cpplint categories emitted for one input file."""
    pattern = re.compile(
        rf"^{re.escape(str(filename))}:\d+:.*\s\[(?P<category>[^\]]+)\]\s\[\d+\]$",
        re.MULTILINE,
    )
    return {match.group("category") for match in pattern.finditer(output)}


def test_c_extensions_skip_cpp_warnings_without_affecting_cpp_files(tmp_path):
    """C files suppress C++ rules, but that suppression must not leak to C++ files."""
    source = """\
int main() {
  int value = 1;
  float converted = (float)value;
  short port = 8080;
  return port;
}
"""

    c_files = [
        tmp_path / "lowercase.c",
        tmp_path / "uppercase.C",
        tmp_path / "lowercase.h",
        tmp_path / "uppercase.H",
    ]
    cpp_file = tmp_path / "still_cpp.cpp"

    for filename in c_files:
        filename.write_text(source)
    cpp_file.write_text(source)

    cpplint_script = Path(__file__).with_name("cpplint.py")
    result = subprocess.run(
        [
            sys.executable,
            str(cpplint_script),
            # Restrict output to precisely the C++-specific categories at issue.
            "--filter=-,+readability/casting,+runtime/int",
            *(str(filename) for filename in c_files),
            str(cpp_file),
        ],
        text=True,
        capture_output=True,
        check=False,
    )
    output = result.stdout + result.stderr

    expected_categories = {"readability/casting", "runtime/int"}

    # All spellings covered by .[cChH] are C inputs and must not recommend
    # C++ casts or fixed-width integer substitutions.
    for c_file in c_files:
        assert _warning_categories_for_file(output, c_file).isdisjoint(expected_categories), (
            f"{c_file.suffix} was not treated as C:\n{output}"
        )

    # Processing C files in the same cpplint invocation must not globally
    # suppress the rules for a subsequent C++ file.
    assert expected_categories.issubset(_warning_categories_for_file(output, cpp_file)), output

