import pytest

from yarl import URL


@pytest.mark.parametrize(
    ("port", "type_name"),
    [
        (8080.0, "float"),
        ("8080", "str"),
        ([], "list"),
    ],
)
def test_build_invalid_port_error_includes_type_name(port, type_name):
    with pytest.raises(TypeError) as exc_info:
        URL.build(scheme="http", host="example.com", port=port)

    assert str(exc_info.value) == f"The port is required to be int, got {type_name}."


def test_build_invalid_port_reports_custom_type_name():
    class InvalidPort:
        pass

    with pytest.raises(TypeError) as exc_info:
        URL.build(scheme="http", host="example.com", port=InvalidPort())

    assert str(exc_info.value) == "The port is required to be int, got InvalidPort."


def test_build_still_accepts_none_and_integer_ports():
    assert str(URL.build(scheme="http", host="example.com", port=None)) == (
        "http://example.com"
    )
    assert str(URL.build(scheme="http", host="example.com", port=8080)) == (
        "http://example.com:8080"
    )

import inspect
