import cpplint


TARGET_CXX_CATEGORIES = {"readability/casting", "runtime/int"}


def _lint_categories(filename, extension):
    """Run cpplint's normal per-file processing and return printed categories."""
    categories = []

    def collect_error(filename, linenum, category, confidence, message):
        if cpplint._ShouldPrintError(category, confidence, filename, linenum):
            categories.append(category)

    cpplint.ProcessFileData(
        filename,
        extension,
        [
            "// Copyright 2024 Example Authors.",
            "long value = (int64_t) 65;",
            "",
        ],
        collect_error,
    )
    return categories


@pytest.fixture(autouse=True)
def reset_nolint_state():
    # C-language handling must be per-file and must not affect later files.
    cpplint.ResetNolintSuppressions()
    yield
    cpplint.ResetNolintSuppressions()


@pytest.mark.parametrize("extension", ["c", "C", "h", "H"])
def test_c_extensions_suppress_cpp_casting_and_integer_warnings(extension):
    categories = _lint_categories("example." + extension, extension)

    assert TARGET_CXX_CATEGORIES.isdisjoint(categories)


@pytest.mark.parametrize("extension", ["c", "C", "h", "H"])
def test_c_extensions_are_accepted_by_default_command_line_extensions(extension):
    filename = "example." + extension

    # It is not enough to suppress checks after processing: these extensions
    # must also be recognized by the normal command-line file selection path.
    assert cpplint.ParseArguments([filename]) == [filename]


@pytest.mark.parametrize("c_extension", ["c", "C", "h", "H"])
def test_c_suppression_is_limited_to_the_current_c_file(c_extension):
    # Process a C file first, as a mixed C/C++ invocation would.
    c_categories = _lint_categories("first." + c_extension, c_extension)
    assert TARGET_CXX_CATEGORIES.isdisjoint(c_categories)

    # The C-specific suppression must not leak into a following C++ file.
    cpp_categories = _lint_categories("second.cc", "cc")
    assert TARGET_CXX_CATEGORIES.issubset(cpp_categories)

