from keyring import cli


@pytest.mark.parametrize("password", ["correct horse battery staple", ""])
def test_get_returns_password_after_set_for_anonymous_credential(
    monkeypatch, capsys, password
):
    stored_passwords = {}

    def set_password(service, username, value):
        stored_passwords[service, username] = value

    def get_password(service, username):
