    # property must not prevent the CLI from returning the stored password.
    assert capsys.readouterr().out == f"{password}\n"

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def _spec(openapi_version, *, schema_name_resolver=None):
    plugin_kwargs = {}
    if schema_name_resolver is not None:
        plugin_kwargs["schema_name_resolver"] = schema_name_resolver

    return APISpec(
        title="Nested nullable test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin(**plugin_kwargs)],
    )


def _nested_property(openapi_version, *, metadata=None):
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class ParentSchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True, metadata=metadata)

    spec = _spec(openapi_version)
    # Register Foo first so Parent's field is rendered as a component ref.
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Parent", schema=ParentSchema)
    return spec.to_dict()["components"]["schemas"]["Parent"]["properties"]["foo"]


@pytest.mark.parametrize("openapi_version", ("3.0.0", "3.0.3"))
def test_oas30_nullable_nested_ref_uses_nullable_object_branch(openapi_version):
    """OAS 3.0 has no ``null`` type; nullable must modify a local type."""
    property_schema = _nested_property(openapi_version)

    assert property_schema == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


@pytest.mark.parametrize("openapi_version", ("3.0.0", "3.0.3"))
def test_oas30_nullable_nested_ref_with_metadata_does_not_use_nullable_allof(
    openapi_version,
):
    """The allOf wrapper used for ref siblings must not inherit nullable."""
    property_schema = _nested_property(
        openapi_version,
        metadata={"description": "Optional nested object"},
    )

    assert property_schema == {
        "description": "Optional nested object",
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ],
    }
    assert "allOf" not in property_schema
    assert "nullable" not in property_schema
    assert {"type": "null"} not in property_schema["anyOf"]


@pytest.mark.parametrize("openapi_version", ("3.0.0", "3.0.3"))
def test_oas30_nullable_inline_nested_schema_modifies_local_object_type(
    openapi_version,
):
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class ParentSchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    # An inline nested schema has a type assertion in this same Schema Object,
    # so OpenAPI 3.0's ordinary nullable form is appropriate.
    spec = _spec(openapi_version, schema_name_resolver=lambda schema: None)
    spec.components.schema("Parent", schema=ParentSchema)

    assert spec.to_dict()["components"]["schemas"]["Parent"]["properties"]["foo"] == {
        "type": "object",
        "nullable": True,
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }


def test_oas31_nullable_nested_ref_uses_json_schema_null_type():
    """The OAS 3.0 workaround must not replace the OAS 3.1 representation."""
    property_schema = _nested_property("3.1.0")

    assert property_schema == {
        "anyOf": [
            {"$ref": "#/components/schemas/Foo"},
            {"type": "null"},
        ]
    }

