from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_openapi_303_spec():
    return APISpec(
        title="Nullable nested schemas",
        version="1.0.0",
        openapi_version="3.0.3",
        plugins=[MarshmallowPlugin()],
    )


def test_openapi_303_nullable_nested_schema_uses_nullable_object_anyof():
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_openapi_303_spec()
    spec.components.schema("MySchema", schema=MySchema)

    schemas = spec.to_dict()["components"]["schemas"]
    assert schemas["Foo"] == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }

    # In OpenAPI 3.0, nullable only applies to a type declared in the same
    # Schema Object. It cannot make a referenced schema nullable by appearing
    # alongside allOf or a $ref.
    assert schemas["MySchema"]["properties"]["foo"] == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


def test_openapi_303_nullable_nested_schema_with_metadata_does_not_use_nullable_allof():
    class ChildSchema(Schema):
        value = fields.String(required=True)

    class ParentSchema(Schema):
        child = fields.Nested(
            ChildSchema,
            allow_none=True,
            metadata={"description": "An optional child"},
        )

    spec = make_openapi_303_spec()
    spec.components.schema("ParentSchema", schema=ParentSchema)

    child_property = spec.to_dict()["components"]["schemas"]["ParentSchema"][
        "properties"
    ]["child"]

    # Field metadata normally makes a nested reference use allOf. Nullable
    # must still be represented by an object type in its own anyOf branch.
    assert child_property == {
        "description": "An optional child",
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ],
    }


def test_openapi_303_nullable_non_reference_field_keeps_nullable_type_modifier():
    class ExampleSchema(Schema):
        name = fields.String(allow_none=True)

    spec = make_openapi_303_spec()
    spec.components.schema("ExampleSchema", schema=ExampleSchema)

    # The special union is needed only for references. For a directly declared
    # type, nullable belongs beside that type in the same Schema Object.
    assert spec.to_dict()["components"]["schemas"]["ExampleSchema"]["properties"][
        "name"
    ] == {"type": "string", "nullable": True}

import punq


class KeywordOnlyDependency:
    pass


class KeywordOnlyDependencyConsumer:
    def __init__(self, *, dependency: KeywordOnlyDependency):
        self.dependency = dependency


class KeywordOnlyRuntimeArgument:
    def __init__(self, *, value):
        self.value = value


class KeywordOnlyDefaultArgument:
