def test_resolves_annotated_keyword_only_dependencies():
    container = punq.Container()
    container.register(KeywordOnlyDependency)
    container.register(KeywordOnlyDependencyConsumer)

    resolved = container.resolve(KeywordOnlyDependencyConsumer)

    assert isinstance(resolved.dependency, KeywordOnlyDependency)


