    assert resolved.value == "from-resolve"


def test_uses_keyword_only_annotated_defaults_when_no_service_is_registered():
    container = punq.Container()
    container.register(KeywordOnlyDefaultArgument)

    resolved = container.resolve(KeywordOnlyDefaultArgument)

    assert resolved.retries == 0

import pytest
import sqlglot


@pytest.mark.parametrize(
    "sql, expected",
    [
        (
            "SELECT 'hello' || 'world' FROM t",
            "SELECT 'hello' + 'world' FROM t",
        ),
        (
            "SELECT first_name || last_name AS full_name FROM users",
            "SELECT first_name + last_name AS full_name FROM users",
        ),
        (
            "SELECT a || b || c FROM t",
            "SELECT a + b + c FROM t",
        ),
        (
            "SELECT UPPER(first_name || ' ' || last_name) FROM users",
            "SELECT UPPER(first_name + ' ' + last_name) FROM users",
        ),
    ],
)
def test_postgres_string_concatenation_uses_plus_in_tsql(sql, expected):
    assert sqlglot.transpile(sql, read="postgres", write="tsql") == [expected]


def test_all_dpipe_expressions_are_rendered_with_tsql_compatible_concatenation():
    # SQLite also uses || for string concatenation. The T-SQL generator must
    # not emit Azure-only || syntax irrespective of the input dialect.
    result = sqlglot.transpile(
        "SELECT COALESCE(first_name, '') || ' ' || COALESCE(last_name, '') FROM users",
        read="sqlite",
        write="tsql",
    )

    assert result == [
        "SELECT COALESCE(first_name, '') + ' ' + COALESCE(last_name, '') FROM users"
    ]
    assert "||" not in result[0]


def test_tsql_generation_keeps_logical_or_distinct_from_concatenation():
    # T-SQL rendering may normalize bare boolean columns to explicit predicates,
    # but a logical OR must remain an OR and must never be rendered as ||.
    result = sqlglot.transpile(
        "SELECT a FROM t WHERE enabled OR is_admin", read="postgres", write="tsql"
    )[0]

    assert " OR " in result
    assert "||" not in result


def test_existing_tsql_plus_operator_is_preserved():
    assert sqlglot.transpile(
        "SELECT first_name + last_name FROM users", read="tsql", write="tsql"
    ) == ["SELECT first_name + last_name FROM users"]

