import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_parameter_is_not_reported_as_missing():
    """A constructor's ``**kwargs`` collector is never a required input."""

    class ConfigurableModel:
        def __init__(self, required_parameter, **kwargs):
            pass

    _check_model_params(ConfigurableModel.__init__, {"required_parameter": 1})


def test_kwargs_allows_additional_model_configuration():
    """Model parameters collected by ``**kwargs`` are valid configuration."""

    class ConfigurableModel:
        def __init__(self, required_parameter, **kwargs):
            self.required_parameter = required_parameter
            self.configuration = kwargs

    params = {
        "required_parameter": 1,
        "feature_enabled": True,
        "max_retries": 3,
    }

    # This is the configuration that SolaraViz must be able to validate before
