from urllib.parse import parse_qs, urlsplit

from nix_auto_follow.cli import LockFile, Node, check_lock_file


GIT_URL = "https://github.com/SuperSandro2000/nixpkgs.git"


def assert_git_url(
    url: str,
    *,
    ref: str | None = None,
    rev: str | None = None,
    shallow: bool = False,
) -> None:
    parsed = urlsplit(url)

    assert parsed.scheme == "git+https"
    assert parsed.netloc == "github.com"
    # Git flake refs are URL query parameters, not path suffixes. This is
    # particularly important because branch names may themselves contain "/".
    assert parsed.path == "/SuperSandro2000/nixpkgs.git"

    query = parse_qs(parsed.query)
    if ref is None:
        assert "ref" not in query
    else:
        assert query.get("ref") == [ref]

    if rev is None:
        assert "rev" not in query
    else:
        assert query.get("rev") == [rev]

    if shallow:
        assert query.get("shallow") == ["1"]
    else:
        assert "shallow" not in query


def test_git_node_reconstructs_ref_and_shallow_as_url_options() -> None:
    # This represents the flake input from the issue:
    # git+https://github.com/SuperSandro2000/nixpkgs.git?shallow=1&ref=nixos-unstable
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": GIT_URL,
                "shallow": True,
                "ref": "nixos-unstable",
            }
        }
    )

    assert_git_url(node.get_url(), ref="nixos-unstable", shallow=True)


def test_git_node_reconstructs_revision_as_a_url_option() -> None:
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": GIT_URL,
                "rev": "0123456789abcdef",
            }
        }
    )

    assert_git_url(node.get_url(), rev="0123456789abcdef")


def test_check_lock_file_reports_usable_git_url_instead_of_raising(
    capsys,
) -> None:
    """The check-mode diagnostic that triggered the issue handles git nodes."""
    lock = LockFile.from_dict(
        {
            "root": "root",
            "version": 7,
            "nodes": {
                "root": {"inputs": {"a": "consumer_a", "b": "consumer_b"}},
                "consumer_a": {"inputs": {"nixpkgs": "nixpkgs_a"}},
                "consumer_b": {"inputs": {"nixpkgs": "nixpkgs_b"}},
                "nixpkgs_a": {
                    "original": {
                        "type": "git",
                        "url": GIT_URL,
                        "shallow": True,
                        "ref": "nixos/unstable",
                    },
                    "locked": {"type": "git", "rev": "a" * 40},
                },
                "nixpkgs_b": {
                    "original": {
                        "type": "git",
                        "url": GIT_URL,
                        "shallow": True,
                        "ref": "nixos/unstable",
                    },
                    "locked": {"type": "git", "rev": "b" * 40},
                },
            },
        }
    )

    assert check_lock_file(lock) is False

    output = capsys.readouterr().out
    assert "Unknown type git" not in output
    assert "git+https://github.com/SuperSandro2000/nixpkgs.git" in output

    suggested_url = output.split('nixpkgs.url = "', 1)[1].split('"', 1)[0]
    assert_git_url(suggested_url, ref="nixos/unstable", shallow=True)

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_spec(openapi_version):
    return APISpec(
        title="Nested nullable test",
        version="1.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_reference_has_local_typed_nullable_branch(
    openapi_version,
):
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("My", schema=MySchema)
    schemas = spec.to_dict()["components"]["schemas"]

    assert schemas["Foo"] == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }

    # In OpenAPI 3.0, nullable modifies a type assertion in the same Schema
    # Object. It cannot make a referenced schema nullable, and "null" is not
    # an OpenAPI 3.0 type.
    assert schemas["My"]["properties"]["foo"] == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


def test_openapi_30_nullable_nested_reference_with_metadata_is_locally_typed():
    class ChildSchema(Schema):
        name = fields.String()

    class ParentSchema(Schema):
        child = fields.Nested(
            ChildSchema,
            allow_none=True,
            metadata={"description": "An optional child"},
        )

    spec = make_spec("3.0.3")
    spec.components.schema("Parent", schema=ParentSchema)
    property_schema = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "child"
    ]

    # Metadata makes ordinary nested-reference conversion use allOf. The
    # nullable representation must still use a locally typed nullable branch,
    # rather than nullable beside an allOf/reference or JSON-Schema type:null.
    assert property_schema == {
        "description": "An optional child",
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ],
    }


def test_openapi_30_nullable_fields_with_a_local_type_keep_nullable():
    class ChildSchema(Schema):
        value = fields.Integer()

    class ValuesSchema(Schema):
        text = fields.String(allow_none=True)
        children = fields.Nested(ChildSchema, many=True, allow_none=True)

    spec = make_spec("3.0.3")
    spec.components.schema("Values", schema=ValuesSchema)
    properties = spec.to_dict()["components"]["schemas"]["Values"]["properties"]

    # These fields already assert their type in their own Schema Object, so
    # normal OpenAPI 3.0 nullable representation remains correct.
    assert properties["text"] == {"type": "string", "nullable": True}
    assert properties["children"] == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Child"},
        "nullable": True,
    }


def test_nullable_nested_reference_keeps_openapi_2_and_31_behavior():
    class ChildSchema(Schema):
        value = fields.Integer()

    class ParentSchema(Schema):
        child = fields.Nested(ChildSchema, allow_none=True)

    swagger_spec = make_spec("2.0")
    swagger_spec.components.schema("Parent", schema=ParentSchema)
    assert swagger_spec.to_dict()["definitions"]["Parent"]["properties"]["child"] == {
        "$ref": "#/definitions/Child",
        "x-nullable": True,
    }

    openapi_31_spec = make_spec("3.1.0")
    openapi_31_spec.components.schema("Parent", schema=ParentSchema)
    assert openapi_31_spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "child"
    ] == {
        "anyOf": [
            {"$ref": "#/components/schemas/Child"},
            {"type": "null"},
        ]
    }

