import pytest

from sqlglot import exp, parse_one, transpile
from sqlglot.errors import ParseError


@pytest.mark.parametrize(
    "sql, expected",
    [
        (
            "SELECT 'hello' || 'world' AS value",
            "SELECT 'hello' + 'world' AS value",
        ),
        (
            "SELECT first_name || ' ' || last_name FROM users",
            "SELECT first_name + ' ' + last_name FROM users",
        ),
        (
            "SELECT UPPER(first_name || ' ' || last_name) FROM users",
            "SELECT UPPER(first_name + ' ' + last_name) FROM users",
        ),
        (
            "SELECT a || (b || c) FROM t",
            "SELECT a + (b + c) FROM t",
        ),
    ],
)
def test_postgres_string_concatenation_uses_plus_in_tsql(sql, expected):
    assert transpile(sql, read="postgres", write="tsql") == [expected]


def test_tsql_plus_concatenation_is_preserved():
    assert transpile(
        "SELECT first_name + ' ' + last_name FROM users",
        read="tsql",
        write="tsql",
    ) == ["SELECT first_name + ' ' + last_name FROM users"]


def test_tsql_double_pipe_is_not_parsed_as_string_concatenation():
    """
    Regular SQL Server does not use || for string concatenation.

    SQLGlot is not necessarily a SQL validator, so a dialect may reject this
    unsupported syntax or interpret it according to its non-concatenation
    meaning. In either case, it must never create a DPipe concatenation node.
    """
    try:
        expression = parse_one("SELECT a || b FROM t", dialect="tsql")
    except ParseError:
        return

    assert not list(expression.find_all(exp.DPipe))
    assert "||" not in expression.sql(dialect="tsql")


def test_tsql_double_pipe_cannot_be_transpiled_as_concatenation():
    try:
        expression = parse_one("SELECT a || b FROM t", dialect="tsql")
    except ParseError:
        return

    # If accepted for permissive parsing, it must retain non-concatenation
    # semantics when emitted for a dialect where || is a concat operator.
    assert expression.sql(dialect="postgres") == "SELECT a OR b FROM t"

