        "required": ["bar"],
    }

    # `nullable` must modify a type asserted in its own Schema Object. In
    # particular, it must not be put beside an allOf/ref and a JSON Schema
    # `type: null` is not legal in OpenAPI 3.0.
    assert schemas["My"]["properties"]["foo"] == {
        "anyOf": [
            {"type": "object", "nullable": True},
