    # there just like github nodes.
    lock_data = {
        "root": "root",
        "version": 7,
        "nodes": {
            "root": {"inputs": {"a": "a", "b": "b"}},
            "a": {"inputs": {"nixpkgs": "nixpkgs_a"}},
            "b": {"inputs": {"nixpkgs": "nixpkgs_b"}},
            "nixpkgs_a": {
