from io import StringIO
from urllib.parse import parse_qs, urlsplit

from nix_auto_follow.cli import Node, start


GIT_URL = "https://github.com/SuperSandro2000/nixpkgs.git"
REF = "nixos-unstable"


def assert_nix_git_url(url: str) -> None:
    """Validate the important semantic parts of a git flake URL."""
    parsed = urlsplit(url)

    assert parsed.scheme == "git+https"
    assert parsed.netloc == "github.com"
    assert parsed.path == "/SuperSandro2000/nixpkgs.git"
    assert parse_qs(parsed.query) == {
        "shallow": ["1"],
        "ref": [REF],
    }


def test_git_flake_url_uses_query_parameters_for_ref_and_preserves_options() -> None:
    # Git refs are query parameters.  Appending "/<ref>" produces a different
    # repository URL, and appending it after an existing query corrupts that
    # query parameter's value.
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": f"{GIT_URL}?shallow=1",
                "ref": REF,
            }
        }
    )

    assert_nix_git_url(node.get_url())


def test_git_flake_url_reconstructs_normalized_shallow_lockfile_option() -> None:
    # Nix normalizes the URL from the issue when writing a lock file: the base
    # URL, ref, and shallow option can be stored as separate original fields.
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": GIT_URL,
                "shallow": True,
                "ref": REF,
            }
        }
    )

    assert_nix_git_url(node.get_url())


def test_check_mode_reports_a_valid_git_flake_url_in_its_suggestion(capsys) -> None:
    """A conflicting git input must produce remediation output, not a traceback."""
    lock_file = {
        "root": "root",
        "version": 7,
        "nodes": {
            "root": {"inputs": {}},
            "first-parent": {"inputs": {"nixpkgs": "first-nixpkgs"}},
            "second-parent": {"inputs": {"nixpkgs": "second-nixpkgs"}},
            "first-nixpkgs": {
                "locked": {"type": "git", "rev": "111"},
                "original": {
                    "type": "git",
                    "url": GIT_URL,
                    "shallow": True,
                    "ref": REF,
                },
            },
            "second-nixpkgs": {
                "locked": {"type": "git", "rev": "222"},
                "original": {
                    "type": "git",
                    "url": GIT_URL,
                    "shallow": True,
                    "ref": REF,
                },
            },
        },
    }

    try:
        start(
            args=["--check", "-"],
            stdin=StringIO(json.dumps(lock_file)),
            stdout=StringIO(),
        )
    except SystemExit as error:
        # The lock file is deliberately inconsistent, so --check should fail,
        # but only after printing a usable suggestion.
        assert error.code == 1
    else:
        raise AssertionError("check mode should fail for unequal nixpkgs nodes")

    output = capsys.readouterr().out
    assert "Unknown type git" not in output
    suggested_url = output.split('nixpkgs.url = "', 1)[1].split('"', 1)[0]
    assert_nix_git_url(suggested_url)

