import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_collector_is_not_required_model_parameter():
    """A model using **kwargs should not need a literal kwargs model parameter."""

    class ConfigurableModel:
        def __init__(self, population, mode="default", **configuration):
            self.population = population
            self.mode = mode
            self.configuration = configuration

