from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_openapi_303_spec():
    return APISpec(
        title="Nullable nested schemas",
        version="1.0.0",
        openapi_version="3.0.3",
        plugins=[MarshmallowPlugin()],
    )


def test_nullable_nested_schema_uses_oas30_nullable_object_alternative():
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_openapi_303_spec()
    spec.components.schema("My", schema=MySchema)

    foo = spec.to_dict()["components"]["schemas"]["My"]["properties"]["foo"]

    # nullable cannot modify a type inherited through allOf or a $ref in
    # OpenAPI 3.0. A separate typed nullable object branch is required.
    assert foo == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


def test_nullable_nested_schema_with_sibling_metadata_does_not_inherit_nullable():
    class ChildSchema(Schema):
        value = fields.String(required=True)

    class ParentSchema(Schema):
        # Metadata causes normal nested conversion to build an allOf wrapper
        # around the reference before nullable handling occurs.
        child = fields.Nested(
            ChildSchema,
            allow_none=True,
            metadata={"description": "Optional child"},
        )

    spec = make_openapi_303_spec()
    spec.components.schema("Parent", schema=ParentSchema)

    child = spec.to_dict()["components"]["schemas"]["Parent"]["properties"]["child"]

    assert child == {
        "description": "Optional child",
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ],
    }

    # In particular, OAS 3.0 is not OAS 3.1 / JSON Schema: `type: null`
    # is not a valid null branch for this specification version.
    assert {"type": "null"} not in child["anyOf"]

