    Git flake selectors are query parameters.

    This represents the lock-file form of:
    git+https://github.com/SuperSandro2000/nixpkgs.git?shallow=1&ref=nixos-unstable
    """
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": GIT_REPOSITORY_URL,
                "ref": "nixos-unstable",
                "shallow": True,
            }
        }
    )

    parsed = urlsplit(node.get_url())

    assert parsed.scheme == "git+https"
    assert parsed.netloc == "github.com"
    # A branch/ref must not be appended as a repository path component.
    assert parsed.path == "/SuperSandro2000/nixpkgs.git"
    assert parse_qs(parsed.query) == {
        "ref": ["nixos-unstable"],
        "shallow": ["1"],
    }


