def test_check_mode_suggests_a_valid_git_flake_url_instead_of_crashing(
    capsys: pytest.CaptureFixture[str],
) -> None:
    """
    The reported crash happens when --check formats its remediation message for
    two unequal inputs, one of which has original.type == "git".
    """
    lock_file = {
        "version": 7,
        "root": "root",
        "nodes": {
            "root": {"inputs": {"first": "first", "second": "second"}},
            "first": {"inputs": {"nixpkgs": "git_nixpkgs"}},
            "second": {"inputs": {"nixpkgs": "github_nixpkgs"}},
            "git_nixpkgs": {
                "original": {
                    "type": "git",
                    "url": GIT_REPOSITORY_URL,
                    "ref": "nixos-unstable",
                    "shallow": True,
                },
                "locked": {
                    "type": "git",
                    "url": GIT_REPOSITORY_URL,
                    "rev": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                },
            },
            "github_nixpkgs": {
                "original": {
                    "type": "github",
                    "owner": "NixOS",
                    "repo": "nixpkgs",
                    "ref": "nixos-unstable",
                },
                "locked": {
                    "type": "github",
                    "owner": "NixOS",
                    "repo": "nixpkgs",
                    "rev": "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
                },
            },
        },
    }

    with pytest.raises(SystemExit) as result:
        start(args=["--check", "-"], stdin=io.StringIO(json.dumps(lock_file)))

    assert result.value.code == 1
    output = capsys.readouterr().out
    assert "Unknown type git" not in output

    suggested_git_url = output.split('nixpkgs.url = "', 1)[1].split('"', 1)[0]
    parsed = urlsplit(suggested_git_url)

    assert parsed.scheme == "git+https"
    assert parsed.netloc == "github.com"
    assert parsed.path == "/SuperSandro2000/nixpkgs.git"
    assert parse_qs(parsed.query) == {
        "ref": ["nixos-unstable"],
        "shallow": ["1"],
    }

