from streamlink import Streamlink
from streamlink.plugins.kick import Kick


@pytest.mark.parametrize(
    ("url", "api_url", "api_response", "expected_metadata"),
    [
        (
            "https://kick.com/zmok",
            "https://kick.com/api/v2/channels/zmok/livestream",
            {
                "data": {
                    "playback_url": "https://cdn.example.test/live/master.m3u8",
                    "id": 12345,
                    "category": {"name": "Games"},
                    "session_title": "Live title",
                },
            },
            {
                "id": 12345,
                "author": "zmok",
                "category": "Games",
                "title": "Live title",
            },
        ),
        (
            "https://kick.com/kukudota2/videos/4acba712-a1cd-45b0-8ce0-4b534d4c271f",
            "https://kick.com/api/v1/video/4acba712-a1cd-45b0-8ce0-4b534d4c271f",
            {
                "source": "https://cdn.example.test/vod/master.m3u8",
                "livestream": {
                    "session_title": "VOD title",
                    "channel": {
                        "user": {
                            "username": "kukudota2",
                        },
                    },
                },
            },
            {
                "id": "4acba712-a1cd-45b0-8ce0-4b534d4c271f",
                "author": "kukudota2",
                "title": "VOD title",
            },
        ),
    ],
)
def test_kick_api_requests_are_authenticated_and_do_not_get_forbidden(
    requests_mock,
    url,
    api_url,
    api_response,
    expected_metadata,
):
    """
    Kick's API rejects direct requests with HTTP 403.

    A successful extraction must first obtain the XSRF token from Kick and use
    it when requesting both livestream and VOD API endpoints. The mocked API
    deliberately behaves like the protected API: any missing or malformed
    authentication/request context is rejected with 403.
    """
    token = "kick-xsrf-token"
    received_headers = {}

    requests_mock.get(
        "https://kick.com/",
        cookies={"XSRF-TOKEN": token},
        text="<html></html>",
    )

    def protected_api(request, context):
        received_headers.update(request.headers)

        if (
            request.headers.get("Authorization") != f"Bearer {token}"
            or request.headers.get("Referer") != url
            or request.headers.get("Accept") != "application/json"
        ):
            context.status_code = 403
            return {"error": "Request blocked by security policy."}

        context.status_code = 200
        return api_response

    requests_mock.get(api_url, json=protected_api)

    # A real master playlist makes sure that the plugin reaches stream
    # extraction, rather than merely accepting an API response.
    requests_mock.get(
        "https://cdn.example.test/live/master.m3u8",
        text=(
            "#EXTM3U\n"
            "#EXT-X-STREAM-INF:BANDWIDTH=1000000,RESOLUTION=1280x720\n"
            "https://cdn.example.test/live/720p.m3u8\n"
        ),
    )
    requests_mock.get(
        "https://cdn.example.test/vod/master.m3u8",
        text=(
            "#EXTM3U\n"
            "#EXT-X-STREAM-INF:BANDWIDTH=1000000,RESOLUTION=1280x720\n"
            "https://cdn.example.test/vod/720p.m3u8\n"
        ),
    )

    plugin = Kick(Streamlink(), url)
    streams = plugin.streams()

    assert streams
    assert received_headers["Authorization"] == f"Bearer {token}"
    assert received_headers["Referer"] == url
    assert received_headers["Accept"] == "application/json"

    for attribute, value in expected_metadata.items():
        assert getattr(plugin, attribute) == value

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_spec(openapi_version):
    return APISpec(
        title="Nested nullable test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )


def nested_ref_from_schema(schema):
    """Return the referenced schema from either supported reference form."""
    if "$ref" in schema:
        return schema["$ref"]

    assert set(schema) == {"allOf"}
    assert len(schema["allOf"]) == 1
    assert set(schema["allOf"][0]) == {"$ref"}
    return schema["allOf"][0]["$ref"]


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_nullable_nested_reference_uses_a_nullable_typed_anyof_branch(
    openapi_version,
):
    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    child_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "child"
    ]

    # OpenAPI 3.0 nullable must appear in the same Schema Object as its type.
    # In particular, it must not be a sibling of a $ref or allOf containing it.
    assert child_property == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ]
    }


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
@pytest.mark.parametrize(
    ("nested_kwargs", "expected_sibling"),
    [
        (
            {"metadata": {"description": "An optional child object"}},
            {"description": "An optional child object"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
    ],
)
def test_nullable_nested_reference_with_sibling_properties_is_compliant(
    openapi_version, nested_kwargs, expected_sibling
):
    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        # Existing nested conversion normally uses allOf when a nested ref has
        # sibling schema properties. That must not cause nullable to be put on
        # the allOf wrapper.
        child = fields.Nested(Child, allow_none=True, **nested_kwargs)

    spec = make_spec(openapi_version)
    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    child_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "child"
    ]

    assert child_property.items() >= expected_sibling.items()
    assert "nullable" not in child_property
    assert "allOf" not in child_property
    assert set(child_property) == {*expected_sibling, "anyOf"}

    alternatives = child_property["anyOf"]
    assert len(alternatives) == 2
    assert alternatives[0] == {"type": "object", "nullable": True}
    assert nested_ref_from_schema(alternatives[1]) == "#/components/schemas/Child"


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_nullable_nested_many_remains_nullable_on_its_array_type(openapi_version):
    class Child(Schema):
        value = fields.Integer()

    class Parent(Schema):
        children = fields.Nested(Child, many=True, allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    children_property = spec.to_dict()["components"]["schemas"]["Parent"][
        "properties"
    ]["children"]

    # The outer schema itself asserts type: array, so nullable is meaningful
    # directly on it and describes null-or-array, not null array items.
    assert children_property == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Child"},
        "nullable": True,
    }


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_other_nullable_typed_fields_keep_normal_openapi_30_nullable_behavior(
    openapi_version,
):
    class Parent(Schema):
        name = fields.String(allow_none=True)
        count = fields.Integer(allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("Parent", schema=Parent)

    properties = spec.to_dict()["components"]["schemas"]["Parent"]["properties"]
    assert properties["name"] == {"type": "string", "nullable": True}
    assert properties["count"] == {"type": "integer", "nullable": True}


def test_openapi_2_nullable_nested_reference_remains_x_nullable():
    class Child(Schema):
        value = fields.Integer()

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    spec = make_spec("2.0")
    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    assert spec.to_dict()["definitions"]["Parent"]["properties"]["child"] == {
        "$ref": "#/definitions/Child",
        "x-nullable": True,
    }


def test_openapi_31_nullable_nested_reference_keeps_json_schema_null_type():
    class Child(Schema):
        value = fields.Integer()

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    spec = make_spec("3.1.0")
    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    child_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "child"
    ]

    assert child_property == {
        "anyOf": [
            {"$ref": "#/components/schemas/Child"},
            {"type": "null"},
        ]
    }

