from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_parameter_is_not_treated_as_missing_required_parameter():
    class ConfigurableModel:
        def __init__(self, **kwargs):
            self.configuration = kwargs

    # A bare **kwargs parameter is optional and must not itself be required.
    _check_model_params(ConfigurableModel.__init__, {})


def test_kwargs_model_allows_additional_configuration_parameters():
    class ConfigurableModel:
        def __init__(self, population_size, **kwargs):
            self.population_size = population_size
            self.configuration = kwargs

    # Extra visualization parameters are valid because the model can receive them
    # through **kwargs.
    _check_model_params(
        ConfigurableModel.__init__,
        {
            "population_size": 10,
            "custom_option": "enabled",
            "another_optional_setting": 3,
        },
    )


