import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_spec(openapi_version="3.0.3"):
    return APISpec(
        title="Nullable nested schemas",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )


def schema_property(spec, child_schema, parent_schema, property_name):
    spec.components.schema("Child", schema=child_schema)
    spec.components.schema("Parent", schema=parent_schema)
    return spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        property_name
    ]


def nullable_child_anyof():
    """The OpenAPI 3.0 representation proposed by the issue."""
    return {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ]
    }


@pytest.mark.parametrize("openapi_version", ("3.0.0", "3.0.3"))
def test_openapi30_nullable_nested_reference_is_not_nullable_allof(openapi_version):
    """nullable must be paired with a type in its own Schema Object."""

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    child = schema_property(make_spec(openapi_version), Child, Parent, "child")

    assert child == nullable_child_anyof()
    assert "nullable" not in child
    assert "allOf" not in child


@pytest.mark.parametrize(
    ("field_kwargs", "expected_extra"),
    [
        (
            {"metadata": {"description": "An optional child"}},
            {"description": "An optional child"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
        ({"load_only": True}, {"writeOnly": True}),
    ],
)
def test_openapi30_nullable_nested_reference_with_sibling_attributes_is_compliant(
    field_kwargs, expected_extra
):
    """Nested references with sibling attributes must not retain nullable/allOf.

    Metadata and read/write flags cause apispec to represent a Nested reference
    with ``allOf``. A fix which handles only a bare ``$ref`` leaves these
    normal public Marshmallow field configurations invalid under OAS 3.0.3.
    """

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True, **field_kwargs)

    child = schema_property(make_spec(), Child, Parent, "child")

    assert child == {**expected_extra, **nullable_child_anyof()}
    assert "nullable" not in child
    assert "allOf" not in child


def test_openapi30_nullable_many_nested_schema_keeps_nullable_with_array_type():
    """For many=True, nullable modifies the directly asserted array type."""

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        children = fields.Nested(Child, many=True, allow_none=True)

    children = schema_property(make_spec(), Child, Parent, "children")

    assert children == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Child"},
        "nullable": True,
    }


def test_openapi30_nullable_nested_list_item_uses_compliant_reference_union():
    """The requirement also applies when Nested is used as a List item."""

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        children = fields.List(fields.Nested(Child, allow_none=True))

    children = schema_property(make_spec(), Child, Parent, "children")

    assert children == {
        "type": "array",
        "items": nullable_child_anyof(),
    }


def test_openapi30_non_nullable_nested_schema_remains_a_plain_reference():
    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child)

    child = schema_property(make_spec(), Child, Parent, "child")

    assert child == {"$ref": "#/components/schemas/Child"}


def test_openapi31_nullable_nested_schema_uses_json_schema_null_type():
    """The OpenAPI 3.0 workaround must not alter the OpenAPI 3.1 output."""

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    child = schema_property(make_spec("3.1.0"), Child, Parent, "child")

    assert child == {
        "anyOf": [
            {"$ref": "#/components/schemas/Child"},
            {"type": "null"},
        ]
    }

