import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_model_params_support_arbitrary_configuration_with_var_keyword_init():
    """Models using **kwargs must not require a literal ``kwargs`` parameter.

    Their additional configuration keys must also be allowed, since those keys
    are what Python passes through the variable-keyword argument.
    """

    class ConfigurableModel:
        def __init__(self, required_parameter, **configuration):
            self.required_parameter = required_parameter
            self.configuration = configuration

    _check_model_params(
        ConfigurableModel.__init__,
        {
            "required_parameter": 1,
            "optional_setting": "enabled",
            "another_setting": 42,
        },
    )

    # A model whose only arguments are **kwargs is also valid with no params.
    class KeywordOnlyConfigurationModel:
        def __init__(self, **configuration):
            self.configuration = configuration

    _check_model_params(KeywordOnlyConfigurationModel.__init__, {})
    _check_model_params(
        KeywordOnlyConfigurationModel.__init__,
        {"custom_option": True},
    )


def test_var_keyword_init_still_validates_declared_required_parameters():
    """Accepting arbitrary configuration must not hide missing normal arguments."""

    class ConfigurableModel:
        def __init__(self, required_parameter, **configuration):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_parameter"
    ):
        _check_model_params(
            ConfigurableModel.__init__,
            {"optional_setting": "enabled"},
        )

