import io
import unittest

import cpplint
import pytest


REDUNDANT_SEMICOLON = "You don't need a ; after a }"


def trailing_semicolon_errors(source):
    """Return brace diagnostics produced by the trailing-semicolon check."""
    lines = source.splitlines()
    clean_lines = cpplint.CleansedLines(lines)
    errors = []

    def record_error(filename, linenum, category, confidence, message):
        if category == "readability/braces":
            errors.append((linenum, message))

    for linenum in range(len(lines)):
        cpplint.CheckTrailingSemicolon(
            "concepts.cc", clean_lines, linenum, record_error
        )
    return errors


def test_concept_requires_expression_semicolon_is_not_reported():
    errors = trailing_semicolon_errors(
        """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};

void RedundantFunctionBody() {};
"""
    )

    # The first semicolon terminates the concept definition and is required.
    # The second follows an ordinary function body and is still redundant.
    assert errors == [(5, REDUNDANT_SEMICOLON)]


@pytest.mark.parametrize(
    "source",
    [
        # A declaration can be wrapped between its name and '='.
        """\
template <typename T>
concept IndexableToChar
    = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
""",
        # The requires keyword, parameters, and opening brace can be wrapped.
        """\
template <typename T>
concept HasValueType =
    requires
        (T value)
    {
      typename T::value_type;
    };
""",
        # A requires expression need not have a local parameter list.
        """\
template <typename T>
concept HasNestedType =
    requires {
      typename T::type;
    };
""",
    ],
)
def test_wrapped_concept_requires_expression_semicolon_is_not_reported(source):
    assert trailing_semicolon_errors(source) == []


def test_only_concept_requires_expression_is_exempt_from_semicolon_rule():
    errors = trailing_semicolon_errors(
        """\
template <typename T>
concept HasType = requires(T value) {
  typename T::type;
};

auto constrained_lambda = [](auto value) requires true {
  return value;
};

void OrdinaryFunction() {};
"""
    )

    # A requires-clause on a lambda is not a concept definition, and neither
    # is an ordinary function.  Their body-following semicolons remain wrong.
    assert errors == [
        (6, REDUNDANT_SEMICOLON),
        (9, REDUNDANT_SEMICOLON),
    ]


