import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def _make_spec(openapi_version, *, schema_name_resolver=None):
    plugin = MarshmallowPlugin(schema_name_resolver=schema_name_resolver)
    return APISpec(
        title="Nullable nested schemas",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[plugin],
    )


def _schema_property(spec, schema_name, property_name):
    document = spec.to_dict()
    if spec.openapi_version.major < 3:
        return document["definitions"][schema_name]["properties"][property_name]
    return document["components"]["schemas"][schema_name]["properties"][property_name]


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_schema_is_a_nullable_object_or_reference(
    openapi_version,
):
    """A nullable Nested reference must not put nullable next to an allOf/$ref."""
    spec = _make_spec(openapi_version)

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    assert _schema_property(spec, "Parent", "child") == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ]
    }


@pytest.mark.parametrize(
    "field_kwargs",
    [
        {"metadata": {"description": "An optional child"}},
        {"dump_only": True},
        {
            "dump_only": True,
            "metadata": {"description": "An optional child"},
        },
    ],
)
def test_openapi_30_nullable_annotated_nested_schema_is_not_nullable_allof(
    field_kwargs,
):
    """Field annotations must not restore the invalid nullable/allOf form.

    Marshmallow nested fields with annotations are normally wrapped in allOf so
    that the annotation may be a sibling of the reference.  In OpenAPI 3.0,
    nullable is ineffective in that outer object because its type is inherited
    through allOf.  The nullable object and the reference must instead be
    alternatives.
    """
    spec = _make_spec("3.0.3")

    class Child(Schema):
        value = fields.String(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True, **field_kwargs)

    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    expected = {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Child"},
        ]
    }
    if "metadata" in field_kwargs:
        expected["description"] = "An optional child"
    if field_kwargs.get("dump_only"):
        expected["readOnly"] = True

    child_property = _schema_property(spec, "Parent", "child")
    assert child_property == expected
    assert "nullable" not in child_property
    assert "allOf" not in child_property


def test_openapi_30_nullable_inline_nested_schema_has_a_local_type():
    """An inline nested schema is compliant because nullable shares its type."""
    spec = _make_spec("3.0.3", schema_name_resolver=lambda schema: None)

    class Child(Schema):
        value = fields.Integer(required=True)

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    spec.components.schema("Parent", schema=Parent)

    assert _schema_property(spec, "Parent", "child") == {
        "type": "object",
        "properties": {"value": {"type": "integer"}},
        "required": ["value"],
        "nullable": True,
    }


def test_nullable_nested_array_remains_a_nullable_array_in_openapi_30():
    """For many=True the nullable value is the array itself, which has a type."""
    spec = _make_spec("3.0.3")

    class Child(Schema):
        value = fields.Integer()

    class Parent(Schema):
        children = fields.Nested(Child, many=True, allow_none=True)

    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    assert _schema_property(spec, "Parent", "children") == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Child"},
        "nullable": True,
    }


@pytest.mark.parametrize(
    ("openapi_version", "expected"),
    [
        (
            "2.0",
            {
                "$ref": "#/definitions/Child",
                "x-nullable": True,
            },
        ),
        (
            "3.1.0",
            {
                "anyOf": [
                    {"$ref": "#/components/schemas/Child"},
                    {"type": "null"},
                ]
            },
        ),
    ],
)
def test_nullable_nested_schema_keeps_non_openapi_30_behavior(
    openapi_version, expected
):
    spec = _make_spec(openapi_version)

    class Child(Schema):
        value = fields.Integer()

    class Parent(Schema):
        child = fields.Nested(Child, allow_none=True)

    spec.components.schema("Child", schema=Child)
    spec.components.schema("Parent", schema=Parent)

    assert _schema_property(spec, "Parent", "child") == expected

