import textwrap

import cpplint
import pytest


REDUNDANT_SEMICOLON = "You don't need a ; after a }"


class ErrorCollector:
    """Collect diagnostics emitted through cpplint's normal error callback."""

    def __init__(self):
        self.errors = []

    def __call__(self, filename, linenum, category, confidence, message):
        self.errors.append((linenum, category, confidence, message))


def lint(source):
    collector = ErrorCollector()
    cpplint.ProcessFileData(
        "concepts.cc",
        "cc",
        textwrap.dedent(source).splitlines(),
        collector,
    )
    return collector.errors


def redundant_brace_semicolon_errors(source):
    return [
        error
        for error in lint(source)
        if error[1] == "readability/braces" and REDUNDANT_SEMICOLON in error[3]
    ]


@pytest.mark.parametrize(
    "source",
    [
        # The form reported in the issue, including a compound requirement.
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # A concept definition may be wrapped before its assignment operator.
        # This is still one declaration whose terminating semicolon is required.
        """
        template <typename T>
        concept IndexableToChar
            = requires(T t) {
              { t[0] } -> std::convertible_to<char>;
            };
        """,
        # Whitespace between the requires parameter list and its compound
        # requirement body is insignificant.
        """
        template <typename T>
        concept HasValue = requires(T t)
        {
          t.value();
        };
        """,
        # The requires-expression can also begin on a later line than the
        # assignment operator.
        """
        template <typename T>
        concept HasValue =
            requires(T t)
            {
              t.value();
            };
        """,
        # The body has no language-imposed small line-count limit.  In
        # particular, formatting a long list of requirements must not turn its
        # mandatory declaration semicolon into a readability/braces warning.
        """
        template <typename T>
        concept RichInterface = requires(T t) {
          t.first();
          t.second();
          t.third();
          t.fourth();
          t.fifth();
          t.sixth();
          t.seventh();
          t.eighth();
          t.ninth();
          t.tenth();
          t.eleventh();
        };
        """,
    ],
)
def test_required_semicolon_after_concept_requires_expression_is_not_reported(source):
    assert redundant_brace_semicolon_errors(source) == []

