import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def _make_spec(openapi_version="3.0.3", **plugin_options):
    return APISpec(
        title="Nullable nested fields",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin(**plugin_options)],
    )


def _contains_ref(value, ref):
    if isinstance(value, dict):
        return value.get("$ref") == ref or any(
            _contains_ref(child, ref) for child in value.values()
        )
    if isinstance(value, list):
        return any(_contains_ref(child, ref) for child in value)
    return False


def test_openapi30_nullable_nested_schema_is_a_nullable_object_union():
    """The issue example must not put nullable next to an allOf-only reference."""

    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = _make_spec()
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("My", schema=MySchema)

    foo = spec.to_dict()["components"]["schemas"]["My"]["properties"]["foo"]

    assert foo == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


@pytest.mark.parametrize(
    ("field_kwargs", "expected_outer_property"),
    [
        ({"metadata": {"description": "Optional Foo"}}, ("description", "Optional Foo")),
        ({"dump_only": True}, ("readOnly", True)),
    ],
)
def test_openapi30_nullable_nested_with_siblings_does_not_put_nullable_beside_allof(
    field_kwargs, expected_outer_property
):
    """Sibling properties make Nested use allOf before nullable handling.

    This must remain compliant: an outer ``nullable: true`` cannot make an
    allOf-only schema nullable because that schema has no local type assertion.
    """

    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class ParentSchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True, **field_kwargs)

    spec = _make_spec()
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Parent", schema=ParentSchema)

    foo = spec.to_dict()["components"]["schemas"]["Parent"]["properties"]["foo"]
    property_name, property_value = expected_outer_property

    assert foo[property_name] == property_value
    assert foo.get("nullable") is not True
    assert "allOf" not in foo

    # The branch which permits null must itself assert object. The nested
    # schema, possibly wrapped to retain its siblings, remains the other branch.
    assert len(foo["anyOf"]) == 2
    assert foo["anyOf"][0] == {"type": "object", "nullable": True}
    assert _contains_ref(foo["anyOf"][1], "#/components/schemas/Foo")


def test_openapi30_nullable_nested_with_inline_schema_uses_local_object_type():
    """Inlining has a local object type, so ordinary nullable is valid."""

    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class ParentSchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = _make_spec(schema_name_resolver=lambda schema: None)
    spec.components.schema("Parent", schema=ParentSchema)

    foo = spec.to_dict()["components"]["schemas"]["Parent"]["properties"]["foo"]

    assert foo["type"] == "object"
    assert foo["nullable"] is True
    assert foo["properties"]["bar"] == {"type": "integer"}
    assert "allOf" not in foo
    assert "anyOf" not in foo


def test_openapi30_nullable_nested_many_is_nullable_array_not_nullable_reference():
    """many=True describes an array, which provides its own local type."""

    class FooSchema(Schema):
        value = fields.String()

    class ParentSchema(Schema):
        foos = fields.Nested(FooSchema, many=True, allow_none=True)

    spec = _make_spec()
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Parent", schema=ParentSchema)

    foos = spec.to_dict()["components"]["schemas"]["Parent"]["properties"]["foos"]

    assert foos == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
