            assert line == "", "blank line retained whitespace: {!r}".format(line)


def assert_clean_quote_only_lines(markdown):
    """Quote-only separator lines must not carry a trailing marker space."""
    for line in markdown.splitlines():
        if line and all(character in "> " for character in line):
            assert line == line.rstrip(), (
                "blockquote separator retained trailing whitespace: {!r}".format(line)
            )


def test_paragraphs_in_list_item_have_empty_unindented_separator():
    result = md("<ul><li><p>1</p><p>2</p></li></ul>")

    # Continuation text remains indented as required by Markdown, but the
    # separator itself is an actually empty line.
    assert result == "\n\n* 1\n\n  2\n"
    assert_no_whitespace_only_lines(result)


def test_multiple_paragraphs_in_list_item_have_no_indented_blank_lines():
    result = md(
        "<ul><li><p>first</p><p>second</p><p>third</p></li></ul>"
    )

    assert result == "\n\n* first\n\n  second\n\n  third\n"
    assert_no_whitespace_only_lines(result)


def test_paragraphs_in_blockquote_use_clean_quote_separator():
