        "parse_variant_playlist",
        lambda stream_session, stream_url: {
            "720p": HLSStream(stream_session, stream_url),
        },
    )

    streams = plugin.streams()

    assert stream_name in streams
    assert len(requests) == 1, "API access must not depend on a token-fetch preflight request"

    request = requests[0]
    headers = request["headers"]

    assert request["raise_for_status"] is False
    assert headers["referer"] == url
    assert headers["user-agent"] == useragents.CHROME
    assert headers["accept"] == "application/json"
    assert headers["accept-language"] == "en-US"
    assert "authorization" not in headers

    # These are the fetch metadata and Chromium client-hint headers sent by a
    # browser request to Kick's same-origin JSON APIs.
    assert headers["sec-fetch-dest"] == "empty"
    assert headers["sec-fetch-mode"] == "cors"
    assert headers["sec-fetch-site"] == "same-origin"
    assert headers["sec-fetch-user"] == "?1"
    assert headers["sec-ch-ua-mobile"] == "?0"
    assert headers["sec-ch-ua-platform"] == '"Windows"'
    assert headers["sec-ch-ua-arch"] == '"x86"'
    assert headers["sec-ch-ua-bitness"] == '"64"'

    match = re.search(r"Chrome/(?P<full>(?P<major>\d+)\S+)", useragents.CHROME)
    assert match is not None
    assert f'"Chromium";v="{match["major"]}"' in headers["sec-ch-ua"]
    assert headers["sec-ch-ua-full-version"] == f'"{match["full"]}"'
    assert f'"Chromium";v="{match["full"]}"' in headers["sec-ch-ua-full-version-list"]

    for name, value in expected_metadata.items():
        assert getattr(plugin, name) == value


