import urllib.parse

from nix_auto_follow.cli import LockFile, Node, check_lock_file


def test_git_node_reconstructs_git_flake_url_with_supported_options() -> None:
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": "https://github.com/SuperSandro2000/nixpkgs.git",
                "ref": "nixos-unstable",
                "rev": "0123456789abcdef0123456789abcdef01234567",
                "shallow": True,
                "submodules": True,
                "allRefs": True,
            }
        }
    )

    url = node.get_url()
    parsed = urllib.parse.urlsplit(url)

    assert f"{parsed.scheme}://{parsed.netloc}{parsed.path}" == (
        "git+https://github.com/SuperSandro2000/nixpkgs.git"
    )
    assert dict(urllib.parse.parse_qsl(parsed.query)) == {
        "ref": "nixos-unstable",
        "rev": "0123456789abcdef0123456789abcdef01234567",
        "shallow": "1",
        "submodules": "1",
        "allRefs": "1",
    }


def test_git_node_without_options_has_no_query_separator() -> None:
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": "ssh://git@github.com/example/repository.git",
            }
        }
    )

    assert node.get_url() == "git+ssh://git@github.com/example/repository.git"


def test_git_node_escapes_query_parameter_values() -> None:
    # '&' is permitted in a Git ref, but is a query-string separator and must
    # therefore be escaped when reconstructing the flake URL.
    node = Node.from_dict(
        {
            "original": {
                "type": "git",
                "url": "https://example.invalid/repository.git",
                "ref": "feature&urgent",
            }
        }
    )

    url = node.get_url()

    assert "ref=feature%26urgent" in url
    assert dict(urllib.parse.parse_qsl(urllib.parse.urlsplit(url).query)) == {
        "ref": "feature&urgent"
    }


