import io
import unittest

import pytest

import cpplint


def lint_source(source):
    """Run cpplint's public file-data processing API and collect diagnostics."""
    errors = []

    def collect_error(filename, linenum, category, confidence, message):
        errors.append((linenum, category, confidence, message))

    # ProcessFileData uses the configured category filters.  Explicitly enable
    # the category under test without depending on process-global command-line
    # state left by other tests.
    old_filters = cpplint._cpplint_state.filters
    try:
        cpplint._cpplint_state.filters = ["-", "+readability/braces"]
        cpplint.ProcessFileData(
            "concept_requires.cc",
            "cc",
            source.splitlines(),
            collect_error,
        )
    finally:
        cpplint._cpplint_state.filters = old_filters

    return errors


@pytest.mark.parametrize(
    "concept_source",
    [
        pytest.param(
            """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
""",
            id="compound-requirement-from-issue",
        ),
        pytest.param(
            """\
template <typename T>
concept SplitAssignment
    = requires(T t) {
  t.value();
};
""",
            id="concept-assignment-on-next-line",
        ),
        pytest.param(
            """\
template <typename T>
concept MultiLineParameters = requires(
    T first,
    T second) {
  first == second;
};
""",
            id="multiline-requires-parameters",
        ),
        pytest.param(
            """\
template <typename T>
concept BraceOnSeparateLine = requires(T t)
{
  typename T::value_type;
};
""",
            id="opening-brace-on-separate-line",
        ),
    ],
)
def test_required_semicolon_after_concept_requires_expression_is_not_reported(
    concept_source,
):
    """The terminating semicolon of a concept requires-expression is required."""
    source = concept_source + "\nvoid RedundantFunctionDeclaration() {};\n"
    brace_errors = [
        error for error in lint_source(source)
        if error[1] == "readability/braces"
    ]

    # The concept's semicolon is required.  The deliberately redundant
    # function semicolon must still be diagnosed, proving the rule was not
    # disabled generally.
    assert len(brace_errors) == 1
    assert brace_errors[0][0] == len(source.splitlines()) - 1
    assert brace_errors[0][3] == "You don't need a ; after a }"


def test_cpplint_unit_suite_remains_compatible():
    """Run the repository suite in an isolated process-global lint state."""
    import cpplint_unittest

    # cpplint_unittest's setUp methods expect the command-line defaults rather
    # than filters configured by this test module or pytest plugins.
    saved_filters = cpplint._cpplint_state.filters
    saved_count = cpplint._cpplint_state.count
    try:
        cpplint._cpplint_state.filters = cpplint._DEFAULT_FILTERS[:]
        cpplint._cpplint_state.count = 0
        suite = unittest.defaultTestLoader.loadTestsFromModule(cpplint_unittest)
        result = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)
    finally:
        cpplint._cpplint_state.filters = saved_filters
        cpplint._cpplint_state.count = saved_count

    assert result.wasSuccessful(), (
        "cpplint_unittest failures: %s; errors: %s"
        % (result.failures, result.errors)
    )

