import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_spec(openapi_version, *, schema_name_resolver=None):
    plugin_kwargs = {}
    if schema_name_resolver is not None:
        plugin_kwargs["schema_name_resolver"] = schema_name_resolver

    return APISpec(
        title="Nested nullable test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin(**plugin_kwargs)],
    )


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_reference_uses_nullable_object_union(
    openapi_version,
):
    class Foo(Schema):
        bar = fields.Integer(required=True)

    class Parent(Schema):
        foo = fields.Nested(Foo, allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("Foo", schema=Foo)
    spec.components.schema("Parent", schema=Parent)

    foo_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "foo"
    ]

    assert foo_property == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }
    # nullable cannot modify a type which is asserted only by a composed/ref
    # schema in OpenAPI 3.0.
    assert "nullable" not in foo_property
    assert "allOf" not in foo_property


@pytest.mark.parametrize(
    ("field_kwargs", "expected_sibling"),
    [
        (
            {"metadata": {"description": "An optional Foo"}},
            {"description": "An optional Foo"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
    ],
)
def test_openapi_30_nullable_nested_reference_with_sibling_attributes_is_compliant(
    field_kwargs, expected_sibling
):
    """Metadata must not make nullable fall back to nullable plus allOf.

    A normal nested reference with sibling schema attributes is represented as
    allOf. That representation remains invalid when allow_none=True because
    nullable does not apply to a type inherited through allOf.
    """

    class Foo(Schema):
        bar = fields.Integer(required=True)

    class Parent(Schema):
        foo = fields.Nested(Foo, allow_none=True, **field_kwargs)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=Foo)
    spec.components.schema("Parent", schema=Parent)

    foo_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "foo"
    ]

    assert foo_property == {
        **expected_sibling,
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ],
    }
    assert "nullable" not in foo_property
    assert "allOf" not in foo_property


def test_openapi_30_nullable_inline_nested_schema_has_local_object_type():
    """Inlining is valid because nullable and type stay in one Schema Object."""

    class Foo(Schema):
        bar = fields.Integer(required=True)

    class Parent(Schema):
        foo = fields.Nested(Foo, allow_none=True)

    spec = make_spec("3.0.3", schema_name_resolver=lambda schema: None)
    spec.components.schema("Parent", schema=Parent)

    foo_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "foo"
    ]

    assert foo_property == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
        "nullable": True,
    }
    assert "allOf" not in foo_property
    assert "anyOf" not in foo_property


def test_openapi_30_nullable_nested_many_keeps_nullable_on_array_type():
    class Foo(Schema):
        bar = fields.Integer(required=True)

    class Parent(Schema):
        foos = fields.Nested(Foo, many=True, allow_none=True)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=Foo)
    spec.components.schema("Parent", schema=Parent)

    foos_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "foos"
    ]

    # This is valid OpenAPI 3.0: nullable and the array type assertion are in
    # the same Schema Object.
    assert foos_property == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_openapi_30_nullable_non_nested_field_remains_type_modifier():
    class Parent(Schema):
        name = fields.String(allow_none=True)

    spec = make_spec("3.0.3")
    spec.components.schema("Parent", schema=Parent)

    name_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "name"
    ]

    assert name_property == {"type": "string", "nullable": True}


def test_openapi_31_nullable_nested_reference_remains_a_null_union():
    class Foo(Schema):
        bar = fields.Integer(required=True)

    class Parent(Schema):
        foo = fields.Nested(Foo, allow_none=True)

    spec = make_spec("3.1.0")
    spec.components.schema("Foo", schema=Foo)
    spec.components.schema("Parent", schema=Parent)

    foo_property = spec.to_dict()["components"]["schemas"]["Parent"]["properties"][
        "foo"
    ]

    assert foo_property == {
        "anyOf": [
            {"$ref": "#/components/schemas/Foo"},
            {"type": "null"},
        ]
    }


def test_openapi_2_nullable_nested_reference_remains_x_nullable():
    class Foo(Schema):
        bar = fields.Integer(required=True)

    class Parent(Schema):
        foo = fields.Nested(Foo, allow_none=True)

    spec = make_spec("2.0")
    spec.components.schema("Foo", schema=Foo)
    spec.components.schema("Parent", schema=Parent)

    foo_property = spec.to_dict()["definitions"]["Parent"]["properties"]["foo"]

    assert foo_property == {
        "$ref": "#/definitions/Foo",
        "x-nullable": True,
    }

"""Regression tests for **kwargs in Solara model parameter validation."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_model_params_accept_extra_configuration_when_init_accepts_kwargs():
    """Extra visualization parameters are valid configuration for ``**kwargs`` models."""

    class ConfigurableModel:
        def __init__(self, population, **kwargs):
            self.population = population
            self.configuration = kwargs

    _check_model_params(
        ConfigurableModel.__init__,
        {
            "population": 10,
            "custom_option": "enabled",
            "another_optional_setting": 42,
        },
    )


def test_model_params_do_not_treat_kwargs_as_a_missing_required_parameter():
    """The VAR_KEYWORD signature parameter itself must not be required."""

    class ConfigurableModel:
        def __init__(self, population, **kwargs):
            pass

    _check_model_params(ConfigurableModel.__init__, {"population": 10})


def test_kwargs_does_not_hide_other_required_parameters():
    """Ignoring ``**kwargs`` must not disable validation of real requirements."""

    class ConfigurableModel:
