import pytest

import sqlglot
from sqlglot import exp


@pytest.mark.parametrize(
    "sql, expected",
    [
        (
            "insert into t(i) values (default)",
            "INSERT INTO t (i) VALUES (DEFAULT)",
        ),
        (
            "INSERT INTO t(i, j) VALUES (DEFAULT, 1)",
            "INSERT INTO t (i, j) VALUES (DEFAULT, 1)",
        ),
        (
            "insert into t(i, j) values (1, default)",
            "INSERT INTO t (i, j) VALUES (1, DEFAULT)",
        ),
        (
            "insert into t(i, j) values (default, 1), (2, default)",
            "INSERT INTO t (i, j) VALUES (DEFAULT, 1), (2, DEFAULT)",
        ),
        (
            "insert into t(i, j, k) values (Default, 1, DEFAULT)",
            "INSERT INTO t (i, j, k) VALUES (DEFAULT, 1, DEFAULT)",
        ),
    ],
)
def test_insert_default_values_are_preserved_as_keywords(sql, expected):
    assert sqlglot.transpile(sql, read="mysql", write="duckdb") == [expected]


def test_default_value_is_not_parsed_as_a_string_literal():
    expression = sqlglot.parse_one(
        "INSERT INTO t (i) VALUES (default)",
        read="mysql",
    )
    values = expression.find(exp.Values)
    value = values.expressions[0].expressions[0]

    assert not isinstance(value, exp.Literal)
    assert expression.sql(dialect="duckdb") == "INSERT INTO t (i) VALUES (DEFAULT)"


def test_default_keyword_remains_distinct_from_default_string_and_identifier():
    string_sql = "INSERT INTO t (i) VALUES ('default')"
    identifier_sql = "INSERT INTO t (i) VALUES (`default`)"

    assert sqlglot.transpile(string_sql, read="mysql", write="duckdb") == [
        "INSERT INTO t (i) VALUES ('default')"
    ]
    assert sqlglot.transpile(identifier_sql, read="mysql", write="duckdb") == [
        'INSERT INTO t (i) VALUES ("default")'
    ]


def test_default_is_preserved_in_other_value_expression_contexts():
    assert sqlglot.transpile(
        "UPDATE t SET i = default",
        read="mysql",
        write="duckdb",
    ) == ["UPDATE t SET i = DEFAULT"]


def test_column_default_constraint_still_generates_a_default_clause():
    assert sqlglot.transpile(
        "CREATE TABLE t (i INT DEFAULT 0)",
        read="mysql",
        write="duckdb",
    ) == ["CREATE TABLE t (i INT DEFAULT 0)"]

import pytest

from markdownify import markdownify as md


def assert_no_whitespace_only_lines(markdown):
    """Blank lines must be truly blank, rather than indentation whitespace."""
    assert all(
        line == "" or line.strip() != ""
        for line in markdown.splitlines()
    ), repr(markdown)


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        (
            "<ul><li><p>one</p><p>two</p></li></ul>",
            "\n\n* one\n\n  two\n",
        ),
        (
            "<ol><li><p>one</p><p>two</p></li></ol>",
            "\n\n1. one\n\n   two\n",
        ),
        (
            "<ul><li><p>one</p><p>two</p><p>three</p></li></ul>",
            "\n\n* one\n\n  two\n\n  three\n",
        ),
    ],
)
def test_list_item_paragraph_separators_have_no_indenting_spaces(html, expected):
    result = md(html)

    assert result == expected
    assert_no_whitespace_only_lines(result)


def test_list_item_empty_lines_are_clean_with_custom_bullet_prefix():
    result = md("<ul><li><p>one</p><p>two</p></li></ul>", bullets="+")

    assert result == "\n\n+ one\n\n  two\n"
    assert_no_whitespace_only_lines(result)


def test_nested_list_item_paragraph_separator_has_no_indentation_only_line():
    result = md(
        "<ul><li><p>outer</p><ul><li><p>one</p><p>two</p></li></ul>"
        "<p>after</p></li></ul>"
    )

    # The nested item and its containing item both add indentation.  None of
    # that indentation should survive on paragraph-separator lines.
    assert_no_whitespace_only_lines(result)
    assert "* outer" in result
    assert "+ one" in result
    assert "    two" in result
    assert "  after" in result


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        (
            "<blockquote><p>one</p><p>two</p></blockquote>",
            "\n> one\n>\n> two\n\n",
        ),
        (
            "<blockquote><p>one</p><p>two</p><p>three</p></blockquote>",
            "\n> one\n>\n> two\n>\n> three\n\n",
        ),
    ],
)
def test_blockquote_paragraph_separators_have_marker_without_trailing_space(
    html, expected
):
    result = md(html)

    assert result == expected
    assert "> \n" not in result
    assert all(not line.endswith(" ") for line in result.splitlines())


def test_nested_blockquote_empty_line_has_no_trailing_space():
    result = md(
        "<blockquote><blockquote><p>one</p><p>two</p></blockquote></blockquote>"
    )

    assert result == "\n> > one\n> >\n> > two\n\n"
    assert "> > \n" not in result
    assert all(not line.endswith(" ") for line in result.splitlines())

