import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


def make_spec(openapi_version):
    return APISpec(
        title="Nested nullable test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )


def schema_property(spec, schema_name, property_name):
    return spec.to_dict()["components"]["schemas"][schema_name]["properties"][
        property_name
    ]


def assert_openapi_30_nullable_nested_reference(schema, reference, **siblings):
    """Assert an OpenAPI 3.0-compliant union for a nullable object reference.

    In OpenAPI 3.0, ``nullable`` modifies only a ``type`` declared in the same
    Schema Object. It cannot be a sibling of an ``allOf`` that supplies the
    referenced object's type.
    """
    assert schema == {
        **siblings,
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": reference},
        ],
    }


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_schema_uses_compliant_union(openapi_version):
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class ParentSchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Parent", schema=ParentSchema)

    assert_openapi_30_nullable_nested_reference(
        schema_property(spec, "Parent", "foo"),
        "#/components/schemas/Foo",
    )


@pytest.mark.parametrize(
    ("nested_kwargs", "expected_siblings"),
    [
        (
            {"metadata": {"description": "An optional Foo"}},
            {"description": "An optional Foo"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
    ],
)
def test_openapi_30_nullable_nested_reference_with_annotations_is_compliant(
    nested_kwargs, expected_siblings
):
    """Annotations must not cause invalid ``nullable`` plus ``allOf`` output."""
    class FooSchema(Schema):
        bar = fields.Integer(required=True)

    class ParentSchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True, **nested_kwargs)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Parent", schema=ParentSchema)

    assert_openapi_30_nullable_nested_reference(
        schema_property(spec, "Parent", "foo"),
        "#/components/schemas/Foo",
        **expected_siblings,
    )


def test_openapi_30_nullable_nested_many_is_nullable_array():
    """For ``many=True``, nullable modifies the array type in the same object."""
    class FooSchema(Schema):
