import io
import unittest

import cpplint
import cpplint_unittest


BRACES_CATEGORY = "readability/braces"
BRACES_MESSAGE = "You don't need a ; after a }"


def _trailing_semicolon_errors(source):
    """Run cpplint's trailing-semicolon check and collect diagnostics."""
    lines = source.splitlines()
    clean_lines = cpplint.CleansedLines(lines)
    errors = []

    def record_error(filename, linenum, category, confidence, message):
        errors.append((linenum, category, confidence, message))

    for linenum in range(len(lines)):
        cpplint.CheckTrailingSemicolon(
            "concept_test.cc", clean_lines, linenum, record_error
        )

    return errors


def _brace_errors(source):
    return [
        error
        for error in _trailing_semicolon_errors(source)
        if error[1] == BRACES_CATEGORY and error[3] == BRACES_MESSAGE
    ]


def test_requires_expression_concept_semicolon_is_not_reported():
    errors = _brace_errors(
        """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};

void RedundantFunctionSemicolon() {};
"""
    )

    # The concept definition's semicolon is required. The ordinary function's
    # semicolon remains redundant and must still be diagnosed.
    assert errors == [(5, BRACES_CATEGORY, 4, BRACES_MESSAGE)]


def test_long_requires_expression_concept_semicolon_is_not_reported():
    requirements = "\n".join(
        "  { t.member%d() } -> std::same_as<int>;" % number
        for number in range(12)
    )

    errors = _brace_errors(
        """\
template <typename T>
concept HasManyRequirements = requires(T t) {
%s
};
"""
        % requirements
    )

    # There is no language limit on the number of requirements. The required
    # terminating semicolon must not be diagnosed based on brace distance.
    assert errors == []


def test_concept_assignment_and_requires_expression_may_be_split_over_lines():
    errors = _brace_errors(
        """\
template <typename T>
concept Incrementable
    = requires(T value) {
        ++value;
      };
"""
    )

    # Newlines are whitespace in a concept definition, including around '='.
    assert errors == []


def test_existing_cpplint_regression_suite_still_passes():
    """Keep the established lint behavior covered alongside the new syntax."""
    suite = unittest.defaultTestLoader.loadTestsFromModule(cpplint_unittest)
    result = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)

    assert result.wasSuccessful(), (
        "Existing cpplint regression tests failed:\n"
        + "\n".join(str(failure) for _, failure in result.failures + result.errors)
    )

