def test_check_mode_reports_git_flake_url_instead_of_crashing(
    capsys: pytest.CaptureFixture[str],
) -> None:
    """
    Reproduce the issue through check mode.

    A mismatched pair of inputs makes check mode call get_url() while preparing
    its user-facing follows suggestion.  Git inputs must be rendered in that
    suggestion rather than raising ``ValueError: Unknown type git``.
    """
    lock_file = {
        "nodes": {
            "root": {
                "inputs": {
                    "nixpkgs": "git_nixpkgs",
                }
            },
            "dependency": {
                "inputs": {
                    "nixpkgs": "other_nixpkgs",
                }
            },
            "git_nixpkgs": {
                "original": {
                    "type": "git",
                    "url": "https://github.com/SuperSandro2000/nixpkgs.git",
                    "shallow": True,
                    "ref": "nixos-unstable",
                }
            },
            "other_nixpkgs": {
                "original": {
                    "type": "github",
                    "owner": "NixOS",
                    "repo": "nixpkgs",
                    "ref": "nixos-unstable",
                }
            },
        },
        "root": "root",
        "version": 7,
    }

    # A mismatch is expected to make --check exit with status 1, but it must
    # reach that normal failure path and print a valid git URL recommendation.
    with pytest.raises(SystemExit) as error:
        start(args=["--check", "-"], stdin=io.StringIO(json.dumps(lock_file)))

    assert error.value.code == 1
    output = capsys.readouterr().out
    assert "Unknown type git" not in output
    assert 'nixpkgs.url = "git+https://github.com/SuperSandro2000/nixpkgs.git?' in output

    suggested_git_url = next(
        part.split('"')[1]
        for part in output.splitlines()
        if 'nixpkgs.url = "git+https://github.com/SuperSandro2000/nixpkgs.git?'
        in part
    )
    parsed = urlsplit(suggested_git_url)
    assert parsed.scheme == "git+https"
    assert parsed.netloc == "github.com"
    assert parsed.path == "/SuperSandro2000/nixpkgs.git"
    assert dict(parse_qsl(parsed.query)) == {
        "shallow": "1",
        "ref": "nixos-unstable",
    }

