def assert_clickhouse_median_sql(sql, argument_sql):
    # ClickHouse supports `median` as a lowercase alias for quantile(0.5).
    # Either spelling is a valid compilation, but the original broken output
    # (`MEDIAN(...)`) is not valid because ClickHouse function names are
    # case-sensitive.
    assert sql in {
        f"median({argument_sql})",
        f"quantile(0.5)({argument_sql})",
    }


@pytest.mark.parametrize(
    ("name", "argument", "argument_sql"),
    [
        ("median", sg.to_identifier("x"), "x"),
        ("MEDIAN", sg.to_identifier("x"), "x"),
        (
            "median",
            exp.Add(this=sg.to_identifier("left_value"), expression=sg.to_identifier("right_value")),
            "left_value + right_value",
        ),
        ("median", sg.func("length", sg.to_identifier("name")), "LENGTH(name)"),
    ],
)
def test_func_median_compiles_to_a_case_sensitive_clickhouse_median(
    name, argument, argument_sql
):
    expression = sg.func(name, argument)

    sql = expression.sql(dialect="clickhouse")

    assert_clickhouse_median_sql(sql, argument_sql)
    assert not sql.startswith("MEDIAN(")


