    query = (
        sg.select(sg.func("median", sg.to_identifier("x")).as_("middle"))
        .from_("measurements")
    )

    sql = query.sql(dialect="clickhouse")

    assert sql in {
        "SELECT median(x) AS middle FROM measurements",
        "SELECT quantile(0.5)(x) AS middle FROM measurements",
    }
    assert "MEDIAN(" not in sql

