concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
  typename T::value_type;
  requires sizeof(T) > 0;
  t.begin();
  t.end();
  t.size();
  t.empty();
  t.clear();
  t.data();
  t.front();
  t.back();
  t.capacity();
};

// This semicolon is actually redundant.
void OrdinaryFunction() {};
""",
        encoding="utf-8",
    )

    errors = []
    cpplint.ProcessFileData(
        str(source),
        "cc",
        source.read_text(encoding="utf-8").splitlines(),
        lambda filename, linenum, category, confidence, message: errors.append(
            (linenum, category, confidence, message)
        ),
    )

    brace_errors = [
        error
        for error in errors
        if error[1] == "readability/braces"
        and error[3] == "You don't need a ; after a }"
    ]

    # A requires-expression may contain any number of requirements.  Its
    # closing semicolon remains required even when the body is long; only the
    # ordinary function's semicolon should be diagnosed.
    assert len(brace_errors) == 1
    assert brace_errors[0][0] == 18
    assert brace_errors[0][2] == 4

