import cpplint
import pytest


REDUNDANT_SEMICOLON_MESSAGE = "You don't need a ; after a }"


def trailing_semicolon_errors(source: str):
    """Return readability/braces errors from the trailing-semicolon check."""
    clean_lines = cpplint.CleansedLines(source.splitlines())
    errors = []

    def record_error(filename, linenum, category, confidence, message):
        errors.append((filename, linenum, category, confidence, message))

    for linenum in range(len(clean_lines.lines)):
        cpplint.CheckTrailingSemicolon(
            "concept_requires.cc",
            clean_lines,
            linenum,
            record_error,
        )

    return [
        error
        for error in errors
        if error[2] == "readability/braces"
        and REDUNDANT_SEMICOLON_MESSAGE in error[4]
    ]


@pytest.mark.parametrize(
    "requires_expression",
    [
        # The form from the reported issue.
        """
template <typename T>
concept IndexableToChar = requires(T value) {
  { value[0] } -> std::convertible_to<char>;
};
""",
        # A valid requires-expression may split its parameter list and opening
        # brace over multiple lines.
        """
template <typename T>
concept WrappedRequires = requires(
    T value
) {
  { value[0] } -> std::convertible_to<char>;
};
""",
        # A concept body is not limited to an arbitrary number of lines.
        """
template <typename T>
concept ManyRequirements = requires(T value) {
  typename T::member01;
  typename T::member02;
  typename T::member03;
  typename T::member04;
  typename T::member05;
  typename T::member06;
  typename T::member07;
  typename T::member08;
  typename T::member09;
  typename T::member10;
  typename T::member11;
  typename T::member12;
};
""",
        # `requires (...) { ... }` is a C++20 requires-expression even when
        # used to initialize a bool rather than directly in a concept.
        """
template <typename T>
constexpr bool kIsIndexable = requires(T value) {
  { value[0] } -> std::convertible_to<char>;
};
""",
    ],
    ids=[
        "reported-concept",
        "wrapped-parameters",
        "long-body",
        "requires-expression-outside-concept",
    ],
)
def test_required_requires_expression_semicolon_is_not_reported(
    requires_expression: str,
) -> None:
    # Include an ordinary function with a truly redundant semicolon.  This
    # ensures the exemption is limited to requires-expression braces.
    errors = trailing_semicolon_errors(
        requires_expression
        + """
void OrdinaryFunction() {};
"""
    )

    assert len(errors) == 1
    assert errors[0][2] == "readability/braces"
    assert REDUNDANT_SEMICOLON_MESSAGE in errors[0][4]

