from oop_ext.interface import (
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
)


def test_is_implementation_requires_an_explicit_declaration_by_default():
    class IMarker(Interface):
        def identify(self, value):
            pass

    class StructurallyCompatibleButUndeclared:
        def identify(self, value):
            return value

    candidate = StructurallyCompatibleButUndeclared()

    # Merely having all interface methods must no longer make a class an
    # implementation when the argument is omitted.
    assert not IsImplementation(StructurallyCompatibleButUndeclared, IMarker)
    assert not IsImplementation(candidate, IMarker)

    # The old structural/duck-typing behavior remains available when requested.
    assert IsImplementation(
        StructurallyCompatibleButUndeclared,
        IMarker,
        requires_declaration=False,
    )
    assert IsImplementation(candidate, IMarker, requires_declaration=False)

    # Explicitly requesting the new default has the same result.
    assert not IsImplementation(
        StructurallyCompatibleButUndeclared,
        IMarker,
        requires_declaration=True,
    )


def test_declared_implementations_are_recognized_by_default():
    class IMarker(Interface):
        def identify(self, value):
            pass

    @ImplementsInterface(IMarker)
    class DeclaredImplementation:
        def identify(self, value):
            return value

    assert IsImplementation(DeclaredImplementation, IMarker)
    assert IsImplementation(DeclaredImplementation(), IMarker)


def test_external_and_inherited_interface_declarations_count_as_explicit():
    class IBaseMarker(Interface):
        def identify(self, value):
            pass

    class IMoreSpecificMarker(IBaseMarker):
        pass

    class ExternallyDeclaredImplementation:
        def identify(self, value):
            return value

    # Declaring outside the class is a supported explicit declaration mechanism.
    DeclareClassImplements(ExternallyDeclaredImplementation, IBaseMarker)
    assert IsImplementation(ExternallyDeclaredImplementation, IBaseMarker)

    @ImplementsInterface(IMoreSpecificMarker)
    class MoreSpecificImplementation:
        def identify(self, value):
            return value

    # Declaring a derived interface also explicitly declares its base interface.
    assert IsImplementation(MoreSpecificImplementation, IBaseMarker)
    assert IsImplementation(MoreSpecificImplementation(), IBaseMarker)

from wemake_python_styleguide.violations.complexity import (
    TooManyLocalsViolation,
)
from wemake_python_styleguide.visitors.ast.complexity.function import (
    FunctionComplexityVisitor,
)


def test_wps210_ignores_assignments_in_nested_functions_and_classes(
    default_options,
    parse_ast_tree,
):
    """Nested scopes must not make their enclosing function exceed WPS210."""
    code = """
def outer():
    enclosing_local = 0

    def helper():
        helper_one = 1
        helper_two = 2
        helper_three = 3

    class Inner:
        first_attribute = 1
        second_attribute = 2
        third_attribute = 3
        fourth_attribute = 4
        fifth_attribute = 5
        sixth_attribute = 6
"""
    tree = parse_ast_tree(code)
    visitor = FunctionComplexityVisitor(default_options, tree=tree)

    visitor.run()

    assert not any(
        isinstance(violation, TooManyLocalsViolation)
        for violation in visitor.violations
    )

