import cpplint


def _brace_errors(source):
    """Run cpplint's trailing-semicolon check and return brace diagnostics."""
    clean_lines = cpplint.CleansedLines(source.splitlines())
    errors = []

    def record_error(*args):
        errors.append(args)

    for linenum in range(len(clean_lines.elided)):
        cpplint.CheckTrailingSemicolon(
            "concept_example.cc", clean_lines, linenum, record_error
        )

    return [error for error in errors if error[2] == "readability/braces"]


def test_requires_expression_concept_terminator_is_not_reported():
    source = """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
"""

    assert _brace_errors(source) == []


def test_multiline_concept_declaration_terminator_is_not_reported():
    # Newlines are whitespace in a declaration, so this is the same kind of
    # C++20 concept definition and its terminating semicolon is required.
    source = """\
template <typename T>
concept
    IndexableToChar
    =
    requires(T t) {
      { t[0] } -> std::convertible_to<char>;
    };
"""

    assert _brace_errors(source) == []


def test_concept_does_not_suppress_redundant_semicolon_on_other_block():
    # The concept's semicolon is required, but the semicolon after this
    # unrelated control-flow block remains redundant and must still be linted.
    source = """\
template <typename T>
concept Indexable = requires(T value) {
  value[0];
};

if (true) {
};
"""

    errors = _brace_errors(source)

    assert len(errors) == 1
    assert "You don't need a ; after a }" in errors[0][4]

from oop_ext.interface import (
