)


def test_is_implementation_requires_explicit_declaration_by_default_for_classes_and_instances():
    class IService(Interface):
        def process(self, value):
            pass

    class StructurallyCompatibleButUndeclared:
        def process(self, value):
            return value

    candidate = StructurallyCompatibleButUndeclared()

    # Matching an interface structurally is not enough by default: interfaces are
    # also used as identities and therefore require an explicit declaration.
    assert not IsImplementation(StructurallyCompatibleButUndeclared, IService)
    assert not IsImplementation(candidate, IService)

    # Duck typing remains available only when explicitly requested.
