from dataclasses import dataclass, field
from typing import Any

from hydra_zen import builds, instantiate


_factory_calls = []
_nonserializable_factory_result = object()


def tracked_default_factory():
    _factory_calls.append(len(_factory_calls) + 1)
    return {"factory_call": len(_factory_calls)}


def nonserializable_default_factory():
    return _nonserializable_factory_result


@dataclass
class DataclassWithTrackedFactory:
    value: Any = field(default_factory=tracked_default_factory)


@dataclass
class DataclassWithOverridableFactory:
    value: Any = field(default_factory=lambda: "from-factory")


@dataclass
class DataclassWithNonserializableFactoryResult:
    value: Any = field(default_factory=nonserializable_default_factory)


def test_populate_full_signature_defers_dataclass_default_factory_to_instantiation():
    _factory_calls.clear()

    Conf = builds(DataclassWithTrackedFactory, populate_full_signature=True)

    # The factory is not a config value and must not be called while building
    # the config.
    assert _factory_calls == []

    first = instantiate(Conf)
    second = instantiate(Conf)

    # The target dataclass retains normal default-factory behavior: the factory
    # is evaluated separately each time the target is instantiated.
    assert first.value == {"factory_call": 1}
    assert second.value == {"factory_call": 2}
    assert first.value is not second.value


def test_populate_full_signature_allows_overriding_dataclass_factory_default():
    Conf = builds(
        DataclassWithOverridableFactory,
        value="explicit-configured-value",
        populate_full_signature=True,
    )

    assert instantiate(Conf).value == "explicit-configured-value"


def test_populate_full_signature_does_not_require_factory_result_to_be_serializable():
    # This object cannot be represented as a Hydra primitive. builds must not
    # eagerly evaluate and serialize a dataclass default factory; the target
    # dataclass evaluates it during instantiation instead.
    Conf = builds(
        DataclassWithNonserializableFactoryResult,
        populate_full_signature=True,
    )

    assert instantiate(Conf).value is _nonserializable_factory_result

