from pyopenapi3.schemas import ObjectsDTSchema


def _assert_free_form_object(schema):
    rendered = schema.dict()

    assert rendered["type"] == "object"

    # OpenAPI permits all of these equivalent free-form representations:
    #   type: object
    #   type: object, additionalProperties: true
    #   type: object, additionalProperties: {}
    assert rendered.get("additionalProperties", True) is True or (
        rendered.get("additionalProperties") == {}
    )


@pytest.mark.parametrize(
