import importlib.util
import sys
from pathlib import Path

import pytest


_CPPLINT_PATH = Path(__file__).with_name("cpplint.py")
_SPEC = importlib.util.spec_from_file_location("cpplint", _CPPLINT_PATH)
cpplint = importlib.util.module_from_spec(_SPEC)
sys.modules["cpplint"] = cpplint
_SPEC.loader.exec_module(cpplint)

TRAILING_SEMICOLON_MESSAGE = "You don't need a ; after a }"


def trailing_semicolon_errors(source):
    """Collect cpplint's readability/braces trailing-semicolon diagnostics."""
    clean_lines = cpplint.CleansedLines(source.splitlines())
    errors = []

    def record_error(filename, linenum, category, confidence, message):
        if (
            category == "readability/braces"
            and TRAILING_SEMICOLON_MESSAGE in message
        ):
            errors.append((linenum, message))

    for linenum in range(clean_lines.NumLines()):
        cpplint.CheckTrailingSemicolon(
            "concept_test.cc", clean_lines, linenum, record_error
        )

    return errors


@pytest.mark.parametrize(
    "source",
    [
        # The formatting in the reported issue.
        """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
""",
        # Whitespace, including a newline, may occur before the = token.
        """\
template <typename T>
concept IndexableToChar
    = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
""",
        # Whitespace may also occur between the concept keyword and its name.
        """\
template <typename T>
concept
    IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
""",
    ],
    ids=["reported-layout", "equals-on-next-line", "name-on-next-line"],
)
def test_requires_expression_concept_terminating_semicolon_is_not_redundant(
    source,
):
    assert trailing_semicolon_errors(source) == []


def test_concept_does_not_hide_unrelated_redundant_semicolon_nearby():
    # The required semicolon of a concept must not suppress a real warning for
    # another brace pair merely because it is close to the concept definition.
    errors = trailing_semicolon_errors(
        """\
template <typename T>
concept AnyValue = requires(T value) {
  value;
};

void RedundantFunctionTerminator() {
};
"""
    )

    assert len(errors) == 1

