import serde


def test_coerce_fixed_tuple_field_can_be_serialized_and_deserialized() -> None:
    """Tuple element paths containing dict-key quotes must generate valid code."""

    @serde.serde(type_check=serde.coerce)
    class Location:
        loc: tuple[float, float]

    # This is the original reported case.  Class decoration eagerly generates
    # both dict serializer and deserializer functions, so either unsafe code
    # path would raise SyntaxError before reaching these assertions.
    serialized = serde.to_dict(Location(loc=(1, 2)))
    assert serialized == {"loc": (1.0, 2.0)}

    restored = serde.from_dict(Location, {"loc": ("3.5", 4)})
    assert restored.loc == (3.5, 4.0)
    assert all(isinstance(value, float) for value in restored.loc)


def test_coerce_nested_tuple_with_renamed_dict_key_round_trips() -> None:
    """Escaping must also work for nested tuple paths and renamed dict keys."""

    @serde.serde(rename_all="camelcase", type_check=serde.coerce)
    class Coordinates:
        coordinate_pair: tuple[tuple[float, float], tuple[float, float]]

    value = Coordinates(coordinate_pair=((1, "2"), ("3.5", 4)))
    serialized = serde.to_dict(value)

    assert serialized == {
        "coordinatePair": ((1.0, 2.0), (3.5, 4.0)),
    }

    restored = serde.from_dict(
        Coordinates,
        {"coordinatePair": (("5", 6), (7, "8.5"))},
    )
    assert restored.coordinate_pair == ((5.0, 6.0), (7.0, 8.5))

from oop_ext.interface import (
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
)


def test_is_implementation_default_requires_the_requested_interface_declaration():
    class IPrimaryOperation(Interface):
        def operate(self, value):
            pass

    # This is deliberately structurally identical to IPrimaryOperation. Interfaces
    # may be used as IDs, so declaring one must not make an implementation match
    # the other merely because their methods happen to be the same.
    class IUnrelatedOperation(Interface):
        def operate(self, value):
            pass

    @ImplementsInterface(IPrimaryOperation)
    class PrimaryOperation:
        def operate(self, value):
            return value

    implementation = PrimaryOperation()

    assert IsImplementation(PrimaryOperation, IPrimaryOperation)
    assert IsImplementation(implementation, IPrimaryOperation)

    assert not IsImplementation(PrimaryOperation, IUnrelatedOperation)
    assert not IsImplementation(implementation, IUnrelatedOperation)

    # Structural/duck-typing checks remain available when callers explicitly opt in.
    assert IsImplementation(
        PrimaryOperation, IUnrelatedOperation, requires_declaration=False
    )
    assert IsImplementation(
        implementation, IUnrelatedOperation, requires_declaration=False
    )


def test_is_implementation_default_accepts_external_interface_declaration():
    class IOperation(Interface):
        def operate(self, value):
            pass

    class ExternalOperation:
        def operate(self, value):
            return value

    # Declaration outside of the class is an equally valid explicit declaration.
    DeclareClassImplements(ExternalOperation, IOperation)

    assert IsImplementation(ExternalOperation, IOperation)
    assert IsImplementation(ExternalOperation(), IOperation)

