import serde


def test_coerce_fixed_tuple_round_trips_through_dict() -> None:
    """Fixed-length tuple coercion must generate valid serializer/deserializer code."""

    @serde.serde(type_check=serde.coerce)
    class Coordinates:
        loc: tuple[float, float]

    # This is the original reported use case.  Class decoration itself used to
    # raise SyntaxError while generating code for the tuple elements.
    value = Coordinates(loc=(1, 2))
    assert value.loc == (1.0, 2.0)
    assert serde.to_dict(value) == {"loc": (1.0, 2.0)}

    # Deserialization renders the problematic data["loc"][index] expression,
    # so also verify that it is executable and applies coercion.
    restored = serde.from_dict(Coordinates, {"loc": ("3.5", "4.5")})
    assert restored == Coordinates(loc=(3.5, 4.5))


def test_coerce_nested_fixed_tuples_round_trip() -> None:
    """Escaping must remain valid when tuple element paths are nested."""

    @serde.serde(type_check=serde.coerce)
    class Matrix:
        values: tuple[tuple[float, float], tuple[float, float]]

    value = Matrix(values=((1, 2), (3, 4)))
    assert value.values == ((1.0, 2.0), (3.0, 4.0))
    assert serde.to_dict(value) == {"values": ((1.0, 2.0), (3.0, 4.0))}

    restored = serde.from_dict(
        Matrix,
        {"values": (("1.25", "2.5"), ("3.75", "4.0"))},
    )
    assert restored.values == ((1.25, 2.5), (3.75, 4.0))

import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


class IHasName(Interface):
    def GetName(self):
        pass


class IHasIdentifier(Interface):
    def GetIdentifier(self):
        pass


class StructurallyNamed:
    def GetName(self):
        return "name"


def test_structural_match_is_not_an_implementation_by_default():
    # Having the same methods is not enough: implementations are interface IDs
    # and must be explicitly declared.
    assert not IsImplementation(StructurallyNamed, IHasName)
    assert not IsImplementation(StructurallyNamed(), IHasName)

    # Duck-typing checks remain available when explicitly requested.
    assert IsImplementation(
        StructurallyNamed, IHasName, requires_declaration=False
    )
    assert IsImplementation(
        StructurallyNamed(), IHasName, requires_declaration=False
    )


def test_related_public_interface_checks_default_to_declared_implementations():
    assert not IsImplementationOfAny(StructurallyNamed, (IHasName,))
    assert IsImplementationOfAny(
        StructurallyNamed, (IHasName,), requires_declaration=False
    )

    with pytest.raises(AssertionError):
        AssertImplements(StructurallyNamed, IHasName)

    # Full structural validation can still be explicitly requested.
    AssertImplements(StructurallyNamed, IHasName, requires_declaration=False)


def test_declaration_distinguishes_interfaces_and_invalidates_prior_check_cache():
    class ImplementsBothShapes:
        def GetName(self):
            return "name"

        def GetIdentifier(self):
            return "identifier"

    # Populate both cache variants before declaring the interface.
    assert not IsImplementation(ImplementsBothShapes, IHasName)
    assert IsImplementation(
        ImplementsBothShapes, IHasName, requires_declaration=False
    )

    DeclareClassImplements(ImplementsBothShapes, IHasName)

    # A later declaration must make a previously cached default failure succeed.
    assert IsImplementation(ImplementsBothShapes, IHasName)
    assert IsImplementation(ImplementsBothShapes(), IHasName)

    # Implementing the methods for another interface does not make it an ID
    # implemented by this class unless that interface was declared too.
    assert not IsImplementation(ImplementsBothShapes, IHasIdentifier)
    assert IsImplementation(
        ImplementsBothShapes, IHasIdentifier, requires_declaration=False
    )

import asyncio
from urllib.parse import unquote_plus

import httpx


def _query_fields(url: httpx.URL) -> list[str]:
    return url.query.decode("ascii").split("&")


def test_async_client_preserves_bare_query_parameter_when_merging_params():
    async def app(request: httpx.Request) -> httpx.Response:
        return httpx.Response(200, request=request)

    async def make_request() -> httpx.Response:
        async with httpx.AsyncClient(transport=httpx.MockTransport(app)) as client:
            return await client.get(
                "https://example.org/get?foobar",
                params={"hello": "world"},
            )

    response = asyncio.run(make_request())

    assert set(_query_fields(response.url)) == {"hello=world", "foobar"}


def test_encoded_bare_parameter_names_remain_bare_when_merging_params():
    request = httpx.Request(
        "GET",
        "https://example.org/?space%20name&equals%3Dsign",
        params={"added": "value"},
    )

    fields = _query_fields(request.url)

    # These query components have encoded characters in their names, but no
    # explicit value delimiter. They must not be serialized with a trailing "=".
    bare_fields = [field for field in fields if "=" not in field]
    assert {unquote_plus(field) for field in bare_fields} == {
        "space name",
        "equals=sign",
    }
    assert "added=value" in fields


def test_bare_and_explicitly_empty_occurrences_of_same_key_are_distinct():
    request = httpx.Request(
        "GET",
        "https://example.org/?flag=&flag",
        params={"added": "value"},
    )

    fields = _query_fields(request.url)

    # A key written as "flag=" explicitly has an empty value, while "flag"
    # has no value. Preserving bare fields must not rewrite both occurrences.
    assert fields.count("flag=") == 1
    assert fields.count("flag") == 1
    assert "added=value" in fields


def test_copy_set_param_keeps_unrelated_bare_query_parameters():
    url = httpx.URL("https://example.org/?bare").copy_set_param("other", "value")

    assert set(_query_fields(url)) == {"bare", "other=value"}

