import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


def test_interface_checks_require_an_explicit_declaration_by_default():
    class IService(Interface):
        def process(self, value):
            pass

    class StructurallyCompatible:
        def process(self, value):
            return value

    candidate = StructurallyCompatible()

    # Having compatible methods alone must not make a class an implementation.
    assert not IsImplementation(StructurallyCompatible, IService)
    assert not IsImplementation(candidate, IService)

    # Duck-typing remains available when explicitly requested.
    assert IsImplementation(
        StructurallyCompatible, IService, requires_declaration=False
    )
    assert IsImplementation(candidate, IService, requires_declaration=False)

    with pytest.raises(AssertionError, match="does not declare"):
        AssertImplements(candidate, IService)

    # AssertImplements must retain the opt-in duck-typing behavior too.
    AssertImplements(candidate, IService, requires_declaration=False)


def test_declaration_after_a_failed_default_check_invalidates_cached_result():
    class IWorker(Interface):
        def work(self):
            pass

    class UndeclaredWorker:
        def work(self):
            return "done"

    # This populates the cache with the default (declaration-required) result.
    assert not IsImplementation(UndeclaredWorker, IWorker)
    assert not IsImplementationOfAny(UndeclaredWorker(), [IWorker])

    # Declaring an already checked class must make subsequent default checks succeed.
    DeclareClassImplements(UndeclaredWorker, IWorker)

    assert IsImplementation(UndeclaredWorker, IWorker)
    assert IsImplementation(UndeclaredWorker(), IWorker)
    assert IsImplementationOfAny(UndeclaredWorker(), [IWorker])
    AssertImplements(UndeclaredWorker(), IWorker)


def test_declaration_is_inherited_and_is_accepted_by_default_checks():
    class IBase(Interface):
        def base_method(self):
            pass

    class IDerived(IBase):
        def derived_method(self):
            pass

    class Implementer:
        def base_method(self):
            return "base"

        def derived_method(self):
            return "derived"

    DeclareClassImplements(Implementer, IDerived)

    class ChildImplementer(Implementer):
        pass

    # Declaring a derived interface declares its base interfaces as well, and
    # subclasses inherit the declaration.
    assert IsImplementation(Implementer, IDerived)
    assert IsImplementation(Implementer(), IBase)
    assert IsImplementation(ChildImplementer, IDerived)
    assert IsImplementationOfAny(ChildImplementer(), [IBase, IDerived])

import serde


def test_coerce_fixed_tuple_can_be_declared_serialized_and_deserialized() -> None:
    """Tuple element accessors must be safely embedded in generated coercion code."""

    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    # This is the original reported case: class decoration must not raise SyntaxError,
    # and tuple members should be coerced in generated serialization code.
    assert serde.to_dict(Foo(loc=(1, 2))) == {"loc": (1.0, 2.0)}

    # Generated deserialization code has the same quoted accessor path and must
    # coerce values received from a data-format-like payload.
    restored = serde.from_dict(Foo, {"loc": ["3.5", "4"]})
    assert restored.loc == (3.5, 4.0)
    assert all(isinstance(value, float) for value in restored.loc)


def test_coerce_nested_tuple_with_renamed_field_round_trips() -> None:
    """Nested tuple accessor paths contain multiple quoted dictionary lookups."""

    @serde.serde(type_check=serde.coerce)
    class Coordinates:
        point: tuple[tuple[float, float], tuple[float, float]] = serde.field(
            rename="wire_point"
        )

    value = Coordinates(point=((1, 2), (3, 4)))
    assert serde.to_dict(value) == {
        "wire_point": ((1.0, 2.0), (3.0, 4.0)),
    }

    restored = serde.from_dict(
        Coordinates,
        {"wire_point": [["1.25", 2], [3, "4.75"]]},
    )
    assert restored == Coordinates(point=((1.25, 2.0), (3.0, 4.75)))

import io
import unittest

import cpplint


def test_existing_cpplint_regression_suite_still_passes():
    # Run the repository's established suite through the same in-process
    # coverage session used by this test file.
    import cpplint_unittest

    suite = unittest.defaultTestLoader.loadTestsFromModule(cpplint_unittest)
    result = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)
    assert result.wasSuccessful()


def _braces_errors(source):
    """Run cpplint's file-processing API and return brace diagnostics."""
    errors = []

    def collect_error(filename, linenum, category, confidence, message):
        del filename, confidence
        if category == "readability/braces":
            errors.append((linenum, message))

    cpplint.ProcessFileData(
        "concept_test.cc",
        "cc",
        source.splitlines(True),
        collect_error,
    )
    return errors


def test_requires_expression_concept_closing_semicolon_is_not_reported():
    errors = _braces_errors(
        """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
"""
    )

    assert errors == []


def test_concept_definition_can_be_split_across_lines():
    # Newlines are permitted between declaration tokens; the semicolon after
    # this requires-expression body is still required by the language.
    errors = _braces_errors(
        """\
template <typename T>
concept
    IndexableToChar
    = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
"""
    )

    assert errors == []


def test_nearby_concept_does_not_hide_redundant_function_semicolon():
    # A concept declaration must not suppress the check for a distinct brace
    # pair merely because the declaration appears nearby.
    errors = _braces_errors(
        """\
template <typename T>
concept HasIndex = requires(T value) {
  value[0];
};

void OrdinaryFunction() {};
"""
    )

    assert len(errors) == 1
    assert errors[0][1] == "You don't need a ; after a }"

