import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


def test_isimplementation_requires_explicit_declaration_by_default_for_class_and_instance():
    class IService(Interface):
        def process(self, value):
            pass

    class StructurallyCompatible:
        def process(self, value):
            pass

    instance = StructurallyCompatible()

    # Matching the interface shape alone must not make this class an implementation.
    assert not IsImplementation(StructurallyCompatible, IService)
    assert not IsImplementation(instance, IService)

    # Duck typing remains available as an explicit opt-in.
    assert IsImplementation(StructurallyCompatible, IService, requires_declaration=False)
    assert IsImplementation(instance, IService, requires_declaration=False)


def test_explicitly_declared_implementation_is_recognized_by_default():
    class IService(Interface):
        def process(self, value):
            pass

    @ImplementsInterface(IService)
    class DeclaredImplementation:
        def process(self, value):
            pass

    assert IsImplementation(DeclaredImplementation, IService)
    assert IsImplementation(DeclaredImplementation(), IService)


def test_declare_class_implements_invalidates_a_previous_declaration_required_check():
    class IService(Interface):
        def process(self, value):
            pass

    class LaterDeclared:
        def process(self, value):
            pass

    # This check populates the declaration-required result before the declaration exists.
    assert not IsImplementation(LaterDeclared, IService)

    DeclareClassImplements(LaterDeclared, IService)

    # Declaring externally is a supported explicit declaration mechanism and must be
    # visible even when the previous negative result was cached.
    assert IsImplementation(LaterDeclared, IService)
    assert IsImplementation(LaterDeclared(), IService)
    AssertImplements(LaterDeclared, IService)


def test_related_public_checks_require_declaration_by_default():
    class IService(Interface):
        def process(self, value):
            pass

    class IOther(Interface):
        def other(self):
            pass

    class StructurallyCompatible:
        def process(self, value):
            pass

    candidate = StructurallyCompatible()

    with pytest.raises(AssertionError):
        AssertImplements(candidate, IService)

    # Full structural validation can still be requested explicitly.
    AssertImplements(candidate, IService, requires_declaration=False)

    assert not IsImplementationOfAny(candidate, [IOther, IService])
    assert IsImplementationOfAny(
        candidate, [IOther, IService], requires_declaration=False
    )

import urllib.parse

import httpx


def _query_parts(url: httpx.URL) -> list[str]:
    return url.query.decode("ascii").split("&")


def test_request_params_preserve_a_bare_query_parameter():
    request = httpx.Request(
        "GET",
        "https://example.org/get?foobar",
        params={"hello": "world"},
    )

    assert set(_query_parts(request.url)) == {"foobar", "hello=world"}


def test_encoded_bare_parameter_is_preserved_after_merging_params():
    request = httpx.Request(
        "GET",
        "https://example.org/get?feature%20flag",
        params={"hello": "world"},
    )

    parts = _query_parts(request.url)
    bare_keys = [
        urllib.parse.unquote_plus(part)
        for part in parts
        if "=" not in part
    ]

    assert bare_keys == ["feature flag"]
    assert "hello=world" in parts


def test_bare_and_explicitly_empty_parameters_remain_distinct():
    request = httpx.Request(
        "GET",
        "https://example.org/get?state=&state",
        params={"hello": "world"},
    )

    state_parts = [
        part
        for part in _query_parts(request.url)
        if urllib.parse.unquote_plus(part.split("=", 1)[0]) == "state"
    ]

    assert state_parts == ["state=", "state"]


def test_replacing_bare_parameter_with_explicit_empty_value_keeps_equals_sign():
    request = httpx.Request(
        "GET",
        "https://example.org/get?flag",
        params={"flag": ""},
    )

    assert _query_parts(request.url) == ["flag="]


def test_url_copy_add_param_preserves_existing_bare_parameter():
    url = httpx.URL("https://example.org/get?flag").copy_add_param("hello", "world")

    assert _query_parts(url) == ["flag", "hello=world"]

