import ast

import pytest

from pyupgrade import _fix_py3_plus


def _metaclass_type_assignments(source):
    tree = ast.parse(source)
    return [
        node
        for node in ast.walk(tree)
        if (
            isinstance(node, ast.Assign) and
            len(node.targets) == 1 and
            isinstance(node.targets[0], ast.Name) and
            node.targets[0].id == '__metaclass__' and
            isinstance(node.value, ast.Name) and
            node.value.id == 'type'
        )
    ]


def test_py3_plus_removes_module_metaclass_type_assignment():
    src = (
        '"""module docs"""\n'
        '__metaclass__ = type\n'
        '\n'
        'VALUE = 1\n'
    )

    assert _fix_py3_plus(src) == (
        '"""module docs"""\n'
        '\n'
        'VALUE = 1\n'
    )


@pytest.mark.parametrize(
    'src',
    (
        'class C:\n'
        '    __metaclass__ = type\n',
        'def f():\n'
        '    __metaclass__ = type\n',
        'async def f():\n'
        '    __metaclass__ = type\n',
        'def f():\n'
        '    class C:\n'
        '        __metaclass__ = type\n',
    ),
)
def test_py3_plus_does_not_remove_non_module_metaclass_assignments(src):
    assert _fix_py3_plus(src) == src


@pytest.mark.parametrize(
    'src',
    (
        '__metaclass__ = other_type\n',
        'other_name = type\n',
        '__metaclass__ = type,\n',
        '__metaclass__, other_name = type, object\n',
    ),
)
def test_py3_plus_only_removes_the_old_metaclass_type_idiom(src):
    assert _fix_py3_plus(src) == src


@pytest.mark.parametrize(
    'src',
    (
        'before = 1; __metaclass__ = type\n',
        '__metaclass__ = type; after = 2\n',
        'before = 1; __metaclass__ = type; after = 2\n',
    ),
)
def test_py3_plus_removes_only_the_assignment_when_sharing_a_line(src):
    fixed = _fix_py3_plus(src)

    # The old Python-2-only assignment is gone, but unrelated statements on
    # the same physical line must not be deleted along with it.
    assert not _metaclass_type_assignments(fixed)

    namespace = {}
    exec(fixed, namespace)
    if 'before' in src:
        assert namespace['before'] == 1
    if 'after' in src:
        assert namespace['after'] == 2

