import serde


def test_coerce_fixed_tuple_fields_generate_and_serialize() -> None:
    # The tuple members are rendered with paths such as data["loc"][0].
    # Decorating this class must not generate invalid Python source.
    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    result = serde.to_dict(Foo(loc=(1, 2)))

    assert result == {"loc": (1.0, 2.0)}
    assert all(isinstance(value, float) for value in result["loc"])


def test_coerce_deserializes_nested_and_renamed_fixed_tuples() -> None:
    # Nested tuple members exercise generated paths including
    # data["position"][0][0], while the rename ensures the path is based on
    # the serialized field name rather than just the attribute name.
    @serde.serde(type_check=serde.coerce)
    class Coordinates:
        loc: tuple[tuple[float, float], tuple[float, float]] = serde.field(rename="position")

    value = serde.from_dict(
        Coordinates,
        {
            "position": (
                ("1.25", 2),
                (3, "4.75"),
            )
        },
    )

    assert value.loc == ((1.25, 2.0), (3.0, 4.75))
    assert all(
        isinstance(component, float)
        for point in value.loc
        for component in point
    )
    assert serde.to_dict(value) == {
        "position": ((1.25, 2.0), (3.0, 4.75)),
    }

