    sampler = _embedding_sampler(
        nodelist=[10, 11],
        edgelist=[(10, 11)],
        embedding={0: [10], 1: [11]},
    )
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): quadratic_bias,
    })

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert CHAIN_STRENGTH_WARNING not in _warning_messages(sampleset)


def test_chain_strength_warning_remains_for_an_embedding_with_a_chain():
    """The diagnostic still applies when there is an actual multi-qubit chain."""
    sampler = _embedding_sampler(
        nodelist=[10, 11, 12],
        edgelist=[(10, 11), (11, 12)],
        embedding={0: [10, 11], 1: [12]},
    )
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): -2,
    })

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert CHAIN_STRENGTH_WARNING in _warning_messages(sampleset)

