import pytest
from pydantic import ValidationError

from pyopenapi3.schemas import ObjectsDTSchema


def test_object_schema_without_properties_is_valid_free_form_object():
    """OpenAPI permits `type: object` without a properties mapping."""
    schema = ObjectsDTSchema()

    assert schema.dict() == {"type": "object"}
    assert schema.json() == '{"type": "object"}'


def test_free_form_object_keeps_object_metadata_and_omits_properties():
    """A free-form object may carry schema metadata without declaring fields."""
    schema = ObjectsDTSchema(
        description="Custom tags",
        additionalProperties=True,
    )

    assert schema.dict() == {
        "type": "object",
        "description": "Custom tags",
        "additionalProperties": True,
    }
    assert "properties" not in schema.dict()


def test_object_schema_still_supports_explicit_properties():
    """Making properties optional must not change regular object schemas."""
    schema = ObjectsDTSchema(
        properties={
            "name": {
                "type": "string",
                "description": "A name",
            }
        }
    )

    assert schema.dict() == {
        "type": "object",
        "properties": {
            "name": {
                "type": "string",
                "description": "A name",
            }
        },
    }


def test_object_type_remains_fixed_when_properties_are_omitted():
    """The free-form relaxation must not allow non-object type values."""
    with pytest.raises(ValidationError):
        ObjectsDTSchema(type="string")

