import serde


def test_coerce_fixed_tuple_fields_generate_and_serialize() -> None:
    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    # Decorating the class must not fail while compiling generated deserialization code.
    # Coercion also applies to each fixed-tuple member during serialization.
    assert serde.to_dict(Foo(loc=(1, 2))) == {"loc": (1.0, 2.0)}


def test_coerce_nested_fixed_tuples_deserialize_each_member() -> None:
    @serde.serde(type_check=serde.coerce)
    class Coordinates:
        origin: tuple[float, float]
        bounds: tuple[tuple[int, float], tuple[float, int]]

    value = serde.from_dict(
        Coordinates,
        {
            "origin": ["1.25", 2],
            "bounds": (("3", "4.5"), ["6.75", "8"]),
        },
    )

    assert value == Coordinates(
        origin=(1.25, 2.0),
        bounds=((3, 4.5), (6.75, 8)),
    )
    assert serde.to_dict(value) == {
        "origin": (1.25, 2.0),
        "bounds": ((3, 4.5), (6.75, 8)),
    }

import json

import yaml
from yaml.nodes import MappingNode, ScalarNode, SequenceNode

from cfn_flip import to_json, to_yaml


def _mapping_value(node, key):
    assert isinstance(node, MappingNode)
    for key_node, value_node in node.value:
        if key_node.value == key:
            return value_node
    raise AssertionError("Could not find key {!r} in YAML mapping".format(key))


def _scalar_nodes_with_values(node, values):
    found = {}

    def visit(current):
        if isinstance(current, ScalarNode):
            if current.value in values:
                found.setdefault(current.value, []).append(current)
        elif isinstance(current, MappingNode):
            for key_node, value_node in current.value:
                visit(key_node)
                visit(value_node)
        elif isinstance(current, SequenceNode):
            for child in current.value:
                visit(child)

    visit(node)
    return found


def _assert_quoted_string_scalar(node, expected_value):
    assert isinstance(node, ScalarNode)
    assert node.value == expected_value
    assert node.tag == "tag:yaml.org,2002:str"
    assert node.style in ("'", '"'), (
        "{} must be emitted as a quoted YAML scalar so YAML consumers do not "
        "interpret the digit-only identifier as a number".format(expected_value)
    )


def test_elb_identifiers_are_quoted_and_round_trip_as_strings():
    """The IDs from the report must remain strings, including leading-zero IDs."""
    source = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021", "Name": "ue1"},
                "us-east-2": {"ELBID": "033677994240", "Name": "ue2"},
                "us-west-1": {"ELBID": "027434742980", "Name": "uw1"},
                "us-west-2": {"ELBID": "797873946194", "Name": "uw2"},
            }
        }
    }

    rendered = to_yaml(json.dumps(source))
    document = yaml.compose(rendered)

    regions = _mapping_value(_mapping_value(document, "Mappings"), "Regions")
    for region, expected_id in (
        ("us-east-1", "127311923021"),
        ("us-east-2", "033677994240"),
        ("us-west-1", "027434742980"),
        ("us-west-2", "797873946194"),
    ):
        elbid = _mapping_value(_mapping_value(regions, region), "ELBID")
        _assert_quoted_string_scalar(elbid, expected_id)

    # Check both a normal YAML consumer and cfn-flip's reverse conversion.
    assert yaml.safe_load(rendered) == source
    assert json.loads(to_json(rendered)) == source


def test_digit_only_string_ids_are_quoted_in_nested_mappings_and_lists():
    """
    IDs may occur outside Mappings as well.  In particular, values with a
    leading zero followed by 8 or 9 must not be left as plain YAML scalars:
    different YAML schemas disagree about whether those are numbers.
    """
    identifiers = [
        "0",
        "0123",
        "000000000008",
        "033677994240",
        "027434742980",
        "123456789012",
    ]
    source = {
        "Parameters": {
            "NestedIdentifier": "000000000008",
            "RegularIdentifier": "123456789012",
        },
        "IdentifierList": identifiers,
    }

    rendered = to_yaml(json.dumps(source))
    document = yaml.compose(rendered)
    scalar_nodes = _scalar_nodes_with_values(document, set(identifiers))

    for identifier in identifiers:
        assert identifier in scalar_nodes, "missing identifier {!r}".format(identifier)
        for node in scalar_nodes[identifier]:
            _assert_quoted_string_scalar(node, identifier)

    # Values such as "0123" are especially important to round-trip through a
    # YAML parser as strings rather than becoming octal/decimal integers.
    assert yaml.safe_load(rendered) == source
    assert json.loads(to_json(rendered)) == source

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import WarningAction


class StructuredExactSolver(dimod.ExactSolver, dimod.Structured):
    """Local structured sampler usable by EmbeddingComposite."""

    def __init__(self, nodelist, edgelist):
        self.parameters = {}
        self.properties = {}

        self._nodelist = list(nodelist)
        self._edgelist = list(edgelist)
        self._adjacency = {v: set() for v in self._nodelist}

        for u, v in self._edgelist:
            self._adjacency[u].add(v)
            self._adjacency[v].add(u)

    @property
    def nodelist(self):
        return self._nodelist

    @property
    def edgelist(self):
        return self._edgelist

    @property
    def adjacency(self):
        return self._adjacency


def warning_messages(sampleset):
    messages = []
    for warning in sampleset.info.get("warnings", []):
        if isinstance(warning, dict):
            messages.append(warning.get("message", ""))
        else:
            messages.append(str(warning))
    return [message.lower() for message in messages]


@pytest.mark.parametrize(
    "quadratic_bias",
    [
        -2,    # The two-variable QUBO/Ising-scale case described in the issue
        -100,  # Bias magnitude must not change behavior when there are no chains
        100,
    ],
)
def test_no_chain_strength_warning_when_embedding_has_only_singletons(
    quadratic_bias,
):
    """Quadratic bias strength is irrelevant if embedding creates no chains."""
    child = StructuredExactSolver([0, 1], [(0, 1)])
    sampler = EmbeddingComposite(
        child,
        find_embedding=lambda source, target: {"a": [0], "b": [1]},
    )

    bqm = dimod.BinaryQuadraticModel.from_ising(
        {},
        {("a", "b"): quadratic_bias},
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert not any(
        "quadratic biases are stronger than the given chain strength" in message
        for message in warning_messages(sampleset)
    )


def test_chain_strength_warning_remains_for_an_actual_chain():
    """The warning remains required when a logical variable has a chain."""
    child = StructuredExactSolver(
        [0, 1, 2],
        [(0, 1), (0, 2), (1, 2)],
    )
    sampler = EmbeddingComposite(
        child,
        find_embedding=lambda source, target: {"a": [0, 1], "b": [2]},
    )

    bqm = dimod.BinaryQuadraticModel.from_ising(
        {},
        {("a", "b"): -100},
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert any(
        "quadratic biases are stronger than the given chain strength" in message
        for message in warning_messages(sampleset)
    )

