import pytest

from sqlglot import exp, parse_one


@pytest.mark.parametrize("element_type", ("DATE", "DATETIME", "TIMESTAMP"))
def test_bigquery_range_type_round_trips_in_table_schema(element_type):
    expression = parse_one(
        f"CREATE TABLE ranges (value RANGE<{element_type}>)",
        read="bigquery",
    )

    data_type = expression.find(exp.DataType)

    assert data_type is not None
    assert data_type.this is exp.DataType.Type.RANGE
    assert len(data_type.expressions) == 1
    assert data_type.expressions[0].sql(dialect="bigquery") == element_type
    assert expression.sql(dialect="bigquery") == (
        f"CREATE TABLE ranges (value RANGE<{element_type}>)"
    )


@pytest.mark.parametrize("element_type", ("DATE", "DATETIME", "TIMESTAMP"))
def test_bigquery_range_type_round_trips_in_casts(element_type):
    expression = parse_one(
        f"SELECT CAST(NULL AS RANGE<{element_type}>) AS value",
        read="bigquery",
    )

    data_type = expression.find(exp.DataType)

    assert data_type is not None
    assert data_type.this is exp.DataType.Type.RANGE
    assert data_type.expressions[0].sql(dialect="bigquery") == element_type
    assert expression.sql(dialect="bigquery") == (
        f"SELECT CAST(NULL AS RANGE<{element_type}>) AS value"
    )


def test_bigquery_range_type_can_be_nested_in_struct_schema():
    expression = parse_one(
        "CREATE TABLE ranges (metadata STRUCT<period RANGE<TIMESTAMP>>)",
        read="bigquery",
    )

    range_type = next(
        data_type
        for data_type in expression.find_all(exp.DataType)
        if data_type.this is exp.DataType.Type.RANGE
    )

    assert range_type.expressions[0].sql(dialect="bigquery") == "TIMESTAMP"
    assert expression.sql(dialect="bigquery") == (
        "CREATE TABLE ranges (metadata STRUCT<period RANGE<TIMESTAMP>>)"
    )

import serde as serde_module


def test_coerce_supports_named_fixed_tuples_for_dict_conversion() -> None:
    @serde_module.serde(type_check=serde_module.coerce)
    class Coordinates:
        loc: tuple[float, float]

    value = Coordinates(loc=(1, 2))

    # Decorating the class must not generate syntactically invalid code for
    # data["loc"][N], and coercion must still be applied to each tuple member.
    assert serde_module.to_dict(value) == {"loc": (1.0, 2.0)}

    restored = serde_module.from_dict(Coordinates, {"loc": ("3.5", "4")})
    assert restored == Coordinates(loc=(3.5, 4.0))


def test_coerce_supports_multiple_and_nested_named_tuple_elements() -> None:
    @serde_module.serde(type_check=serde_module.coerce)
    class TupleContainer:
        point: tuple[float, int]
        bounds: tuple[tuple[float, float], tuple[int, int]]

    restored = serde_module.from_dict(
        TupleContainer,
        {
            "point": ("1.25", "2"),
            "bounds": (("3", "4.5"), ("5", "6")),
        },
    )

    assert restored == TupleContainer(
        point=(1.25, 2),
        bounds=((3.0, 4.5), (5, 6)),
    )
    assert serde_module.to_dict(restored) == {
        "point": (1.25, 2),
        "bounds": ((3.0, 4.5), (5, 6)),
    }

import textwrap
import unittest

import cpplint
import cpplint_unittest
import pytest


TRAILING_SEMICOLON_MESSAGE = "You don't need a ; after a }"


@pytest.fixture(scope="session", autouse=True)
def run_existing_cpplint_regression_suite():
    """Keep the repository's normal cpplint coverage/regression checks active."""
    suite = unittest.defaultTestLoader.loadTestsFromModule(cpplint_unittest)
    result = unittest.TextTestRunner(verbosity=0).run(suite)
    assert result.wasSuccessful()


def lint_brace_errors(source):
    errors = []

    def record_error(filename, linenum, category, confidence, message):
        if category == "readability/braces":
            errors.append((linenum, message))

    cpplint.ProcessFileData(
        "concepts.cc",
        "cc",
        textwrap.dedent(source).splitlines(),
        record_error,
    )
    return errors


def trailing_semicolon_errors(source):
    return [
        error
        for error in lint_brace_errors(source)
        if error[1] == TRAILING_SEMICOLON_MESSAGE
    ]


def test_requires_expression_concept_requires_trailing_semicolon():
    errors = trailing_semicolon_errors(
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """
    )

    assert errors == []


def test_concept_definition_with_name_and_equals_on_later_lines_is_not_flagged():
    # Whitespace, including newlines, is permitted between `concept`, its name,
    # and the equals sign in a concept-definition.
    errors = trailing_semicolon_errors(
        """
        template <typename T>
        concept
            IndexableToChar
            =
            requires(T t) {
              { t[0] } -> std::convertible_to<char>;
            };
        """
    )

    assert errors == []


def test_concept_does_not_suppress_a_later_redundant_brace_semicolon():
    errors = trailing_semicolon_errors(
        """
        template <typename T>
        concept Indexable = requires(T t) {
          t[0];
        };

        void ordinary_function() {};
        """
    )

    # The concept definition needs its semicolon, while the function does not.
    assert len(errors) == 1

import serde


def test_coerce_fixed_and_nested_tuples_can_be_generated_serialized_and_deserialized() -> None:
    """Tuple element paths contain quotes and must remain valid generated Python code."""

    @serde.serde(type_check=serde.coerce)
    class Coordinates:
        loc: tuple[float, float]
        nested: tuple[tuple[int, int], tuple[str, float]]

    value = Coordinates(
        loc=("1", 2),
        nested=(("3", 4), (5, "6.5")),
    )

    # Defining the class itself used to fail with SyntaxError while generating
    # coercion code for paths such as data["loc"][0].
    assert serde.to_dict(value) == {
        "loc": (1.0, 2.0),
        "nested": ((3, 4), ("5", 6.5)),
    }

    # The generated deserializer must also support quoted tuple paths at
    # multiple nesting levels.
    restored = serde.from_dict(
        Coordinates,
        {
            "loc": ("7.25", "8"),
            "nested": (("9", "10"), (11, "12.5")),
        },
    )
    assert restored == Coordinates(
        loc=(7.25, 8.0),
        nested=((9, 10), ("11", 12.5)),
    )

import pytest
import dimod

from dwave.system import EmbeddingComposite
from dwave.system.warnings import WarningAction


CHAIN_STRENGTH_MESSAGE = (
    "Some quadratic biases are stronger than the given chain strength"
)


def _structured_sampler(nodelist, edgelist):
    return dimod.StructureComposite(
        dimod.ExactSolver(),
        nodelist=nodelist,
        edgelist=edgelist,
    )


def _has_chain_strength_warning(sampleset):
    return any(
        warning.get("message") == CHAIN_STRENGTH_MESSAGE
        for warning in sampleset.info.get("warnings", [])
    )


@pytest.mark.parametrize("interaction", [-2, -100])
def test_chain_strength_warning_not_issued_for_singleton_embedding(interaction):
    """No chain-strength warning is relevant when every chain is a singleton.

    This covers the reported two-variable QUBO and verifies that warning
    behavior is determined by whether chains exist, rather than by an
    arbitrary magnitude threshold on the problem's quadratic biases.
    """
    child = _structured_sampler([0, 1], [(0, 1)])
    sampler = EmbeddingComposite(
        child,
        find_embedding=lambda source, target: {0: [0], 1: [1]},
    )

    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): interaction,
    })

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert not _has_chain_strength_warning(sampleset)


def test_chain_strength_warning_issued_when_embedding_has_a_chain():
    """The warning remains applicable if the embedding actually uses a chain."""
    child = _structured_sampler([0, 1, 2], [(0, 1), (1, 2)])
    sampler = EmbeddingComposite(
        child,
        find_embedding=lambda source, target: {0: [0, 1], 1: [2]},
    )

    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): -2,
    })

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert _has_chain_strength_warning(sampleset)

import json

import yaml

from cfn_flip import to_yaml


def _mapping_value(node, key):
    """Return the YAML node associated with a string mapping key."""
    for key_node, value_node in node.value:
        if key_node.value == key:
            return value_node
    raise AssertionError("Key {!r} was not present in generated YAML".format(key))


def _assert_quoted_string_scalar(node, expected_value, rendered_yaml):
    assert node.value == expected_value
    assert node.tag == "tag:yaml.org,2002:str"
    assert node.style in ("'", '"'), (
        "Numeric JSON strings must be explicitly quoted in YAML so consumers "
        "cannot interpret them as numbers. Value {!r} had style {!r}.\n\n{}"
    ).format(expected_value, node.style, rendered_yaml)


def test_elb_ids_from_issue_are_explicit_yaml_strings():
    source = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021", "Name": "ue1"},
                "us-east-2": {"ELBID": "033677994240", "Name": "ue2"},
                "us-west-1": {"ELBID": "027434742980", "Name": "uw1"},
                "us-west-2": {"ELBID": "797873946194", "Name": "uw2"},
            }
        }
    }

    rendered = to_yaml(json.dumps(source))
    document = yaml.compose(rendered)
    regions = _mapping_value(_mapping_value(document, "Mappings"), "Regions")

    expected_ids = {
        "us-east-1": "127311923021",
        "us-east-2": "033677994240",
        "us-west-1": "027434742980",
        "us-west-2": "797873946194",
    }

    for region_node, region_value_node in regions.value:
        region = region_node.value
        _assert_quoted_string_scalar(
            _mapping_value(region_value_node, "ELBID"),
            expected_ids[region],
            rendered,
        )

    # The output must also actually deserialize as strings, not YAML numbers.
    loaded = yaml.safe_load(rendered)
    for region, expected_id in expected_ids.items():
        assert loaded["Mappings"]["Regions"][region]["ELBID"] == expected_id
        assert isinstance(loaded["Mappings"]["Regions"][region]["ELBID"], str)


def test_numeric_strings_are_preserved_in_sequences_and_as_mapping_keys():
    source = {
        "Ids": [
            "0",
            "00",
            "0123",
            "033677994240",
            "127311923021",
            "797873946194",
        ],
        "ById": {
            "001": "leading-zero key",
            "127311923021": "ordinary numeric key",
        },
        "actual_json_number": 127311923021,
    }

    rendered = to_yaml(json.dumps(source))
    document = yaml.compose(rendered)

    ids_node = _mapping_value(document, "Ids")
    for scalar_node, expected in zip(ids_node.value, source["Ids"]):
        _assert_quoted_string_scalar(scalar_node, expected, rendered)

    by_id_node = _mapping_value(document, "ById")
    for key_node, value_node in by_id_node.value:
        _assert_quoted_string_scalar(key_node, key_node.value, rendered)
        assert isinstance(value_node.value, str)

    loaded = yaml.safe_load(rendered)
    assert loaded["Ids"] == source["Ids"]
    assert all(isinstance(value, str) for value in loaded["Ids"])
    assert loaded["ById"] == source["ById"]
    assert all(isinstance(key, str) for key in loaded["ById"])

    # Preserving string IDs must not turn genuine JSON numeric values into strings.
    assert loaded["actual_json_number"] == 127311923021
    assert isinstance(loaded["actual_json_number"], int)

from typing import Optional

from serde import coerce, from_dict, serde, to_dict


def test_coerce_fixed_tuple_field_can_be_generated_serialized_and_deserialized() -> None:
    @serde(type_check=coerce)
    class Foo:
        loc: tuple[float, float]

    # Decorating the class must not raise SyntaxError while generating the
    # coercing deserializer for tuple elements.
    assert to_dict(Foo(loc=(1, 2))) == {"loc": (1.0, 2.0)}

    # Exercise the generated tuple deserializer as well: both tuple elements
    # should be coerced using the correctly rendered field expression.
    assert from_dict(Foo, {"loc": ("1.5", 2)}) == Foo(loc=(1.5, 2.0))


def test_coerce_tuple_inside_optional_field_escapes_get_expression() -> None:
    @serde(type_check=coerce)
    class OptionalTuple:
        loc: Optional[tuple[float, float]]

    # Optional tuple rendering uses data.get("loc")[index], which also embeds
    # quotes in the generated field name passed to coerce_object.
    assert from_dict(OptionalTuple, {"loc": ("3", "4.25")}) == OptionalTuple(
        loc=(3.0, 4.25)
    )
    assert from_dict(OptionalTuple, {"loc": None}) == OptionalTuple(loc=None)

