import pytest

import dimod

from dwave.system import EmbeddingComposite
from dwave.system.testing import MockDWaveSampler


CHAIN_STRENGTH_WARNING = (
    "Some quadratic biases are stronger than the given chain strength"
)


def _has_chain_strength_warning(sampleset):
    return any(
        CHAIN_STRENGTH_WARNING in warning["message"]
        for warning in sampleset.info.get("warnings", [])
    )


@pytest.mark.parametrize("interaction", [-2.0, 100.0])
def test_no_chain_strength_warning_when_embedding_has_no_chains(interaction):
    """Chain strength warnings are irrelevant for singleton-only embeddings.

    In particular, a very large problem interaction must not cause the warning
    merely because it exceeds an arbitrary magnitude threshold.
    """
    child = MockDWaveSampler()
    target_u, target_v = next(iter(child.edgelist))

    def find_singleton_embedding(source_edges, target_edges, **kwargs):
        return {0: [target_u], 1: [target_v]}

    sampler = EmbeddingComposite(child, find_embedding=find_singleton_embedding)
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): interaction,
    })

    sampleset = sampler.sample(bqm, chain_strength=1.0, warnings="SAVE")

    assert not _has_chain_strength_warning(sampleset)


def test_chain_strength_warning_is_still_reported_when_a_chain_exists():
    """Suppressing the warning for no-chain cases must not suppress it globally."""
    child = MockDWaveSampler()

    # Construct a valid embedding in which variable 0 is represented by a
    # length-two chain and one chain endpoint couples to variable 1.
    for chain_endpoint, other_variable in child.edgelist:
        possible_chain_nodes = set(child.adjacency[chain_endpoint])
        possible_chain_nodes.discard(other_variable)
        if possible_chain_nodes:
            chain_node = next(iter(possible_chain_nodes))
            break
    else:
        pytest.skip("mock sampler has no suitable chain configuration")

    def find_chained_embedding(source_edges, target_edges, **kwargs):
        return {0: [chain_node, chain_endpoint], 1: [other_variable]}

    sampler = EmbeddingComposite(child, find_embedding=find_chained_embedding)
    bqm = dimod.BinaryQuadraticModel.from_qubo({(0, 1): 2.0})

    sampleset = sampler.sample(bqm, chain_strength=1.0, warnings="SAVE")

    assert _has_chain_strength_warning(sampleset)

import pytest

from vyper.exceptions import InvalidLiteral, OverflowException


def _contract_returning(expression: str) -> str:
    return f"""
@external
def foo() -> uint256:
    return {expression}
"""


@pytest.mark.parametrize(
    "expression",
    [
        # Regression from the reported issue: both 10**18 and the resulting
        # 10**36 are valid uint256 values.
        "(10**18)**2",
        # Nested literal powers must be accepted whenever their final result
        # is representable, even when the base is substantially larger than
        # the old intermediate-base threshold.
        "(10**38)**2",
    ],
)
def test_nested_constant_powers_that_fit_uint256_compile(expression, get_contract):
    assert get_contract(_contract_returning(expression)) is not None


@pytest.mark.parametrize(
    "expression",
    [
        # 10**114 is beyond uint256's maximum value.
        "(10**38)**3",
        # uint256's largest power-of-two value is 2**255.
        "(2**128)**2",
    ],
)
def test_nested_constant_powers_outside_uint256_are_rejected(
    expression, get_contract, assert_compile_failed
):
    # Depending on the compiler phase which detects the invalid constant,
    # Vyper reports either an overflow or an out-of-bounds literal.
    assert_compile_failed(
        lambda: get_contract(_contract_returning(expression)),
        (OverflowException, InvalidLiteral),
