import pytest

from wemake_python_styleguide.violations.best_practices import (
    GettingElementByUnpackingViolation,
    WrongUnpackingViolation,
)
from wemake_python_styleguide.violations.consistency import (
    UnpackingIterableToListViolation,
)
from wemake_python_styleguide.visitors.ast.builtins import (
    WrongAssignmentVisitor,
)


@pytest.mark.parametrize('code', [
    'names[0], *_ = get_address()',
    'self.name, *_ = get_address()',
    '(name, street), *_ = get_address()',
    'name, street, *_ = get_address()',
    'name, _, city, *_ = get_address()',
    'name, _, self.city, *_ = get_address()',
    (
        'name, (street, city), self.postcode, addresses[0], '
        '*_unused = get_address()'
    ),
])
def test_getting_multiple_or_complex_elements_by_unpacking_is_forbidden(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """WPS472 must cover complex targets and more than one extracted value."""
    visitor = WrongAssignmentVisitor(
        default_options,
        tree=parse_ast_tree(code),
    )
    visitor.run()

    assert_errors(
        visitor,
        [GettingElementByUnpackingViolation],
        ignored_types=(
            UnpackingIterableToListViolation,
            WrongUnpackingViolation,
        ),
    )


def test_named_starred_target_is_not_element_getting_by_unpacking(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A meaningful starred target is normal unpacking, not WPS472."""
    visitor = WrongAssignmentVisitor(
        default_options,
        tree=parse_ast_tree('name, street, *remaining = get_address()'),
    )
    visitor.run()

    assert_errors(visitor, [])

