import json

import yaml
from yaml.nodes import MappingNode, ScalarNode, SequenceNode

from cfn_flip import to_yaml


def _mapping_value(node, key):
    assert isinstance(node, MappingNode)
    for key_node, value_node in node.value:
        if key_node.value == key:
            return value_node
    raise AssertionError(f"Could not find YAML mapping key {key!r}")


def _assert_quoted_string(node, value):
    assert isinstance(node, ScalarNode)
    assert node.value == value
    assert node.style in ("'", '"'), (
        f"Numeric-looking JSON string {value!r} must be explicitly quoted in "
        f"YAML so CloudFormation/YAML readers cannot interpret it as a number; "
        f"got style={node.style!r}"
    )


def test_elb_mapping_ids_are_all_explicit_yaml_strings():
    """The IDs from the reported template must all be emitted as quoted strings."""
    source = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021", "Name": "ue1"},
                "us-east-2": {"ELBID": "033677994240", "Name": "ue2"},
                "us-west-1": {"ELBID": "027434742980", "Name": "uw1"},
                "us-west-2": {"ELBID": "797873946194", "Name": "uw2"},
            }
        }
    }

    rendered = to_yaml(json.dumps(source))

    # The generated document must retain the JSON data types when consumed as YAML.
    assert yaml.safe_load(rendered) == source

    document = yaml.compose(rendered)
    regions = _mapping_value(_mapping_value(document, "Mappings"), "Regions")
    assert isinstance(regions, MappingNode)

    for region, region_data in source["Mappings"]["Regions"].items():
        region_node = _mapping_value(regions, region)
        id_node = _mapping_value(region_node, "ELBID")
        _assert_quoted_string(id_node, region_data["ELBID"])


def test_numeric_like_strings_are_quoted_in_values_lists_and_mapping_keys():
    """JSON strings that look like YAML scalars must not become numbers or keys."""
    numeric_strings = ["0", "123456", "001234", "-42", "1.0", "1e6"]
    source = {
        "ids": numeric_strings,
        "nested": {
            "007": "0007",
            "123": "456",
        },
    }

    rendered = to_yaml(json.dumps(source))
    assert yaml.safe_load(rendered) == source

    document = yaml.compose(rendered)
    ids_node = _mapping_value(document, "ids")
    assert isinstance(ids_node, SequenceNode)
    for item, expected in zip(ids_node.value, numeric_strings):
        _assert_quoted_string(item, expected)

    nested_node = _mapping_value(document, "nested")
    assert isinstance(nested_node, MappingNode)
    for key_node, value_node in nested_node.value:
        # Both JSON keys and values are strings. Numeric-looking keys are
        # especially important: an unquoted YAML key could become an integer.
        _assert_quoted_string(key_node, key_node.value)
        _assert_quoted_string(value_node, source["nested"][key_node.value])

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import WarningAction


CHAIN_STRENGTH_WARNING = (
    "Some quadratic biases are stronger than the given chain strength"
)


def structured_sampler():
    return dimod.StructureComposite(
        dimod.ExactSolver(),
        nodelist=[0, 1, 2],
        edgelist=[(0, 1), (1, 2)],
    )


def singleton_embedding(_source_edges, _target_edges, **kwargs):
    """Embed every logical variable in a singleton physical chain."""
    return {0: [0], 1: [1]}


def chained_embedding(_source_edges, _target_edges, **kwargs):
    """Embed logical variable 0 in a genuine two-qubit chain."""
    return {0: [0, 1], 1: [2]}


def has_chain_strength_warning(sampleset):
    return any(
        CHAIN_STRENGTH_WARNING in warning["message"]
        for warning in sampleset.info.get("warnings", [])
    )


@pytest.mark.parametrize(
    "qubo",
    [
        # The two-variable QUBO from the issue report: it embeds without chains.
        {(0, 0): 1, (1, 1): 1, (0, 1): -2},
        # The absence of chains, not the magnitude of the interaction, is what
        # makes chain strength irrelevant.
        {(0, 1): -100},
    ],
)
def test_no_chain_strength_warning_when_embedding_has_only_singletons(qubo):
    sampler = EmbeddingComposite(
        structured_sampler(),
        find_embedding=singleton_embedding,
    )
    bqm = dimod.BinaryQuadraticModel.from_qubo(qubo)

    sampleset = sampler.sample(bqm, warnings=WarningAction.SAVE)

    assert not has_chain_strength_warning(sampleset)


def test_chain_strength_warning_is_preserved_when_embedding_has_a_chain():
    sampler = EmbeddingComposite(
        structured_sampler(),
        find_embedding=chained_embedding,
    )
    bqm = dimod.BinaryQuadraticModel.from_qubo({(0, 1): -100})

    sampleset = sampler.sample(
        bqm,
        chain_strength=1,
        warnings=WarningAction.SAVE,
    )

    assert has_chain_strength_warning(sampleset)

