import json
import re

import yaml

from cfn_flip import to_yaml


def test_json_elb_id_strings_are_emitted_as_yaml_strings():
    document = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021", "Name": "ue1"},
                "us-east-2": {"ELBID": "033677994240", "Name": "ue2"},
                "us-west-1": {"ELBID": "027434742980", "Name": "uw1"},
                "us-west-2": {"ELBID": "797873946194", "Name": "uw2"},
            }
        }
    }

    rendered = to_yaml(json.dumps(document))
    loaded = yaml.safe_load(rendered)

    regions = loaded["Mappings"]["Regions"]
    for region_name, expected in document["Mappings"]["Regions"].items():
        value = regions[region_name]["ELBID"]
        assert value == expected["ELBID"]
        assert isinstance(value, str)

    # Values such as these are not recognized as octal by every YAML parser,
    # but CloudFormation must still receive them as strings.  They therefore
    # need an unambiguous string representation in the generated YAML.
    for elb_id in ("033677994240", "027434742980"):
        assert re.search(
            rf"^\s*ELBID:\s*['\"]{elb_id}['\"]\s*$",
            rendered,
            flags=re.MULTILINE,
        ), rendered


def test_every_leading_zero_numeric_json_string_is_unambiguously_quoted():
    document = {
        "Ids": {
            "valid_octal_shape": "01234567",
            "contains_eight": "00000008",
            "contains_nine": "09999999",
            "many_zeroes": "000000000000",
        }
    }

    rendered = to_yaml(json.dumps(document))

    # A YAML 1.1 loader would otherwise coerce some of these to integers,
    # while loaders with different numeric rules can disagree about the
    # invalid-octal-looking cases.  Conversion from JSON must preserve the
    # original string type in all cases.
    assert yaml.safe_load(rendered)["Ids"] == document["Ids"]

    for value in document["Ids"].values():
        assert re.search(
            rf"^\s*\w+:\s*['\"]{value}['\"]\s*$",
            rendered,
