import pytest

from alarmdecoder.panels import ADEMCO
from alarmdecoder.zonetracking import Zone, Zonetracker


class _AlarmDecoderStub:
    """Minimal decoder interface required by Zonetracker."""

    mode = ADEMCO


class _KeypadMessage:
    """A keypad-message-shaped object for exercising the public tracker API."""

    def __init__(self, text, numeric_code, check_zone=False, ready=False):
        self.text = text
        self._numeric_code = numeric_code
        self.check_zone = check_zone
        self.ready = ready

    def parse_numeric_code(self):
        return self._numeric_code


def _fault_message(zone):
    return _KeypadMessage("FAULT {}".format(zone), zone)


def _communicator_failure_message():
    return _KeypadMessage("COMM. FAILURE                   ", 0)


def _long_range_radio_check_message():
    # Long-range radio/ECP failures report numeric code 191, while the
    # actual affected zone is present only in the alpha text.
    return _KeypadMessage(
        "CHECK 103 LngRngRadio       0000",
        191,
        check_zone=True,
    )


@pytest.mark.parametrize("radio_check_first", [False, True])
def test_communicator_check_zone_can_mix_with_normal_numeric_zones(
    radio_check_first,
):
    """Communicator checks must not stop later zone tracking updates."""
    tracker = Zonetracker(_AlarmDecoderStub())

    normal_fault = _fault_message(7)
    radio_check = _long_range_radio_check_message()

    if radio_check_first:
        tracker.update(radio_check)
        tracker.update(_communicator_failure_message())
        tracker.update(normal_fault)
    else:
        tracker.update(normal_fault)
        tracker.update(_communicator_failure_message())
        tracker.update(radio_check)

    # The tracker must remain usable after the mixed int/string zone IDs
    # produced by a regular fault and a long-range-radio CHECK message.
    tracker.update(_fault_message(9))

    faulted_by_text = {str(zone) for zone in tracker.faulted}
    assert faulted_by_text == {"7", "9", "103"}

    radio_zone_id = next(zone for zone in tracker.faulted if str(zone) == "103")
    assert tracker.zones[radio_zone_id].status == Zone.CHECK

    for normal_zone in ("7", "9"):
        zone_id = next(zone for zone in tracker.faulted if str(zone) == normal_zone)
        assert tracker.zones[zone_id].status == Zone.FAULT

