import json

import yaml
from yaml.nodes import MappingNode, ScalarNode

from cfn_flip import to_yaml


def _mapping_value(node, key):
    assert isinstance(node, MappingNode)
    for key_node, value_node in node.value:
        if key_node.value == key:
            return value_node
    raise AssertionError("Could not find key {!r} in YAML output".format(key))


def _node_at_path(document, *path):
    node = yaml.compose(document)
    for key in path:
        node = _mapping_value(node, key)
    return node


def _assert_explicitly_quoted_string(document, *path):
    node = _node_at_path(document, *path)
    assert isinstance(node, ScalarNode)
    assert node.tag == "tag:yaml.org,2002:str"
    assert node.style in ("'", '"'), (
        "Numeric JSON strings must be explicitly quoted in YAML so that "
        "CloudFormation/YAML parsers cannot interpret them as numbers. "
        "Path {} was emitted as {!r}".format(path, node.value)
    )


