import json

import yaml

from cfn_flip import to_yaml


def _mapping_values(document, mapping_name):
    root = yaml.compose(document)
    root_values = {key.value: value for key, value in root.value}
    mapping = root_values[mapping_name]
    return {key.value: value for key, value in mapping.value}


def test_to_yaml_quotes_all_numeric_string_ids_including_leading_zeroes():
    """JSON string IDs must remain explicitly string-valued YAML scalars."""
    source = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021"},
                # These are the cases that could otherwise be emitted as
                # plain scalars despite being JSON strings.
                "us-east-2": {"ELBID": "033677994240"},
                "us-west-1": {"ELBID": "027434742980"},
                "us-west-2": {"ELBID": "797873946194"},
            }
        }
    }

    rendered = to_yaml(json.dumps(source))

    mappings = _mapping_values(rendered, "Mappings")
    regions = {key.value: value for key, value in mappings["Regions"].value}

    for region_node in regions.values():
        elbid_node = {key.value: value for key, value in region_node.value}["ELBID"]

        assert elbid_node.tag == "tag:yaml.org,2002:str"
        assert elbid_node.style in ("'", '"')


def test_to_yaml_quotes_leading_zero_numeric_strings_regardless_of_digits():
    """Leading-zero IDs must be quoted even when they are not valid octal."""
    source = {
        "IDs": {
            # Valid old-style octal-looking number.
            "valid_octal_digits": "001234567",
            # Invalid octal digits were the problematic plain-scalar cases.
            "contains_eight": "08",
            "contains_nine": "09",
            "long_mixed_digits": "012345678901",
        }
    }

    rendered = to_yaml(json.dumps(source))

    ids = _mapping_values(rendered, "IDs")
    for name, expected_value in source["IDs"].items():
        node = ids[name]
        assert node.value == expected_value
        assert node.tag == "tag:yaml.org,2002:str"
        assert node.style in ("'", '"')

