import json
import re

import yaml

from cfn_flip import to_yaml


def _json_to_yaml_and_load(document):
    rendered = to_yaml(json.dumps(document))
    return rendered, yaml.safe_load(rendered)


def test_elb_ids_with_and_without_leading_zero_are_explicit_strings():
    document = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021", "Name": "ue1"},
                "us-east-2": {"ELBID": "033677994240", "Name": "ue2"},
                "us-west-1": {"ELBID": "027434742980", "Name": "uw1"},
                "us-west-2": {"ELBID": "797873946194", "Name": "uw2"},
            }
        }
    }

    rendered, loaded = _json_to_yaml_and_load(document)

    expected_ids = {
        "127311923021",
        "033677994240",
        "027434742980",
        "797873946194",
    }

    # Every ID must be explicitly quoted in the YAML, rather than relying on
    # whichever numeric/octal rules a downstream CloudFormation YAML parser uses.
    emitted_ids = re.findall(r"^\s*ELBID:\s*(['\"])([^'\"]+)\1\s*$", rendered, re.MULTILINE)
    assert {value for _, value in emitted_ids} == expected_ids

    regions = loaded["Mappings"]["Regions"]
    for region in regions.values():
        assert isinstance(region["ELBID"], str)
        assert region["ELBID"] in expected_ids


def test_numeric_looking_json_strings_round_trip_as_strings_in_yaml():
    ids = {
        # Valid YAML 1.1 octal-looking values must not become integers.
        "valid_octal": "01234567",
        # Values containing 8 or 9 were the reported inconsistent cases.
        "invalid_octal": "033677994240",
        "another_invalid_octal": "027434742980",
        # A zero-only identifier is also a JSON string, not a number.
        "zero": "0",
        "zero_padded": "000123",
        # Non-zero numeric identifiers must remain strings as well.
        "decimal": "127311923021",
    }
    document = {"Mappings": {"Identifiers": ids}}

    rendered, loaded = _json_to_yaml_and_load(document)

    assert loaded == document
    for name, original_value in ids.items():
        value = loaded["Mappings"]["Identifiers"][name]
        assert isinstance(value, str)
        assert value == original_value

    # In particular, no leading-zero value may be emitted as an unquoted scalar.
    for value in ("01234567", "033677994240", "027434742980", "000123"):
        assert re.search(
            r"^\s*[^:\n]+:\s*(['\"])" + re.escape(value) + r"\1\s*$",
            rendered,
            re.MULTILINE,
        ), "leading-zero identifier {!r} was not quoted".format(value)

