import dimod
import pytest

from dwave.system.composites import EmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _chain_strength_warnings(sampleset):
    return [
        warning for warning in sampleset.info.get("warnings", ())
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


def _structured_random_sampler(nodes, edges):
    return dimod.StructureComposite(dimod.RandomSampler(), nodes, edges)


def test_no_chain_strength_warning_for_all_singleton_embedding():
    """Strong problem couplings must not warn when the embedding has no chains."""
    # This is the QUBO from the reported issue. The target has a direct edge
    # for the problem interaction, so both source variables are singletons.
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): -2,
    })

    embedding = {0: [0], 1: [1]}

    sampler = EmbeddingComposite(
        _structured_random_sampler([0, 1], [(0, 1)]),
        find_embedding=lambda source, target, **kwargs: embedding,
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1.0,
        warnings="SAVE",
        return_embedding=True,
    )

    assert all(len(chain) == 1
               for chain in sampleset.info["embedding_context"]["embedding"].values())
    assert _chain_strength_warnings(sampleset) == []


def test_chain_strength_warning_remains_for_embedding_with_actual_chain():
    """Suppressing the false positive must not suppress legitimate warnings."""
    # Variable 0 is deliberately represented by a two-qubit chain. The
    # interaction has magnitude greater than the supplied chain strength.
    embedding = {0: [0, 1], 1: [2]}

    sampler = EmbeddingComposite(
        _structured_random_sampler([0, 1, 2], [(0, 1), (1, 2)]),
        find_embedding=lambda source, target, **kwargs: embedding,
    )

    sampleset = sampler.sample_ising(
        {},
        {(0, 1): -2},
        chain_strength=1.0,
        warnings="SAVE",
        return_embedding=True,
    )

    assert any(len(chain) > 1
               for chain in sampleset.info["embedding_context"]["embedding"].values())

    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == 1
    assert warnings[0]["data"]["source_interactions"] == [(0, 1)]

