import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


def test_is_implementation_requires_an_explicit_declaration_by_default():
    class IService(Interface):
        def execute(self, value):
            pass

    class StructurallyCompatibleService:
        def execute(self, value):
            return value

    # Having the same API alone must not make this class an implementation:
    # interfaces are used as explicit identities, not just duck-typed contracts.
    assert not IsImplementation(StructurallyCompatibleService, IService)
    assert not IsImplementation(StructurallyCompatibleService(), IService)

    # Duck typing remains available only when specifically requested.
    assert IsImplementation(
        StructurallyCompatibleService, IService, requires_declaration=False
    )
    assert IsImplementation(
        StructurallyCompatibleService(), IService, requires_declaration=False
    )


def test_declared_implementations_are_recognized_by_default():
    class IService(Interface):
        def execute(self, value):
            pass

    @ImplementsInterface(IService)
    class DeclaredService:
        def execute(self, value):
            return value

    assert IsImplementation(DeclaredService, IService)
    assert IsImplementation(DeclaredService(), IService)


def test_declare_class_implements_invalidates_prior_negative_declaration_check():
    class IService(Interface):
        def execute(self):
            pass

    class ServiceDeclaredLater:
        def execute(self):
            pass

    # Seed the declaration-aware cache with a negative result before the
    # interface is declared.
    assert not IsImplementation(ServiceDeclaredLater, IService)
    assert IsImplementation(
        ServiceDeclaredLater, IService, requires_declaration=False
    )

    DeclareClassImplements(ServiceDeclaredLater, IService)

    # A prior result must not prevent an explicit later declaration from being
    # observed by the default, declaration-aware check.
    assert IsImplementation(ServiceDeclaredLater, IService)
    assert IsImplementation(ServiceDeclaredLater(), IService)


def test_related_public_checks_use_declaration_aware_default():
    class IFirst(Interface):
        def first(self):
            pass

    class ISecond(Interface):
        def second(self):
            pass

    class StructurallyCompatible:
        def first(self):
            pass

    # Checking "any" interface must not accidentally reintroduce duck typing.
    assert not IsImplementationOfAny(StructurallyCompatible, [IFirst, ISecond])
    assert IsImplementationOfAny(
        StructurallyCompatible,
        [IFirst, ISecond],
        requires_declaration=False,
    )

    # Assertion-style checking follows the same default, while retaining an
    # opt-in path for callers that intentionally want structural checking.
    with pytest.raises(AssertionError):
        AssertImplements(StructurallyCompatible, IFirst)

    AssertImplements(
        StructurallyCompatible,
        IFirst,
        requires_declaration=False,
    )

import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


def test_structural_match_is_not_an_implementation_by_default():
    class IWorker(Interface):
        def work(self, value):
            ...

    class DuckWorker:
        def work(self, value):
            return value

    # Having matching methods alone must not make an object an implementation.
    assert not IsImplementation(DuckWorker, IWorker)
    assert not IsImplementation(DuckWorker(), IWorker)
    assert not IsImplementationOfAny(DuckWorker(), [IWorker])

    with pytest.raises(AssertionError, match="does not declare"):
        AssertImplements(DuckWorker(), IWorker)

    # Duck typing remains available only when explicitly requested.
    assert IsImplementation(DuckWorker, IWorker, requires_declaration=False)
    assert IsImplementationOfAny(
        DuckWorker(), [IWorker], requires_declaration=False
    )
    AssertImplements(DuckWorker(), IWorker, requires_declaration=False)


def test_explicitly_declared_implementation_is_accepted_by_default():
    class IWorker(Interface):
        def work(self, value):
            ...

    @ImplementsInterface(IWorker)
    class DeclaredWorker:
        def work(self, value):
            return value

    worker = DeclaredWorker()

    assert IsImplementation(DeclaredWorker, IWorker)
    assert IsImplementation(worker, IWorker)
    assert IsImplementationOfAny(worker, [IWorker])
    AssertImplements(worker, IWorker)


def test_declare_class_implements_updates_cached_declaration_checks():
    class IWorker(Interface):
        def work(self, value):
            ...

    class WorkerDeclaredLater:
        def work(self, value):
            return value

    # Populate both declaration-sensitive and structural-check cache entries.
    assert not IsImplementation(WorkerDeclaredLater, IWorker)
    assert IsImplementation(
        WorkerDeclaredLater, IWorker, requires_declaration=False
    )

    # Declaration must be validated structurally, then make future default checks
    # recognize the class despite the earlier cached negative result.
    DeclareClassImplements(WorkerDeclaredLater, IWorker)

    assert IsImplementation(WorkerDeclaredLater, IWorker)
    assert IsImplementation(WorkerDeclaredLater(), IWorker)
    assert IsImplementationOfAny(WorkerDeclaredLater(), [IWorker])
