import json
import os
import queue
import subprocess
import sys
import threading
import time
from pathlib import Path


class _DapClient:
    def __init__(self, process):
        self.process = process
        self._sequence = 1
        self._messages = []
        self._incoming = queue.Queue()
        self._reader = threading.Thread(target=self._read_messages, daemon=True)
        self._reader.start()

    def _read_messages(self):
        try:
            while True:
                headers = {}
                while True:
                    line = self.process.stdout.readline()
                    if not line:
                        return
                    line = line.decode("ascii", errors="replace").strip()
                    if not line:
                        break
                    if ":" in line:
                        key, value = line.split(":", 1)
                        headers[key.lower()] = value.strip()

                content_length = int(headers["content-length"])
                payload = self.process.stdout.read(content_length)
                if len(payload) != content_length:
                    return
                self._incoming.put(json.loads(payload.decode("utf-8")))
        except Exception as exc:
            self._incoming.put(exc)

    def send_request(self, command, arguments=None):
        sequence = self._sequence
        self._sequence += 1
        message = {
            "seq": sequence,
            "type": "request",
            "command": command,
            "arguments": arguments or {},
        }
        encoded = json.dumps(message).encode("utf-8")
        self.process.stdin.write(
            b"Content-Length: " + str(len(encoded)).encode("ascii") + b"\r\n\r\n" + encoded
        )
        self.process.stdin.flush()
        return sequence

    def wait_for(self, predicate, timeout=20):
        deadline = time.monotonic() + timeout

        while True:
            for index, message in enumerate(self._messages):
                if predicate(message):
                    return self._messages.pop(index)

            remaining = deadline - time.monotonic()
            if remaining <= 0:
                seen = [
                    (
                        message
                        if isinstance(message, Exception)
                        else {
                            key: message.get(key)
                            for key in ("type", "event", "command", "success", "message")
                        }
                    )
                    for message in self._messages
                ]
                raise AssertionError(f"Timed out waiting for DAP message. Seen: {seen!r}")

            try:
                message = self._incoming.get(timeout=remaining)
            except queue.Empty:
                continue

            if isinstance(message, Exception):
                raise AssertionError(f"Unable to read DAP messages: {message}") from message
            self._messages.append(message)

    def wait_for_response(self, request_sequence):
        response = self.wait_for(
            lambda message: (
                message.get("type") == "response"
                and message.get("request_seq") == request_sequence
            )
        )
        assert response.get("success"), response
        return response


def _indices_and_values(variables):
    result = {}
    for variable in variables:
        name = variable["name"]
        normalized = name[1:-1] if name.startswith("[") and name.endswith("]") else name
        if normalized.isdigit():
            result[int(normalized)] = variable["value"]
    return result


def _reported_length(variable, children_response):
    if variable.get("indexedVariables") is not None:
        return int(variable["indexedVariables"])

    if children_response.get("indexedVariables") is not None:
        return int(children_response["indexedVariables"])

    for child in children_response.get("variables", []):
        if child.get("name") == "len()":
            return int(child["value"])

    return None


def test_debug_adapter_enumerates_ctypes_arrays_as_indexed_containers(tmp_path):
    """ctypes arrays must be expandable as containers in the debugger protocol."""
    root = Path(__file__).resolve().parents[1]
    program = tmp_path / "ctypes_arrays.py"
    program_source = """\
import ctypes

file_bytes = bytearray([1, 2, 3, 4, 5])
x = (ctypes.c_uint8 * len(file_bytes)).from_buffer(file_bytes)
integers = (ctypes.c_int * 3)(-10, 0, 42)
empty = (ctypes.c_int * 0)()
stop_here = True
"""
    program.write_text(program_source)
    breakpoint_line = program_source.splitlines().index("stop_here = True") + 1

    env = os.environ.copy()
    source_path = str(root / "src")
    env["PYTHONPATH"] = source_path + os.pathsep + env.get("PYTHONPATH", "")

    process = subprocess.Popen(
        [sys.executable, "-u", "-m", "debugpy.adapter"],
        cwd=str(root),
        env=env,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    client = _DapClient(process)

    try:
        initialize = client.send_request(
            "initialize",
            {
                "clientID": "pytest",
                "adapterID": "debugpy",
                "pathFormat": "path",
                "linesStartAt1": True,
                "columnsStartAt1": True,
            },
        )
        client.wait_for_response(initialize)

        launch = client.send_request(
            "launch",
            {
                "name": "ctypes-array-test",
                "type": "python",
                "request": "launch",
                "program": str(program),
                "cwd": str(tmp_path),
                "console": "internalConsole",
                "redirectOutput": False,
                "justMyCode": True,
            },
        )

        client.wait_for(
            lambda message: message.get("type") == "event" and message.get("event") == "initialized"
        )

        set_breakpoints = client.send_request(
            "setBreakpoints",
            {
                "source": {"path": str(program)},
                "breakpoints": [{"line": breakpoint_line}],
            },
        )
        breakpoint_response = client.wait_for_response(set_breakpoints)
        assert breakpoint_response["body"]["breakpoints"][0]["verified"], breakpoint_response

        configuration_done = client.send_request("configurationDone")
        client.wait_for_response(configuration_done)
        client.wait_for_response(launch)

        stopped = client.wait_for(
            lambda message: (
                message.get("type") == "event"
                and message.get("event") == "stopped"
                and message.get("body", {}).get("reason") == "breakpoint"
            )
        )
        thread_id = stopped["body"]["threadId"]

        stack = client.send_request("stackTrace", {"threadId": thread_id})
        frame_id = client.wait_for_response(stack)["body"]["stackFrames"][0]["id"]

        scopes = client.send_request("scopes", {"frameId": frame_id})
        scope_list = client.wait_for_response(scopes)["body"]["scopes"]
        locals_scope = next(
            scope for scope in scope_list if scope["name"].lower() == "locals"
        )

        locals_request = client.send_request(
            "variables",
            {"variablesReference": locals_scope["variablesReference"]},
        )
        local_variables = client.wait_for_response(locals_request)["body"]["variables"]
        locals_by_name = {variable["name"]: variable for variable in local_variables}

        for name in ("x", "integers", "empty"):
            assert name in locals_by_name, f"{name} was not exposed as a local debugger variable"
            assert locals_by_name[name]["variablesReference"] != 0, (
                f"{name} is not expandable in the debugger: {locals_by_name[name]!r}"
            )

        def children_of(name):
            variable = locals_by_name[name]
            request = client.send_request(
                "variables",
                {"variablesReference": variable["variablesReference"]},
            )
            response = client.wait_for_response(request)["body"]
            return variable, response

        x_variable, x_children = children_of("x")
        assert _indices_and_values(x_children["variables"]) == {
            0: "1",
            1: "2",
            2: "3",
            3: "4",
            4: "5",
        }
        assert _reported_length(x_variable, x_children) == 5

        integers_variable, integers_children = children_of("integers")
        assert _indices_and_values(integers_children["variables"]) == {
            0: "-10",
            1: "0",
            2: "42",
        }
        assert _reported_length(integers_variable, integers_children) == 3

        empty_variable, empty_children = children_of("empty")
        assert _indices_and_values(empty_children["variables"]) == {}
        assert _reported_length(empty_variable, empty_children) == 0

        continue_request = client.send_request("continue", {"threadId": thread_id})
        client.wait_for_response(continue_request)
    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=5)

