        @string{jan = "Jan."}

        @inbook{inbook-full,
            month = 10 # "~" # jan,
            title = "A" # {B} # 3
        }
        """
    )

    library = Splitter(bibtex).split()

    assert len(library.failed_blocks) == 0
    entry = library.entries_dict["inbook-full"]
    assert entry.fields_dict["month"].value == '10 # "~" # jan'
