def test_parse_string_concatenates_all_bibtex_field_token_types():
    bibtex = dedent(
        """\
        @string{jan = "Jan."}

        @inbook{inbook-full,
            month = 10 # "~" # jan,
            title = {Part {#} one} # " / " # "two#three",
            note = "A # character inside one string is literal"
        }
        """
    )

    library = bibtexparser.parse_string(bibtex)

    assert len(library.failed_blocks) == 0
    entry = library.entries_dict["inbook-full"]

