import pytest


# Exercise the same vendored pydevd type-resolution code that supplies children
# to debugger variable views, rather than importing the proposed ctypes plugin
# directly.
_REPO_ROOT = Path(__file__).resolve().parents[1]
_PYDEVD_ROOT = _REPO_ROOT / "src" / "debugpy" / "_vendored" / "pydevd"
sys.path.insert(0, str(_PYDEVD_ROOT))

from _pydevd_bundle.pydevd_xml import get_type


def _debugger_children(value):
    """Return the resolver and child dictionary used for a debugger variable."""
    _, _, resolver = get_type(value)
    return resolver, resolver.get_dictionary(value)


def _indexed_children(children):
    return {
        key: value
        for key, value in children.items()
        if isinstance(key, str) and key.isdecimal()
    }


def test_ctypes_array_from_buffer_is_enumerated_with_length():
    # This is the construction described in the issue: an array backed by a
    # mutable byte buffer. Mutating the buffer also verifies that the displayed
    # values are the array's indexed contents, not merely type attributes.
    file_bytes = bytearray([1, 2, 3, 4, 5])
    array = (ctypes.c_uint8 * len(file_bytes)).from_buffer(file_bytes)
    file_bytes[2] = 99

    _, children = _debugger_children(array)

    assert children["len()"] == 5
    assert _indexed_children(children) == {
        "0": 1,
        "1": 2,
        "2": 99,
        "3": 4,
        "4": 5,
    }


@pytest.mark.parametrize(
    ("array", "expected"),
    [
        ((ctypes.c_int * 3)(-10, 0, 42), {"0": -10, "1": 0, "2": 42}),
        ((ctypes.c_char * 3)(b"a", b"b", b"c"), {"0": b"a", "1": b"b", "2": b"c"}),
        ((ctypes.c_int * 0)(), {}),
    ],
)
def test_ctypes_arrays_of_multiple_element_types_are_containers(array, expected):
    _, children = _debugger_children(array)

    assert children["len()"] == len(array)
    assert _indexed_children(children) == expected


def test_nested_ctypes_arrays_are_enumerable_at_each_level():
    matrix = ((ctypes.c_short * 2) * 2)((10, 11), (20, 21))

    _, outer_children = _debugger_children(matrix)

    assert outer_children["len()"] == 2
    assert set(_indexed_children(outer_children)) == {"0", "1"}

    _, first_row_children = _debugger_children(outer_children["0"])
    _, second_row_children = _debugger_children(outer_children["1"])

    assert first_row_children["len()"] == 2
    assert _indexed_children(first_row_children) == {"0": 10, "1": 11}
    assert second_row_children["len()"] == 2
    assert _indexed_children(second_row_children) == {"0": 20, "1": 21}

