from textwrap import dedent

import bibtexparser


def _fields(bibtex_source: str):
    library = bibtexparser.parse_string(dedent(bibtex_source))
    assert not library.failed_blocks
    assert len(library.entries) == 1
    return library.entries[0].fields_dict


def test_field_concatenation_resolves_number_quoted_string_and_macro():
    fields = _fields(
        r'''
        @STRING{ jan = "Jan." }
        @STRING{ suffix = { edition} }

        @INBOOK{concatenated,
          month = 10 # "~" # jan,
          label = 007#"x"#suffix,
          following = "This field must still be parsed"
        }
        '''
    )

    # Numbers are string-like BibTeX tokens: their spelling, including leading
    # zeroes, must be retained while they are concatenated.
    assert fields["month"].value == "10~Jan."
    assert fields["label"].value == "007x edition"

    # A concatenated field must end at its comma rather than consume subsequent
    # fields in the entry.
    assert fields["following"].value == "This field must still be parsed"


def test_concatenation_respects_hashes_and_nested_braces_inside_string_tokens():
    fields = _fields(
        r'''
        @STRING{ ending = "!" }

        @ARTICLE{literal_hashes,
          title = {Part {One #1}} # " and #2" # ending,
          note = "Issue #42",
          howpublished = {A {brace-balanced # token} value} # " / appendix"
        }
        '''
    )

    # A # is an operator only outside a quoted/braced field token. Nested
    # braces are content and must remain balanced in the resulting value.
    assert fields["title"].value == "Part {One #1} and #2!"
    assert fields["note"].value == "Issue #42"
    assert fields["howpublished"].value == "A {brace-balanced # token} value / appendix"

