import ast

import pytest

from wemake_python_styleguide.logic.tree.variables import (
    is_getting_element_by_unpacking,
)


def _unpacking_targets(code):
    """Return tuple-unpacking assignment targets from source code."""
    assignment = ast.parse(code).body[0]
    return assignment.targets[0].elts


@pytest.mark.parametrize('code', [
    'names[0], *_ = get_address()',
    'self.name, *_ = get_address()',
    '(name, street), *_ = get_address()',
    'name, street, *_ = get_address()',
    'name, _, city, *_ = get_address()',
    'name, _, self.city, *_ = get_address()',
    '*_, name, street = get_address()',
    '*_, self.name, self.street = get_address()',
])
def test_getting_element_by_unpacking_detects_complex_targets(code):
    """WPS472 recognizes all supported targets before or after ``*_``."""
    assert is_getting_element_by_unpacking(_unpacking_targets(code))


@pytest.mark.parametrize('code', [
    'name, *rest = get_address()',
    '*rest, name = get_address()',
    '*_ = get_address()',
    'name = get_address()',
])
def test_getting_element_by_unpacking_requires_unused_starred_target(code):
    """Only discarding the remaining values is an element-by-unpacking pattern."""
    if isinstance(ast.parse(code).body[0].targets[0], ast.Tuple):
        targets = _unpacking_targets(code)
    else:
        targets = [ast.parse(code).body[0].targets[0]]

    assert not is_getting_element_by_unpacking(targets)

