import sys
from pathlib import Path

import pytest


# Exercise the vendored debugger implementation that debugpy uses.
PYDEVD_ROOT = (
    Path(__file__).resolve().parents[1] / "src" / "debugpy" / "_vendored" / "pydevd"
)
if str(PYDEVD_ROOT) not in sys.path:
    sys.path.insert(0, str(PYDEVD_ROOT))

from _pydevd_bundle.pydevd_xml import get_type


def _debugger_children(value):
    """Return the debugger's child dictionary for a value."""
    _, _, resolver = get_type(value)
    assert resolver is not None, "Debugger did not select a resolver for the ctypes array"
    return resolver.get_dictionary(value)


def _displayed_items(value):
    """Return the indexed children that the debugger would expose for a value."""
    children = _debugger_children(value)
    return {key: item for key, item in children.items() if key.isdigit()}


def _assert_debugger_reports_length(value):
    # The resolver's dictionary is the data used to populate expandable variables.
    # Collection resolvers expose their length through the synthetic len() child.
    children = _debugger_children(value)
    assert children["len()"] == len(value)


def test_ctypes_array_from_buffer_is_enumerated_and_live():
    """The exact from_buffer-style array from the report must behave as a container."""
    file_bytes = bytearray(b"\x01\x02\x03\x04\x05")
    array = (ctypes.c_uint8 * len(file_bytes)).from_buffer(file_bytes)

    assert _displayed_items(array) == {
        "0": 1,
        "1": 2,
        "2": 3,
        "3": 4,
        "4": 5,
    }
    _assert_debugger_reports_length(array)

    # A variables window must show the current contents, not a one-time conversion.
    file_bytes[2] = 99
    assert _displayed_items(array)["2"] == 99


@pytest.mark.parametrize(
    "array",
    [
        (ctypes.c_int * 3)(-10, 0, 42),
        (ctypes.c_char * 3)(b"a", b"b", b"c"),
        (ctypes.c_double * 2)(1.25, -3.5),
    ],
)
def test_ctypes_arrays_of_different_element_types_are_enumerated(array):
    assert _displayed_items(array) == {
        str(index): array[index] for index in range(len(array))
    }
    _assert_debugger_reports_length(array)


def test_empty_and_nested_ctypes_arrays_are_containers():
    empty = (ctypes.c_int * 0)()
    assert _displayed_items(empty) == {}
    _assert_debugger_reports_length(empty)

    row_type = ctypes.c_int * 2
    matrix = (row_type * 2)(row_type(1, 2), row_type(3, 4))

    outer_items = _displayed_items(matrix)
    assert set(outer_items) == {"0", "1"}
    _assert_debugger_reports_length(matrix)

    # Each child is itself a ctypes array and must remain expandable.
    assert _displayed_items(outer_items["0"]) == {"0": 1, "1": 2}
    assert _displayed_items(outer_items["1"]) == {"0": 3, "1": 4}
    _assert_debugger_reports_length(outer_items["0"])

