import json

from temba_client.serialization import (
    DatetimeField,
    ObjectField,
    ObjectListField,
    TembaObject,
)


class TimestampResponse(TembaObject):
    timestamp = DatetimeField()


class Run(TembaObject):
    started_on = DatetimeField()
    completed_on = DatetimeField()


class RunResponse(TembaObject):
    run = ObjectField(Run)


class RunListResponse(TembaObject):
    runs = ObjectListField(Run)


def test_null_datetime_from_server_round_trips_as_json_null():
    """A null datetime received from the API must be serializable again."""
    payload = {"timestamp": None}

    response = TimestampResponse.deserialize(payload)

    assert response.timestamp is None
    assert response.serialize() == payload
    assert json.loads(json.dumps(response.serialize())) == payload


def test_unset_datetime_on_created_object_serializes_as_null():
    """Datetime fields omitted while creating an object are represented as null."""
    response = TimestampResponse.create()

    assert response.timestamp is None
    assert response.serialize() == {"timestamp": None}

    # This is also the field-level contract used by TembaObject.serialize().
    assert DatetimeField().serialize(None) is None


def test_null_datetimes_in_nested_object_and_object_list_can_be_reserialized():
    """
    Reproduce the API-response shape from the reported traceback: a collection
    of deserialized objects containing null DatetimeField values.
    """
    single_payload = {
        "run": {
            "started_on": None,
            "completed_on": None,
        }
    }
    single_response = RunResponse.deserialize(single_payload)

    assert single_response.run.started_on is None
    assert single_response.run.completed_on is None
    assert single_response.serialize() == single_payload

    list_payload = {
        "runs": [
            {"started_on": None, "completed_on": None},
            {"started_on": None, "completed_on": None},
        ]
    }
    list_response = RunListResponse.deserialize(list_payload)

    assert all(run.started_on is None for run in list_response.runs)
    assert all(run.completed_on is None for run in list_response.runs)
    assert list_response.serialize() == list_payload
    assert json.loads(json.dumps(list_response.serialize())) == list_payload

