import os
from pathlib import Path

import pytest

import compress_pickle


@pytest.mark.parametrize("compression", ["gzip", "infer"])
@pytest.mark.parametrize("path_kind", ["string", "pathlib", "bytes"])
def test_dump_preserves_compound_pkl_gz_filename(
    tmp_path: Path, compression: str, path_kind: str
):
    """A requested ``.pkl.gz`` filename must not be rewritten to ``.pklgz``."""
    requested_path = tmp_path / "model.v1.pkl.gz"

    if path_kind == "string":
        destination = str(requested_path)
    elif path_kind == "pathlib":
        destination = requested_path
    else:
        destination = os.fsencode(requested_path)

    value = {"name": "compound extension", "items": [1, 2, 3]}
    compress_pickle.dump(value, destination, compression=compression)

    # The exact user-supplied compound suffix is part of the public file path.
    assert requested_path.is_file()
    assert not (tmp_path / "model.v1.pklgz").exists()

    # It must also remain a normal gzip-inferable pickle path.
    assert compress_pickle.load(requested_path, compression="infer") == value

