import pandas as pd

from mesa.batchrunner import batch_run
from mesa.model import Model


class _Schedule:
    def __init__(self):
        self.steps = 0


class ExoticParameterModel(Model):
    """Minimal model which records the exotic constructor values it receives."""

    def __init__(self, scenario, input_data=None, social_network_parameters=None):
        super().__init__()
        self.schedule = _Schedule()
        self.running = True

        self.datacollector = type(
            "Collector",
            (),
            {
                "model_vars": {
                    "received_scenario": [scenario],
                    "received_frame_columns": [
                        tuple(input_data.columns) if input_data is not None else None
                    ],
                    "received_average_degree": [
                        (
                            social_network_parameters["average_degree"]
                            if social_network_parameters is not None
                            else None
                        )
                    ],
                },
                "_agent_records": {},
            },
        )()

    def step(self):
        self.schedule.steps += 1
        self.running = False


def test_batch_run_keeps_dataframe_and_mapping_fixed_while_sweeping_scenarios():
    input_data = pd.DataFrame(
        {"region": ["north", "south"], "value": [10, 20]}
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
        "groups": ["a", "b"],
    }

    results = batch_run(
        ExoticParameterModel,
        {
            "input_data": input_data,
            "social_network_parameters": network_parameters,
            "scenario": ["baseline", "scenario1", "scenario2"],
        },
        number_processes=1,
        iterations=2,
        display_progress=False,
    )

    # Neither a DataFrame nor a dict should be expanded into columns or keys.
    assert len(results) == 6
    assert {row["received_scenario"] for row in results} == {
        "baseline",
        "scenario1",
        "scenario2",
    }
    assert {row["received_frame_columns"] for row in results} == {
        ("region", "value")
    }
    assert {row["received_average_degree"] for row in results} == {10}

    # Batch runs must also support repeated runs when their fixed parameters
    # are unhashable complex objects.
    for scenario in ("baseline", "scenario1", "scenario2"):
        assert sorted(
            row["iteration"]
            for row in results
            if row["received_scenario"] == scenario
        ) == [0, 1]

    for row in results:
        assert isinstance(row["input_data"], pd.DataFrame)
        assert row["input_data"].equals(input_data)
        assert row["social_network_parameters"] == network_parameters


def test_batch_run_treats_a_single_string_as_one_parameter_value():
    results = batch_run(
        ExoticParameterModel,
        {"scenario": "baseline"},
        number_processes=1,
        display_progress=False,
    )

    assert len(results) == 1
    assert results[0]["scenario"] == "baseline"
    assert results[0]["received_scenario"] == "baseline"


def test_batch_run_can_sweep_a_list_of_dictionary_values():
    first = {"average_degree": 4, "rewiring_probability": 0.05}
    second = {"average_degree": 12, "rewiring_probability": 0.2}

    results = batch_run(
        ExoticParameterModel,
        {
            "scenario": "baseline",
            "social_network_parameters": [first, second],
        },
        number_processes=1,
        display_progress=False,
    )

    # A dict directly is a fixed value, but dicts deliberately placed in a
    # list are individual values in the parameter sweep.
    assert len(results) == 2
    assert {row["received_average_degree"] for row in results} == {4, 12}
    assert {
        row["social_network_parameters"]["rewiring_probability"] for row in results
    } == {0.05, 0.2}

import io
import pprint

from baseclasses.utils import CaseInsensitiveDict, CaseInsensitiveSet


def _pprint(value, *, width=80):
    """Render a value through the public pprint API."""
    stream = io.StringIO()
    pprint.pprint(value, stream=stream, width=width)
    return stream.getvalue()


def test_case_insensitive_dict_pprint_matches_plain_dict_and_wraps():
    values = {
        "b-longstring": 2,
        "a-longstring": 1,
        "c-longstring": 3,
        "e-longstring": 5,
        "d-longstring": 4,
    }

    expected = _pprint(values)
    actual = _pprint(CaseInsensitiveDict(values))

    assert actual == expected
    assert actual == (
        "{'a-longstring': 1,\n"
        " 'b-longstring': 2,\n"
        " 'c-longstring': 3,\n"
        " 'd-longstring': 4,\n"
        " 'e-longstring': 5}\n"
    )


def test_case_insensitive_set_pprint_wraps_at_requested_width():
    values = {
        "alpha-element-with-a-long-name",
        "bravo-element-with-a-long-name",
        "charlie-element-with-a-long-name",
        "delta-element-with-a-long-name",
    }

    actual = _pprint(CaseInsensitiveSet(values), width=40)

    # This specifically guards against the regression: pprint previously used
    # the container's repr as one unbroken line instead of formatting its items.
    assert len(actual.splitlines()) > 2
    assert "\n " in actual
    for value in values:
        assert repr(value) in actual


def test_case_insensitive_containers_are_pretty_printed_when_nested():
    dictionary_values = {
        "first-option-with-a-long-name": 1,
        "second-option-with-a-long-name": 2,
        "third-option-with-a-long-name": 3,
    }
    set_values = {
        "first-set-element-with-a-long-name",
        "second-set-element-with-a-long-name",
        "third-set-element-with-a-long-name",
    }
    nested = CaseInsensitiveDict(
        {
            "dictionary": CaseInsensitiveDict(dictionary_values),
            "set": CaseInsensitiveSet(set_values),
        }
    )

    actual = _pprint(nested, width=45)

    # pprint must continue to dispatch to the custom containers even when they
    # occur below another mapping, rather than embedding their one-line repr.
    assert len(actual.splitlines()) > 5
    for key, value in dictionary_values.items():
        assert repr(key) in actual
        assert repr(value) in actual
    for value in set_values:
        assert repr(value) in actual

import pytest

from compress_pickle import dump, load


@pytest.mark.parametrize("compression", ["gzip", "infer"])
@pytest.mark.parametrize("use_string_path", [False, True])
def test_dump_preserves_pickle_gzip_compound_extension(
    tmp_path, compression, use_string_path
):
    """A supplied ``.pkl.gz`` path must not be rewritten to ``.pklgz``."""
    target = tmp_path / "model.output.pkl.gz"
    path = str(target) if use_string_path else target
    payload = {"numbers": [1, 2, 3], "name": "compound extension"}

    dump(payload, path, compression=compression)

    assert target.is_file()
    assert not (tmp_path / "model.output.pklgz").exists()
    assert load(target, compression="infer") == payload

from __future__ import annotations

from collections.abc import Callable
from typing import Any

import numpy as np
import pytest

from zarr import Array, AsyncArray, AsyncGroup, Group
from zarr.store import MemoryStore


def _create_sync(
    group: Group, method: str, prototype: Array
) -> tuple[Array, np.ndarray | None]:
    name = f"{method}_result"
    if method == "empty":
        return group.empty(name, shape=(2, 3), dtype="int16"), None
    if method == "zeros":
        return group.zeros(name, shape=(2, 3), dtype="int16"), np.zeros((2, 3), dtype="int16")
    if method == "ones":
        return group.ones(name, shape=(2, 3), dtype="int16"), np.ones((2, 3), dtype="int16")
    if method == "full":
        return group.full(name, shape=(2, 3), dtype="int16", fill_value=7), np.full(
            (2, 3), 7, dtype="int16"
        )
    if method == "empty_like":
        return group.empty_like(name, prototype), None
    if method == "zeros_like":
        return group.zeros_like(name, prototype), np.zeros((2, 3), dtype="int16")
    if method == "ones_like":
        return group.ones_like(name, prototype), np.ones((2, 3), dtype="int16")
    if method == "full_like":
        return group.full_like(name, prototype, fill_value=9), np.full((2, 3), 9, dtype="int16")
    raise AssertionError(f"unknown method {method}")


@pytest.mark.parametrize(
    "method",
    ["empty", "zeros", "ones", "full", "empty_like", "zeros_like", "ones_like", "full_like"],
)
@pytest.mark.parametrize("zarr_format", [2, 3])
def test_group_array_creation_helpers_create_usable_arrays_in_group_format(
    method: str, zarr_format: int
) -> None:
    """Every helper must create an array compatible with its parent group."""
    root = Group.create(MemoryStore(mode="w"), zarr_format=zarr_format)
    group = root.create_group("parent")
    prototype = group.create_array(
        "prototype",
        shape=(2, 3),
        dtype="int16",
        data=np.arange(6, dtype="int16").reshape(2, 3),
    )

    result, expected_data = _create_sync(group, method, prototype)

    assert isinstance(result, Array)
    assert result.path == f"parent/{method}_result"
    assert result.shape == (2, 3)
    assert result.dtype == np.dtype("int16")
    # A group cannot validly contain an array in a different Zarr format: its
    # own getitem implementation uses the group's format to locate child metadata.
    assert result.metadata.zarr_format == zarr_format

    reopened = group[f"{method}_result"]
    assert isinstance(reopened, Array)
    assert reopened.metadata.zarr_format == zarr_format
    if expected_data is not None:
        np.testing.assert_array_equal(reopened[:], expected_data)


async def _create_async(
    group: AsyncGroup, method: str, prototype: AsyncArray
) -> tuple[AsyncArray, np.ndarray | None]:
    name = f"{method}_result"
    if method == "empty":
        return await group.empty(name, shape=(2, 3), dtype="int16"), None
    if method == "zeros":
        return await group.zeros(name, shape=(2, 3), dtype="int16"), np.zeros((2, 3), dtype="int16")
    if method == "ones":
        return await group.ones(name, shape=(2, 3), dtype="int16"), np.ones((2, 3), dtype="int16")
    if method == "full":
        return await group.full(name, shape=(2, 3), dtype="int16", fill_value=7), np.full(
            (2, 3), 7, dtype="int16"
        )
    if method == "empty_like":
        return await group.empty_like(name, prototype), None
    if method == "zeros_like":
        return await group.zeros_like(name, prototype), np.zeros((2, 3), dtype="int16")
    if method == "ones_like":
        return await group.ones_like(name, prototype), np.ones((2, 3), dtype="int16")
    if method == "full_like":
        return await group.full_like(name, prototype, fill_value=9), np.full((2, 3), 9, dtype="int16")
    raise AssertionError(f"unknown method {method}")


@pytest.mark.parametrize(
    "method",
    ["empty", "zeros", "ones", "full", "empty_like", "zeros_like", "ones_like", "full_like"],
)
@pytest.mark.parametrize("zarr_format", [2, 3])
async def test_async_group_array_creation_helpers_use_parent_format(
    method: str, zarr_format: int
) -> None:
    """The asynchronous counterparts must have the same group-scoped behavior."""
    group = await AsyncGroup.create(MemoryStore(mode="w"), zarr_format=zarr_format)
    prototype = await group.create_array(
        "prototype",
        shape=(2, 3),
        dtype="int16",
        data=np.arange(6, dtype="int16").reshape(2, 3),
    )

    result, expected_data = await _create_async(group, method, prototype)

    assert isinstance(result, AsyncArray)
    assert result.path == f"{method}_result"
    assert result.shape == (2, 3)
    assert result.dtype == np.dtype("int16")
    assert result.metadata.zarr_format == zarr_format

    reopened = await group.getitem(f"{method}_result")
    assert isinstance(reopened, AsyncArray)
    assert reopened.metadata.zarr_format == zarr_format
    if expected_data is not None:
        np.testing.assert_array_equal(await reopened.getitem(slice(None)), expected_data)

import json

from temba_client.serialization import DatetimeField, ObjectListField, TembaObject


class NullableDatetimeRecord(TembaObject):
    created_on = DatetimeField()
    completed_on = DatetimeField()


class NullableDatetimeChild(TembaObject):
    entered_on = DatetimeField()
    exited_on = DatetimeField()


class NullableDatetimeCollection(TembaObject):
    items = ObjectListField(item_class=NullableDatetimeChild)


def test_deserialized_null_datetime_fields_serialize_back_to_json_null():
    # This mirrors receiving an API JSON response whose datetime values are null,
    # then passing the deserialized object back through the serializer.
    response_data = json.loads(
        '{"created_on": null, "completed_on": null}'
    )

    record = NullableDatetimeRecord.deserialize(response_data)
    serialized = NullableDatetimeRecord.serialize(record)

    assert serialized == {
        "created_on": None,
        "completed_on": None,
    }
    assert json.loads(json.dumps(serialized)) == response_data


def test_null_datetime_in_deserialized_object_list_serializes_as_null():
    # DatetimeField failures originally also occurred through ObjectListField,
    # which serializes each child object independently.
    response_data = json.loads(
        """
        {
            "items": [
                {"entered_on": null, "exited_on": null},
                {"entered_on": "2020-01-02T03:04:05.000000Z", "exited_on": null}
            ]
        }
        """
    )

    collection = NullableDatetimeCollection.deserialize(response_data)
    serialized = NullableDatetimeCollection.serialize(collection)

    assert serialized["items"][0] == {
        "entered_on": None,
        "exited_on": None,
    }
    assert serialized["items"][1]["exited_on"] is None
    assert serialized["items"][1]["entered_on"] == "2020-01-02T03:04:05.000000"

    # The complete result must remain valid JSON and preserve null values,
    # including those nested in a list of serialized objects.
    encoded = json.dumps(serialized)
    assert json.loads(encoded)["items"][0]["entered_on"] is None
    assert json.loads(encoded)["items"][1]["exited_on"] is None

import pandas as pd

from mesa import Model
from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.time import BaseScheduler


class ExoticParameterModel(Model):
    """Records the exotic constructor values received by ``batch_run``."""

    def __init__(self, scenario, input_data, social_network_parameters):
        super().__init__()
        self.scenario = scenario
        self.input_data = input_data
        self.social_network_parameters = social_network_parameters
        self.schedule = BaseScheduler(self)
        self.running = True
        self.datacollector = DataCollector(
            model_reporters={
                "received_scenario": "scenario",
                "data_columns": lambda model: tuple(model.input_data.columns),
                "data_rows": lambda model: len(model.input_data),
                "network_parameters": "social_network_parameters",
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def test_batch_run_sweeps_string_list_but_passes_dataframe_and_dict_as_values():
    """The issue's example must run without iterating DataFrame columns/dict keys."""
    input_data = pd.DataFrame(
        {
            "region": ["north", "south"],
            "value": [10, 20],
        }
    )
    social_network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }
    scenarios = ["baseline", "scenario1", "scenario2"]

    results = batch_run(
        ExoticParameterModel,
        {
            "scenario": scenarios,
            "input_data": input_data,
            "social_network_parameters": social_network_parameters,
        },
        number_processes=1,
        display_progress=False,
    )

    # The list of strings is the requested parameter sweep.
    assert len(results) == len(scenarios)
    assert {row["received_scenario"] for row in results} == set(scenarios)

    # The DataFrame must be received whole, rather than as its column names.
    assert {row["data_columns"] for row in results} == {("region", "value")}
    assert {row["data_rows"] for row in results} == {2}

    # The dict must be received whole, rather than as its keys.
    assert {
        tuple(sorted(row["network_parameters"].items())) for row in results
    } == {tuple(sorted(social_network_parameters.items()))}


def test_batch_run_can_sweep_dict_values_when_they_are_in_a_list():
    """A list remains a sweep even when each of its members is a dictionary."""
    parameter_values = [
        {"average_degree": 4, "rewiring_probability": 0.0},
        {"average_degree": 12, "rewiring_probability": 0.25},
    ]

    results = batch_run(
        ExoticParameterModel,
        {
            "scenario": "baseline",
            "input_data": pd.DataFrame({"value": [1]}),
            "social_network_parameters": parameter_values,
        },
        number_processes=1,
        display_progress=False,
    )

    assert len(results) == len(parameter_values)
    assert {row["received_scenario"] for row in results} == {"baseline"}
    assert {
        tuple(sorted(row["network_parameters"].items())) for row in results
    } == {tuple(sorted(value.items())) for value in parameter_values}

