import pandas as pd
import pandas.testing as pdt

from mesa import Model
from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.time import BaseScheduler


class ExoticParameterModel(Model):
    """A model requiring a DataFrame and dictionary as fixed constructor inputs."""

    def __init__(self, scenario, input_data, social_network_parameters):
        super().__init__()
        self.scenario = scenario
        self.input_data = input_data
        self.social_network_parameters = social_network_parameters

        selected = input_data.loc[input_data["scenario"] == scenario].iloc[0]
        self.selected_value = selected["value"]
        self.average_degree = social_network_parameters["average_degree"]

        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "selected_value": "selected_value",
                "average_degree": "average_degree",
            }
        )
        self.running = True

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


class DictionaryParameterModel(Model):
    """Model used to verify that dictionaries inside an explicit list can sweep."""

    def __init__(self, social_network_parameters):
        super().__init__()
        self.social_network_parameters = social_network_parameters
        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "average_degree": lambda model: model.social_network_parameters[
                    "average_degree"
                ]
            }
        )
        self.running = True

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def test_batch_run_accepts_dataframe_and_dict_as_fixed_parameters():
    input_data = pd.DataFrame(
        {
            "scenario": ["baseline", "scenario1", "scenario2"],
            "value": [10, 20, 30],
        }
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    results = batch_run(
        ExoticParameterModel,
        parameters={
            # A list is an explicit parameter sweep.
            "scenario": ["baseline", "scenario1", "scenario2"],
            # These iterable objects are each one fixed model parameter.
            "input_data": input_data,
            "social_network_parameters": network_parameters,
        },
        number_processes=1,
        data_collection_period=1,
        display_progress=False,
    )

    assert len(results) == 3
    assert {result["scenario"] for result in results} == {
        "baseline",
        "scenario1",
        "scenario2",
    }
    assert {
        result["scenario"]: result["selected_value"] for result in results
    } == {
        "baseline": 10,
        "scenario1": 20,
        "scenario2": 30,
    }

    for result in results:
        # A DataFrame must not become a sweep over column names, and a dict
        # must not become a sweep over its keys.
        pdt.assert_frame_equal(result["input_data"], input_data)
        assert result["social_network_parameters"] == network_parameters
        assert result["average_degree"] == 10


def test_batch_run_sweeps_dictionaries_when_they_are_in_an_explicit_list():
    parameter_values = [
        {"average_degree": 5, "rewiring_probability": 0.0},
        {"average_degree": 15, "rewiring_probability": 0.25},
    ]

    results = batch_run(
        DictionaryParameterModel,
        parameters={"social_network_parameters": parameter_values},
        number_processes=1,
        data_collection_period=1,
        display_progress=False,
    )

    assert len(results) == 2
    assert {result["average_degree"] for result in results} == {5, 15}
    assert {
        tuple(sorted(result["social_network_parameters"].items())) for result in results
    } == {tuple(sorted(value.items())) for value in parameter_values}

