import pandas as pd

from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.model import Model


class _OneStepSchedule:
    def __init__(self):
        self.steps = 0


class ExoticFixedParameterModel(Model):
    """Model requiring fixed values that are themselves iterable/unhashable."""

    def __init__(self, scenario, input_data, network_parameters, label):
        super().__init__()
        self.scenario = scenario
        self.input_data = input_data
        self.network_parameters = network_parameters
        self.label = label
        self.schedule = _OneStepSchedule()
        self.running = True
        self.datacollector = DataCollector(
            model_reporters={
                "scenario_seen": lambda model: model.scenario,
                "frame_first_column": lambda model: model.input_data.columns[0],
                "frame_value": lambda model: model.input_data.iloc[0, 1],
                "network_degree": lambda model: model.network_parameters[
                    "average_degree"
                ],
                "label_seen": lambda model: model.label,
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.steps += 1
        self.running = False


def test_batch_run_treats_a_single_string_parameter_as_a_single_value():
    input_data = pd.DataFrame({"scenario": ["baseline"], "value": [1]})

    results = batch_run(
        ExoticFixedParameterModel,
        parameters={"scenario": "baseline"},
        fixed_parameters={
            "input_data": input_data,
            "network_parameters": {"average_degree": 10},
            "label": "fixed label",
        },
        display_progress=False,
    )

    assert len(results) == 1
    assert results[0]["scenario_seen"] == "baseline"
    assert results[0]["label_seen"] == "fixed label"


def test_batch_run_supports_string_sweeps_and_iterable_fixed_parameters_in_parallel():
    """Fixed iterable values must not be expanded and repeats must remain grouped."""

    input_data = pd.DataFrame(
        {
            "segment": ["baseline", "scenario1", "scenario2"],
            "value": [42, 43, 44],
        }
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }
    scenarios = ["baseline", "scenario1", "scenario2"]

    results = batch_run(
        ExoticFixedParameterModel,
        parameters={"scenario": scenarios},
        fixed_parameters={
            "input_data": input_data,
            "network_parameters": network_parameters,
            "label": "constant scenario label",
        },
        iterations=2,
        number_processes=2,
        display_progress=False,
    )

    # A list of strings is a parameter sweep, while each string itself is one
    # value rather than a sequence of characters.
    assert {row["scenario_seen"] for row in results} == set(scenarios)
    assert len(results) == len(scenarios) * 2

    # Dataframes, dictionaries, and scalar strings supplied as fixed parameters
    # are passed intact instead of being expanded into columns, keys, or chars.
    assert {row["frame_first_column"] for row in results} == {"segment"}
    assert {row["frame_value"] for row in results} == {42}
    assert {row["network_degree"] for row in results} == {10}
    assert {row["label_seen"] for row in results} == {"constant scenario label"}

    # Repeated runs of a parameter combination must receive distinct iteration
    # numbers even when unhashable fixed values are copied to worker processes.
    iterations_by_scenario = {
        scenario: {
            row["iteration"]
            for row in results
            if row["scenario_seen"] == scenario
        }
        for scenario in scenarios
    }
    assert iterations_by_scenario == {
        scenario: {0, 1} for scenario in scenarios
    }

import pytest

from sqlglot import parse_one


def transpile_to_tsql(sql):
    return parse_one(sql, read="duckdb").sql(dialect="tsql")


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            "SELECT strftime(a, '%Y-%m-%d')",
            "SELECT FORMAT(a, 'yyyy-MM-dd')",
        ),
        (
            "SELECT strftime(a, CONCAT('%Y', '%m'))",
            "SELECT FORMAT(a, CONCAT('yyyy', 'MM'))",
        ),
        (
            "SELECT strftime(a, CONCAT('%Y', '-', '%m', '-', '%d'))",
            "SELECT FORMAT(a, CONCAT('yyyy', '-', 'MM', '-', 'dd'))",
        ),
    ],
)
def test_strftime_format_literals_are_translated_to_tsql(sql, expected):
    assert transpile_to_tsql(sql) == expected


@pytest.mark.parametrize(
    ("format_expression", "expected_format_expression"),
    [
        (
            "COALESCE('%Y', '%m')",
            "COALESCE('yyyy', 'MM')",
        ),
        (
            "COALESCE(format_pattern, '%Y')",
            "COALESCE(format_pattern, 'yyyy')",
        ),
        (
            "CONCAT('%Y', COALESCE('%m', '%d'))",
            "CONCAT('yyyy', COALESCE('MM', 'dd'))",
        ),
        (
            "CONCAT(COALESCE('%Y', '%y'), '-', '%m')",
            "CONCAT(COALESCE('yyyy', 'yy'), '-', 'MM')",
        ),
    ],
)
def test_strftime_recursively_translates_literals_in_complex_format_expressions(
    format_expression, expected_format_expression
):
    """
    Each runtime branch may become the FORMAT pattern, so strftime directives
    in every nested literal must be translated to T-SQL FORMAT directives.
    """
    assert (
        transpile_to_tsql(f"SELECT strftime(a, {format_expression})")
        == f"SELECT FORMAT(a, {expected_format_expression})"
    )


def test_strftime_with_dynamic_format_expression_is_preserved():
    """A non-literal format expression must not turn into the literal 'None'."""
    assert (
        transpile_to_tsql("SELECT strftime(a, format_pattern)")
        == "SELECT FORMAT(a, format_pattern)"
    )

