import ast

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


def test_for_else_search_with_conditional_break_is_allowed(assert_visitor):
    """A break makes the else represent the not-found path."""
    assert_visitor(
        ast.parse(
            '''
def find_item(items, expected):
    for item in items:
        if item == expected:
            break
    else:
        raise LookupError(expected)
''',
        ),
        UselessElseVisitor,
        [],
    )


def test_for_else_with_break_inside_try_is_allowed(assert_visitor):
    """A break may be nested in a try block and still exit the for loop."""
    assert_visitor(
        ast.parse(
            '''
def find_item(items, expected):
    for item in items:
        try:
            if item == expected:
                break
        except ValueError:
            continue
    else:
        raise LookupError(expected)
''',
        ),
        UselessElseVisitor,
        [],
    )


def test_async_for_else_search_with_conditional_break_is_allowed(
    assert_visitor,
):
    """Async for has the same break/else semantics as a regular for."""
    assert_visitor(
        ast.parse(
            '''
async def find_item(items, expected):
    async for item in items:
        if item == expected:
            break
    else:
        raise LookupError(expected)
''',
        ),
        UselessElseVisitor,
        [],
    )


def test_break_in_inner_loop_does_not_justify_outer_for_else(assert_visitor):
    """Only breaks that exit the loop owning else make that else meaningful."""
    assert_visitor(
        ast.parse(
            '''
def process(items, nested_items, condition):
    for item in items:
        if condition:
            for nested_item in nested_items:
                break
    else:
        raise LookupError(items)
''',
        ),
        UselessElseVisitor,
        [UselessReturningElseViolation],
    )

import pandas as pd

from mesa import Model
from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.time import BaseScheduler


class ExoticFixedParameterModel(Model):
    """Model requiring iterable objects as single, fixed constructor arguments."""

    def __init__(
        self,
        scenario,
        input_data,
        social_network_parameters,
        label,
        year_period,
    ):
        super().__init__()
        self.scenario = scenario
        self.input_data = input_data
        self.social_network_parameters = social_network_parameters
        self.label = label
        self.year_period = year_period
        self.running = True
        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "received_scenario": "scenario",
                "received_label": "label",
                "received_year_period": "year_period",
                "input_column_count": lambda model: len(model.input_data.columns),
                "network_degree": lambda model: model.social_network_parameters[
                    "average_degree"
                ],
                "rewiring_probability": lambda model: model.social_network_parameters[
                    "rewiring_probability"
                ],
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def test_batch_run_accepts_iterable_fixed_parameters_alongside_scenario_sweep():
    """DataFrames, dictionaries, and strings can be fixed model arguments."""
    input_data = pd.DataFrame(
        {
            "region": ["north", "south"],
            "population": [1000, 2000],
        }
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    results = batch_run(
        ExoticFixedParameterModel,
        parameters={"scenario": ["baseline", "scenario1"]},
        fixed_parameters={
            "input_data": input_data,
            "social_network_parameters": network_parameters,
            "label": "annual analysis",
            "year_period": 30,
        },
        iterations=2,
        number_processes=1,
        display_progress=False,
    )

    # Two scenario values, each run twice.  In particular, neither the
    # DataFrame's columns nor the dictionary's keys may create extra runs.
    assert len(results) == 4
    assert {row["scenario"] for row in results} == {"baseline", "scenario1"}
    assert {row["received_scenario"] for row in results} == {
        "baseline",
        "scenario1",
    }

    # The constructor must receive the original exotic objects, rather than
    # DataFrame column names, dictionary keys, or individual string letters.
    assert {row["input_column_count"] for row in results} == {2}
    assert {row["network_degree"] for row in results} == {10}
    assert {row["rewiring_probability"] for row in results} == {0.1}
    assert {row["received_label"] for row in results} == {"annual analysis"}
    assert {row["received_year_period"] for row in results} == {30}
    assert all(row["input_data"] is input_data for row in results)
    assert all(
        row["social_network_parameters"] is network_parameters for row in results
    )

    # Iterations must still be tracked correctly when fixed arguments are
    # unhashable (such as a DataFrame and a dict).
    for scenario in ("baseline", "scenario1"):
        scenario_rows = [row for row in results if row["scenario"] == scenario]
        assert sorted(row["iteration"] for row in scenario_rows) == [0, 1]

