    def __init__(self, scenario, input_data, network_parameters):
        super().__init__()
        self.scenario = scenario
        self.input_data = input_data
        self.network_parameters = network_parameters
        self.running = True
        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "model_scenario": lambda model: model.scenario,
                "data_columns": lambda model: tuple(model.input_data.columns),
                "data_rows": lambda model: len(model.input_data),
                "average_degree": lambda model: model.network_parameters[
                    "average_degree"
                ],
                "rewiring_probability": lambda model: model.network_parameters[
                    "rewiring_probability"
                ],
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


class StringParameterModel(Model):
    def __init__(self, scenario, value):
        super().__init__()
        self.scenario = scenario
        self.value = value
        self.running = True
        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "received_scenario": lambda model: model.scenario,
                "received_value": lambda model: model.value,
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def test_batch_run_keeps_dataframe_and_dict_fixed_while_sweeping_scenarios():
    """Iterable fixed values must not be expanded into dataframe columns or dict keys."""
    input_data = pd.DataFrame(
        {
            "region": ["north", "south"],
            "population": [100, 200],
        }
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    results = batch_run(
        ExoticParameterModel,
        parameters={"scenario": ["baseline", "scenario1"]},
        fixed_parameters={
            "input_data": input_data,
            "network_parameters": network_parameters,
        },
        iterations=2,
        max_steps=1,
        display_progress=False,
        number_processes=1,
    )

    # Two scenarios, each run twice.  Neither dataframe columns nor dictionary
    # keys may create additional parameter combinations.
    assert len(results) == 4
    assert {result["scenario"] for result in results} == {"baseline", "scenario1"}

    for scenario in ("baseline", "scenario1"):
        scenario_results = [r for r in results if r["scenario"] == scenario]
        assert {r["iteration"] for r in scenario_results} == {0, 1}

    for result in results:
        # The returned inputs must retain their original types and contents.
        assert isinstance(result["input_data"], pd.DataFrame)
        pd.testing.assert_frame_equal(result["input_data"], input_data)
        assert result["network_parameters"] == network_parameters

        # These values were read by the instantiated model, rather than merely
        # copied into the output dictionary by batch_run.
        assert result["model_scenario"] == result["scenario"]
        assert result["data_columns"] == ("region", "population")
        assert result["data_rows"] == 2
        assert result["average_degree"] == 10
        assert result["rewiring_probability"] == 0.1


def test_batch_run_treats_a_single_string_parameter_as_one_value():
    """A scalar string must not be swept character-by-character."""
