    code,
    assert_errors,
    default_options,
    parse_ast_tree,
):
    """
    Loop ``else`` represents the distinct case where no iteration broke.

    The conditional break may be nested in another statement, and the same
    semantics apply to both regular and asynchronous ``for`` loops.
    """
    tree = parse_ast_tree(code)
    visitor = UselessElseVisitor(default_options, tree=tree)

    visitor.run()

    assert_errors(visitor, [])


def test_break_in_nested_loop_does_not_make_outer_loop_else_meaningful(
    assert_errors,
    default_options,
    parse_ast_tree,
):
    """
