    Since the outer loop always exhausts, its ``else`` can be dedented after
    the loop and remains a WPS503 violation.
    """
    tree = parse_ast_tree("""
for outer_item in outer_items:
    if should_search(outer_item):
        for inner_item in inner_items:
            break
else:
    raise LookupError
""")
    visitor = UselessElseVisitor(default_options, tree=tree)

    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

