])
def test_search_for_else_with_conditional_break_is_not_useless(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """
    The else handles the case where the searched item was never found.

    This remains true when the conditional break is nested in a compound
    statement, and for ``async for``, whose else semantics are identical.
    """
    tree = parse_ast_tree(code)
    visitor = UselessElseVisitor(default_options, tree=tree)

    visitor.run()

