    assert_errors,
    parse_ast_tree,
    default_options,
):
    """
    A nested-loop break cannot suppress the outer loop's else clause.

    The outer else consequently always executes after iteration and remains
    removable under WPS503.
    """
    code = """
def search(groups):
    for group in groups:
        if group:
            for item in group:
                break
    else:
        raise LookupError('item was not found')
"""
    tree = parse_ast_tree(code)
    visitor = UselessElseVisitor(default_options, tree=tree)

