import ast
from collections import namedtuple

import pytest

from wemake_python_styleguide.options.config import Configuration
from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


@pytest.fixture(scope='module')
def default_options():
    """Creates default options required by AST visitors."""
    defaults = {
        option.long_option_name[2:].replace('-', '_'): option.default
        for option in Configuration._options
    }
    options_type = namedtuple('Options', defaults.keys())
    return options_type(**defaults)


def _wps503_violations(source, default_options):
    """Runs the WPS503 visitor and returns only its violations."""
    visitor = UselessElseVisitor(
        default_options,
        tree=ast.parse(source),
    )
    visitor.run()

    return [
        violation
        for violation in visitor.violations
        if isinstance(violation, UselessReturningElseViolation)
    ]


def test_for_else_with_conditional_break_and_raising_else_is_not_useless(
    default_options,
):
    """
    A break belonging to a ``for`` makes that loop's else clause meaningful.

    The else branch is only reached when none of the candidates exists.
    """
    source = '''
def resolve(search_paths, relative_path):
    for search_path in search_paths:
        candidate = search_path / relative_path
        if candidate.exists():
            break
    else:
        raise LookupError('Could not resolve path')

    return candidate
'''
    assert not _wps503_violations(source, default_options)


def test_nested_loop_break_does_not_exempt_outer_for_else(default_options):
    """
    A break only applies to its nearest enclosing loop.

    The outer loop always returns after its first iteration, irrespective of
    whether the inner loop breaks. Therefore, its ``else: return None`` is
    still a useless returning else and must produce WPS503.
    """
    source = '''
def first_batch(batches):
    for batch in batches:
        for item in batch:
            if item.is_valid():
                break
        return batch
    else:
        return None
'''
    violations = _wps503_violations(source, default_options)

    assert len(violations) == 1


def test_for_else_without_break_is_still_reported_when_both_paths_return(
    default_options,
):
    """The break exemption must not disable WPS503 for loops without breaks."""
    source = '''
def find_item(items):
    for item in items:
        if item.is_valid():
            return item
    else:
        return None
'''
    violations = _wps503_violations(source, default_options)

    assert len(violations) == 1

