def _add_broken_submodule_link(repo_path):
    # Model a checked-out repository before and after its submodule is
    # deinitialized: the tracked link remains, but its target disappears.
    submodule_dir = os.path.join(repo_path, 'vendor', 'submodule')
    os.makedirs(submodule_dir)

    link_name = 'link-into-submodule'
    link_path = os.path.join(repo_path, link_name)
    try:
        os.symlink(
            os.path.join('vendor', 'submodule', 'file-in-submodule'),
            link_path,
        )
    except OSError:
        pytest.skip('symlinks are not supported in this test environment')

    os.rmdir(submodule_dir)
    os.rmdir(os.path.dirname(submodule_dir))

    assert os.path.islink(link_path)
    assert not os.path.exists(link_path)

    subprocess.check_call(('git', 'add', link_name), cwd=repo_path)
    return link_name


