from starlette.datastructures import MutableHeaders


def test_mutable_headers_inplace_merge_with_dict_updates_in_place():
    headers = MutableHeaders()
    reference = headers

    headers |= {"X-Header": "string", "X-Other-Header": "other"}

    assert headers is reference
    assert headers.items() == [
        ("x-header", "string"),
        ("x-other-header", "other"),
    ]
