def test_mutable_headers_inplace_merge_overwrites_case_insensitively():
    headers = MutableHeaders(raw=[(b"x-header", b"old"), (b"x-header", b"duplicate")])

    headers |= {"X-HEADER": "new"}

    assert headers.items() == [("x-header", "new")]
