import numpy as np
import pennylane as qml
import pytest


def _assert_binary_mcm_counts(result, shots, observed_outcome):
    """Validate binary MCM counts, including the key-type contract."""
    assert set(result) == {0, 1}
    assert all(isinstance(key, (int, np.integer)) for key in result)
    assert all(not isinstance(key, (float, np.floating)) for key in result)
    assert int(result[observed_outcome]) == shots
    assert int(result[1 - observed_outcome]) == 0
    assert sum(int(value) for value in result.values()) == shots


@pytest.mark.parametrize(
    "prepare_one, expected_outcome",
    [(False, 0), (True, 1)],
)
def test_one_shot_counts_mcm_all_outcomes_binary_keys(prepare_one, expected_outcome):
    """One-shot MCM counts must retain both binary outcomes and integer keys."""
    shots = 11
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if prepare_one:
            qml.PauliX(0)
        measurement = qml.measure(0)
        return qml.counts(measurement, all_outcomes=True)

    _assert_binary_mcm_counts(circuit(), shots, expected_outcome)


def test_one_shot_counts_mcm_without_all_outcomes_only_returns_observed_integer_key():
    """The correction must not change normal observed-outcome counts behavior."""
    shots = 7
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(0)
        measurement = qml.measure(0)
        return qml.counts(measurement)

    result = circuit()

    assert set(result) == {1}
    key = next(iter(result))
    assert isinstance(key, (int, np.integer))
    assert not isinstance(key, (float, np.floating))
    assert int(result[1]) == shots


def test_one_shot_counts_composite_mcm_all_outcomes_uses_integer_eigenvalue_keys():
    """All outcomes of a non-binary MCM expression must use numeric eigenvalue keys."""
    shots = 8
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(0)
        first = qml.measure(0)
        second = qml.measure(1)
        return qml.counts(first + 2 * second, all_outcomes=True)

    result = circuit()

    assert set(result) == {0, 1, 2, 3}
    assert all(isinstance(key, (int, np.integer)) for key in result)
    assert all(not isinstance(key, (float, np.floating)) for key in result)
    assert {int(key): int(value) for key, value in result.items()} == {
        0: 0,
        1: shots,
        2: 0,
        3: 0,
    }


def test_one_shot_counts_multiple_mcms_all_joint_outcomes():
    """Sequences of MCMs must include all bit-string outcomes without mixed key types."""
    shots = 9
    dev = qml.device("default.qubit", wires=2, shots=shots)

    def quantum_function():
        qml.PauliX(0)
        first = qml.measure(0)
        second = qml.measure(1)
        return qml.counts([first, second], all_outcomes=True)

    deferred_result = qml.QNode(quantum_function, dev, mcm_method="deferred")()
    one_shot_result = qml.QNode(quantum_function, dev, mcm_method="one-shot")()

    expected = {"00": 0, "01": 0, "10": shots, "11": 0}

    # Deferred measurements provide the established public behavior for this
    # measurement form.
    assert {key: int(value) for key, value in deferred_result.items()} == expected

    # One-shot must implement the same all_outcomes contract. In particular,
    # it must not add integer eigval keys to bit-string count outcomes.
    assert set(one_shot_result) == set(expected)
    assert all(isinstance(key, str) for key in one_shot_result)
    assert {key: int(value) for key, value in one_shot_result.items()} == expected


def test_one_shot_counts_all_outcomes_for_every_shot_vector_partition():
    """Each one-shot shot-vector bin must independently retain missing outcomes."""
    shot_vector = [3, 5]
    dev = qml.device("default.qubit", wires=1, shots=shot_vector)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(0)
        measurement = qml.measure(0)
        return qml.counts(measurement, all_outcomes=True)

    result = circuit()

    assert isinstance(result, tuple)
    assert len(result) == len(shot_vector)
    for partition_result, shots in zip(result, shot_vector):
        _assert_binary_mcm_counts(partition_result, shots, observed_outcome=1)

