"""Regression tests for one-shot counts of mid-circuit measurements."""

import numpy as np
import pytest

import pennylane as qml


@pytest.mark.parametrize(
    "prepare_one, expected_counts",
    [
        (False, {0: 13, 1: 0}),
        (True, {0: 0, 1: 13}),
    ],
)
def test_one_shot_mcm_counts_all_outcomes_has_binary_integer_keys(
    prepare_one, expected_counts
):
    """A deterministic binary MCM must retain an unobserved outcome with count zero."""

    dev = qml.device("default.qubit", wires=1, shots=13)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if prepare_one:
            qml.PauliX(0)

        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    assert result == expected_counts
    assert all(isinstance(key, (int, np.integer)) for key in result)
    assert not any(isinstance(key, float) for key in result)
    assert sum(result.values()) == 13


def test_one_shot_mcm_counts_all_outcomes_with_shot_vector():
    """Each shot-vector partition must independently include all binary outcomes."""

    shots = (3, 5)
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    assert len(result) == len(shots)
    for counts, partition_shots in zip(result, shots):
        assert counts == {0: partition_shots, 1: 0}
        assert all(isinstance(key, (int, np.integer)) for key in counts)
        assert not any(isinstance(key, float) for key in counts)


def test_one_shot_mcm_sequence_counts_all_joint_outcomes():
    """Counts of several MCMs must include every joint outcome.

    ``qml.counts([m0, m1])`` uses bitstring keys. Consequently, completing
    unobserved outcomes must not introduce numeric keys or fail while sorting
    a mixed collection of numeric and string keys.
    """

    shots = 11
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()

    assert result == {"00": shots, "01": 0, "10": 0, "11": 0}
    assert all(isinstance(key, str) for key in result)
    assert sum(result.values()) == shots


def test_one_shot_mcm_counts_without_all_outcomes_does_not_add_zero_counts():
    """The all-outcome expansion remains opt-in for one-shot MCM counts."""

    shots = 7
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m)

    result = circuit()

    assert result == {0: shots}
    assert all(isinstance(key, (int, np.integer)) for key in result)

