def test_one_shot_mcm_counts_all_outcomes_uses_measurement_value_branches():
    """All outcomes must be those of a processed MeasurementValue."""
    shots = 20
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

