"""Regression tests for one-shot counts of mid-circuit measurements."""

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_counts(result, expected):
    """Assert count keys and values without tensor-scalar dict equality."""
    assert set(result) == set(expected)
    assert all(isinstance(key, (int, np.integer)) for key in result)
    assert all(not isinstance(key, (float, np.floating)) for key in result)
    assert {int(key): int(value) for key, value in result.items()} == expected


@pytest.mark.parametrize(
    "prepare_one, expected",
    [
        (False, {0: 10, 1: 0}),
        (True, {0: 0, 1: 10}),
    ],
)
def test_one_shot_mcm_counts_all_outcomes_include_unobserved_binary_outcome(
    prepare_one, expected
):
    """One-shot MCM counts must include both integer-valued binary outcomes."""
    dev = qml.device("default.qubit", wires=1, shots=10)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if prepare_one:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    _assert_integer_counts(circuit(), expected)


def test_one_shot_mcm_counts_without_all_outcomes_omits_unobserved_outcomes():
    """The all-outcomes fix must not alter the default observed-outcomes behavior."""
    dev = qml.device("default.qubit", wires=1, shots=10)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m)

    _assert_integer_counts(circuit(), {0: 10})


def test_one_shot_mcm_counts_all_outcomes_for_multiple_measurements():
    """All joint MCM bit-string outcomes must be present, including zero counts."""
    dev = qml.device("default.qubit", wires=2, shots=10)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()

    assert set(result) == {"00", "01", "10", "11"}
    assert {key: int(value) for key, value in result.items()} == {
        "00": 10,
        "01": 0,
        "10": 0,
        "11": 0,
    }


def test_one_shot_mcm_counts_all_outcomes_follow_measurement_value_branches():
    """Outcomes must come from the MeasurementValue branches, not raw MCM bits."""
    dev = qml.device("default.qubit", wires=1, shots=10)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

    # The possible values of ``2 * m`` are 0 and 2, even though only 0 is sampled.
    _assert_integer_counts(circuit(), {0: 10, 2: 0})


def test_one_shot_mcm_does_not_coerce_regular_counts_eigenvalues_to_integers():
    """One-shot aggregation must preserve non-integer outcomes of ordinary counts."""
    dev = qml.device("default.qubit", wires=2, shots=10)
    observable = qml.Hermitian(np.diag([0.25, 0.75]), wires=1)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.measure(0)  # activates one-shot MCM postprocessing
        return qml.counts(observable, all_outcomes=True)

    result = circuit()

    assert set(result) == {0.25, 0.75}
    assert {key: int(value) for key, value in result.items()} == {0.25: 10, 0.75: 0}

