"""Regression tests for counts of mid-circuit measurements in one-shot mode."""

from numbers import Integral

import pytest

import pennylane as qml


def _assert_counts(result, expected, shots):
    """Assert a counts result has the expected labels, values, and total shots."""
    assert set(result) == set(expected)
    assert {outcome: int(count) for outcome, count in result.items()} == expected
    assert sum(int(count) for count in result.values()) == shots


@pytest.mark.parametrize(
    "prepare_one, expected",
    [
        (False, {0: 10, 1: 0}),
        (True, {0: 0, 1: 10}),
    ],
)
def test_one_shot_mcm_counts_all_outcomes_includes_unobserved_binary_outcome(
    prepare_one, expected
):
    """One-shot counts must retain both MCM outcomes, including a zero-count one."""
    dev = qml.device("default.qubit", wires=1, shots=10)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if prepare_one:
            qml.PauliX(0)
        measurement = qml.measure(0)
        return qml.counts(measurement, all_outcomes=True)

    result = circuit()

    assert all(isinstance(outcome, Integral) and not isinstance(outcome, bool) for outcome in result)
    _assert_counts(result, expected, shots=10)


def test_one_shot_mcm_counts_all_outcomes_uses_measurement_value_branches():
    """All outcomes must be the possible values of an MCM expression."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        measurement = qml.measure(0)
        return qml.counts(2 * measurement + 3, all_outcomes=True)

    # The possible values of 2*m + 3 are 3 and 5. Since m is deterministically
    # zero, 5 is unobserved but must still be represented. In particular, the
    # underlying binary MCM labels 0 and 1 are not outcomes of this measurement.
    result = circuit()

    assert all(isinstance(outcome, Integral) and not isinstance(outcome, bool) for outcome in result)
    _assert_counts(result, {3: shots, 5: 0}, shots=shots)


def test_one_shot_mcm_counts_all_outcomes_for_measurement_value_list():
    """One-shot counts of a list of MCMs must include every bit-string outcome."""
    shots = 10
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        measurement_0 = qml.measure(0)
        measurement_1 = qml.measure(1)
        return qml.counts([measurement_0, measurement_1], all_outcomes=True)

    _assert_counts(
        circuit(),
        {"00": shots, "01": 0, "10": 0, "11": 0},
        shots=shots,
    )


def test_one_shot_mcm_counts_without_all_outcomes_only_returns_observed_outcomes():
    """The all-outcomes behavior must not be enabled when it was not requested."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        measurement = qml.measure(0)
        return qml.counts(measurement)

    result = circuit()

    assert all(isinstance(outcome, Integral) and not isinstance(outcome, bool) for outcome in result)
    _assert_counts(result, {0: shots}, shots=shots)


def test_one_shot_mcm_counts_all_outcomes_with_shot_vector():
    """Every shot-vector partition must independently retain all MCM outcomes."""
    shot_bins = (3, 7)
    dev = qml.device("default.qubit", wires=1, shots=shot_bins)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        measurement = qml.measure(0)
        return qml.counts(measurement, all_outcomes=True)

    results = circuit()

    assert len(results) == len(shot_bins)
    for result, shots in zip(results, shot_bins):
        _assert_counts(result, {0: shots, 1: 0}, shots=shots)

