from pathlib import Path

import pytest

from borgstore.backends.errors import ObjectNotFound
from borgstore.backends.posixfs import PosixFS
from borgstore.backends.sftp import Sftp


@pytest.fixture()
def posix_backend(tmp_path):
    backend = PosixFS(tmp_path / "store")
    backend.create()
    backend.open()
    try:
        yield backend
    finally:
        if backend.opened:
            backend.close()
        backend.destroy()


class FakeSFTPFile:
    def __init__(self, client, name):
        self.client = client
        self.name = name
        self.value = b""

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is None:
            self.client.files[self.name] = self.value

    def set_pipelined(self, enabled):
        pass

    def write(self, value):
        self.value += value


class FakeSFTPClient:
    """Minimal in-memory SFTP client; no real server/network is needed."""

    def __init__(self):
        self.directories = {"."}
        self.files = {}
        self.events = []

    def open(self, name, mode="r"):
        self.events.append(("open", name))
        if str(Path(name).parent) not in self.directories:
            raise FileNotFoundError(name)
        return FakeSFTPFile(self, name)

    def mkdir(self, name):
        self.events.append(("mkdir", name))
        parent = str(Path(name).parent)
        if parent not in self.directories:
            raise FileNotFoundError(name)
        if name in self.directories:
            raise OSError("already exists")
        self.directories.add(name)

    def posix_rename(self, source, destination):
        self.events.append(("rename", source, destination))
        if source not in self.files:
            raise FileNotFoundError(source)
        if str(Path(destination).parent) not in self.directories:
            raise FileNotFoundError(destination)
        self.files[destination] = self.files.pop(source)

    def unlink(self, name):
        self.events.append(("unlink", name))
        del self.files[name]


def make_sftp_backend():
    # Avoid Sftp.__init__ and connection setup: this is intentionally offline.
    backend = object.__new__(Sftp)
    backend.opened = True
    backend.client = FakeSFTPClient()
    return backend


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_posix_store_recovers_when_a_nesting_directory_was_not_precreated(posix_backend, precreate_dirs):
    """
    Precreating directories is optional.  In particular, stores configured to
    precreate them must still work if a directory was never created or was lost.
    """
    posix_backend.precreate_dirs = precreate_dirs

    posix_backend.store("data/ab/cd/object", b"payload")

    assert posix_backend.load("data/ab/cd/object") == b"payload"


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_posix_move_recovers_when_destination_nesting_directory_is_missing(posix_backend, precreate_dirs):
    posix_backend.precreate_dirs = precreate_dirs
    posix_backend.mkdir("data/old")
    posix_backend.store("data/old/object", b"payload")

    posix_backend.move("data/old/object", "data/new/deeper/object")

    assert not posix_backend.info("data/old/object").exists
    assert posix_backend.load("data/new/deeper/object") == b"payload"


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_store_retries_after_creating_a_missing_nesting_directory(precreate_dirs):
    backend = make_sftp_backend()
    backend.precreate_dirs = precreate_dirs

    backend.store("data/ab/cd/object", b"payload")

    assert backend.client.files["data/ab/cd/object"] == b"payload"
    assert "data/ab/cd" in backend.client.directories

    # The first operation is the latency-saving direct write attempt. mkdir is
    # only performed after that operation reports the missing directory.
    assert backend.client.events[0][0] == "open"
    assert any(event[0] == "mkdir" for event in backend.client.events)


def test_sftp_store_does_not_mkdir_for_an_existing_nesting_directory():
    backend = make_sftp_backend()
    backend.precreate_dirs = True
    backend.client.directories.update({"data", "data/ab"})

    backend.store("data/ab/object", b"payload")

    assert backend.client.files["data/ab/object"] == b"payload"
    assert not [event for event in backend.client.events if event[0] == "mkdir"]


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_move_retries_after_creating_missing_destination_nesting_directory(precreate_dirs):
    backend = make_sftp_backend()
    backend.precreate_dirs = precreate_dirs
    backend.client.directories.update({"data", "data/old"})
    backend.client.files["data/old/object"] = b"payload"

    backend.move("data/old/object", "data/new/deeper/object")

    assert "data/old/object" not in backend.client.files
    assert backend.client.files["data/new/deeper/object"] == b"payload"
    assert "data/new/deeper" in backend.client.directories
    assert backend.client.events[0][0] == "rename"
    assert any(event[0] == "mkdir" for event in backend.client.events)


@pytest.mark.parametrize("backend_kind", ["posix", "sftp"])
def test_move_of_a_missing_source_still_raises_object_not_found(backend_kind, posix_backend):
    """
    Retrying after FileNotFoundError must not leak a raw FileNotFoundError when
    it was the source object, rather than the destination directory, that was
    absent.
    """
    if backend_kind == "posix":
        backend = posix_backend
        backend.precreate_dirs = True
    else:
        backend = make_sftp_backend()
        backend.precreate_dirs = True

    with pytest.raises(ObjectNotFound):
        backend.move("data/old/missing", "data/new/object")

