def _fake_sftp_backend(precreate_dirs):
    backend = object.__new__(Sftp)
    backend.opened = True
    backend.precreate_dirs = precreate_dirs
    backend.client = _FakeSFTPClient()

    mkdir_calls = []

    def mkdir(name, *, parents=False, exist_ok=False):
        mkdir_calls.append(name)
        current = Path()
        for component in Path(name).parts:
            if component not in ("", ".", "/"):
                current /= component
                backend.client.dirs.add(str(current))

    backend._mkdir = mkdir
    return backend, mkdir_calls


def _opened_posix_backend(tmp_path, precreate_dirs):
    backend = PosixFS(tmp_path / "store")
    backend.precreate_dirs = precreate_dirs
    backend.create()
    backend.open()
    return backend


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_posix_store_recovers_when_a_nesting_directory_is_missing(tmp_path, precreate_dirs):
    """Missing/lost nesting dirs must not prevent writing an object."""
    backend = _opened_posix_backend(tmp_path, precreate_dirs)
    try:
        backend.store("data/aa/object", b"value")

        assert backend.load("data/aa/object") == b"value"
        assert (backend.base_path / "data" / "aa").is_dir()
    finally:
        backend.close()
        backend.destroy()


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_posix_move_recovers_when_destination_nesting_directory_is_missing(tmp_path, precreate_dirs):
    backend = _opened_posix_backend(tmp_path, precreate_dirs)
    try:
        backend.mkdir("source")
        backend.store("source/object", b"value")

        backend.move("source/object", "data/bb/object")

        assert not backend.info("source/object").exists
        assert backend.load("data/bb/object") == b"value"
    finally:
        backend.close()
        backend.destroy()


def test_posix_move_missing_source_still_reports_object_not_found(tmp_path):
    backend = _opened_posix_backend(tmp_path, precreate_dirs=False)
    try:
        # Since the destination parent exists, a missing-path error is
        # unambiguously an absent source object.
        backend.mkdir("destination")

        with pytest.raises(ObjectNotFound):
            backend.move("missing/object", "destination/object")
    finally:
        backend.close()
        backend.destroy()


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_store_recovers_when_a_nesting_directory_is_missing(precreate_dirs):
    backend, mkdir_calls = _fake_sftp_backend(precreate_dirs)

    backend.store("data/aa/object", b"value")

    assert backend.client.files["data/aa/object"] == b"value"
    assert mkdir_calls == ["data/aa"]


def test_sftp_store_does_not_mkdir_when_nesting_directory_already_exists():
    backend, _mkdir_calls = _fake_sftp_backend(precreate_dirs=True)
    backend.client.dirs.update({"data", "data/aa"})

    def mkdir_must_not_be_called(*args, **kwargs):
        raise AssertionError("existing nesting directories must not be created again")

    backend._mkdir = mkdir_must_not_be_called

    backend.store("data/aa/object", b"value")

    assert backend.client.files["data/aa/object"] == b"value"


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_move_recovers_when_destination_nesting_directory_is_missing(precreate_dirs):
    backend, mkdir_calls = _fake_sftp_backend(precreate_dirs)
    backend.client.dirs.add("source")
    backend.client.files["source/object"] = b"value"

    backend.move("source/object", "data/bb/object")

    assert "source/object" not in backend.client.files
    assert backend.client.files["data/bb/object"] == b"value"
    assert mkdir_calls == ["data/bb"]


def test_sftp_move_missing_source_still_reports_object_not_found():
    backend, _mkdir_calls = _fake_sftp_backend(precreate_dirs=False)
    backend.client.dirs.add("destination")

    with pytest.raises(ObjectNotFound):
        backend.move("missing/object", "destination/object")

import pytest

import hashin


@pytest.mark.parametrize(
    ("python_version", "expected_identifiers"),
    [
        (
            "3.10",
            {
                "3.10",
                "cp310",
                "py3",
                "py3.10",
                "py310",
                "source",
                "py2.py3",
            },
        ),
        (
            # Python minor versions must not be artificially limited to two
            # digits. This also follows the issue's suggested \d*\d pattern.
            "3.100",
            {
                "3.100",
                "cp3100",
                "py3",
                "py3.100",
                "py3100",
                "source",
                "py2.py3",
            },
        ),
    ],
)
def test_expand_python_version_expands_multi_digit_minor_versions(
    python_version, expected_identifiers
):
    assert hashin.expand_python_version(python_version) == expected_identifiers


@pytest.mark.parametrize(
    ("python_version", "wheel_python_tag"),
    [
        ("3.10", "cp310"),
        ("3.100", "cp3100"),
    ],
)
def test_python_version_filter_selects_wheel_for_multi_digit_minor_version(
    python_version, wheel_python_tag
):
    """The release-filtering behavior must use expanded Python wheel tags."""
    data = {
        "info": {"name": "example-package"},
        "releases": {
            "1.0": [
                {
                    "url": (
                        "https://example.invalid/files/"
                        "example-package-1.0-{}-none-any.whl".format(
                            wheel_python_tag
                        )
                    ),
                    "digests": {"sha256": "matching-hash"},
                },
                {
                    "url": (
                        "https://example.invalid/files/"
                        "example-package-1.0-cp39-none-any.whl"
                    ),
                    "digests": {"sha256": "other-hash"},
                },
            ]
        },
    }

    result = hashin.get_package_hashes(
        package="example-package",
        version="1.0",
        python_versions=(python_version,),
        lookup_memory={"example-package": data},
    )

    assert result == {
        "package": "example-package",
        "version": "1.0",
        "hashes": [{"hash": "matching-hash"}],
    }


@pytest.mark.parametrize("version", ["3.", "3.a", "3.10.1", "py3.10"])
def test_expand_python_version_leaves_non_major_minor_values_unchanged(version):
    assert hashin.expand_python_version(version) == [version]

import pytest

import hashin


@pytest.mark.parametrize(
    ("version", "expected"),
    [
        (
            "3.10",
            {
                "3.10",
                "cp310",
                "py3",
                "py3.10",
                "py310",
                "source",
                "py2.py3",
            },
        ),
        (
            # The issue's proposed regex intentionally permits arbitrary-length
            # minor components, so future Python versions must not silently
            # stop receiving their compatible wheel tags.
            "3.100",
            {
                "3.100",
                "cp3100",
                "py3",
                "py3.100",
                "py3100",
                "source",
                "py2.py3",
            },
        ),
    ],
)
def test_expand_python_version_expands_multi_digit_minor_versions(version, expected):
    assert set(hashin.expand_python_version(version)) == expected


@pytest.mark.parametrize(
    ("python_version", "wheel_tag"),
    [
        ("3.10", "cp310"),
        ("3.100", "cp3100"),
    ],
)
def test_python_version_filter_finds_wheels_for_multi_digit_minor_versions(
    monkeypatch, python_version, wheel_tag
):
    release = {
        "url": (
            "https://packages.example.invalid/example-1.0-"
            f"{wheel_tag}-{wheel_tag}-manylinux_2_17_x86_64.whl"
        ),
        "digests": {"sha256": "wheel-hash"},
    }
    package_data = {
        "info": {"name": "example"},
        "releases": {"1.0": [release]},
    }

    monkeypatch.setattr(
        hashin,
        "get_package_data",
        lambda package, index_url, verbose=False: package_data,
    )

    assert hashin.get_package_hashes(
        "example",
        version="1.0",
        python_versions=[python_version],
        algorithm="sha256",
        index_url="https://packages.example.invalid/",
    ) == {
        "package": "example",
        "version": "1.0",
        "hashes": [{"hash": "wheel-hash"}],
    }
